insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','dt',1,1,'Estas são as palavras que Moisés falou a todo o Israel além do Jordão, no deserto, na planície defronte do Mar Vermelho, entre Parã e Tôfel, e Labã, e Hazerote, e Di-Zaabe.'),
('acf','dt',1,2,'Onze jornadas há desde Horebe, caminho do monte Seir, até Cades-Barnéia.'),
('acf','dt',1,3,'E sucedeu que, no ano quadragésimo, no mês undécimo, no primeiro dia do mês, Moisés falou aos filhos de Israel, conforme a tudo o que o Senhor lhe mandara acerca deles.'),
('acf','dt',1,4,'Depois que feriu a Siom, rei dos amorreus, que habitava em Hesbom, e a Ogue, rei de Basã, que habitava em Astarote, em Edrei.'),
('acf','dt',1,5,'Além do Jordão, na terra de Moabe, começou Moisés a declarar esta lei, dizendo:'),
('acf','dt',1,6,'O Senhor nosso Deus nos falou em Horebe, dizendo: Assaz vos haveis demorado neste monte.'),
('acf','dt',1,7,'Voltai-vos, e parti, e ide à montanha dos amorreus, e a todos os seus vizinhos, à planície, e à montanha, e ao vale, e ao sul, e à margem do mar; à terra dos cananeus, e ao Líbano, até ao grande rio, o rio Eufrates.'),
('acf','dt',1,8,'Eis que tenho posto esta terra diante de vós; entrai e possuí a terra que o Senhor jurou a vossos pais, Abraão, Isaque e Jacó, que a daria a eles e à sua descendência depois deles.'),
('acf','dt',1,9,'E no mesmo tempo eu vos falei, dizendo: Eu sozinho não poderei levar-vos.'),
('acf','dt',1,10,'O Senhor vosso Deus já vos tem multiplicado; e eis que em multidão sois hoje como as estrelas do céu.'),
('acf','dt',1,11,'O Senhor Deus de vossos pais vos aumente, ainda mil vezes mais do que sois; e vos abençoe, como vos tem falado.'),
('acf','dt',1,12,'Como suportaria eu sozinho os vossos fardos, e as vossas cargas, e as vossas contendas?'),
('acf','dt',1,13,'Tomai-vos homens sábios e entendidos, experimentados entre as vossas tribos, para que os ponha por chefes sobre vós.'),
('acf','dt',1,14,'Então vós me respondestes, e dissestes: Bom é fazer o que tens falado.'),
('acf','dt',1,15,'Tomei, pois, os chefes de vossas tribos, homens sábios e experimentados, e os tenho posto por cabeças sobre vós, por capitães de milhares, e por capitães de cem, e por capitães de cinqüenta, e por capitães de dez, e por governadores das vossas tribos.'),
('acf','dt',1,16,'E no mesmo tempo mandei a vossos juízes, dizendo: Ouvi a causa entre vossos irmãos, e julgai justamente entre o homem e seu irmão, e entre o estrangeiro que está com ele.'),
('acf','dt',1,17,'Não discriminareis as pessoas em juízo; ouvireis assim o pequeno como o grande; não temereis a face de ninguém, porque o juízo é de Deus; porém a causa que vos for difícil fareis vir a mim, e eu a ouvirei.'),
('acf','dt',1,18,'Assim naquele tempo vos ordenei todas as coisas que havíeis de fazer.'),
('acf','dt',1,19,'Então partimos de Horebe, e caminhamos por todo aquele grande e tremendo deserto que vistes, pelo caminho das montanhas dos amorreus, como o Senhor nosso Deus nos ordenara; e chegamos a Cades-Barnéia.'),
('acf','dt',1,20,'Então eu vos disse: Chegados sois às montanhas dos amorreus, que o Senhor nosso Deus nos dá.'),
('acf','dt',1,21,'Eis aqui o Senhor teu Deus tem posto esta terra diante de ti; sobe, toma posse dela, como te falou o Senhor Deus de teus pais; não temas, e não te assustes.'),
('acf','dt',1,22,'Então todos vós chegastes a mim, e dissestes: Mandemos homens adiante de nós, para que nos espiem a terra e, de volta, nos ensinem o caminho pelo qual devemos subir, e as cidades a que devemos ir.'),
('acf','dt',1,23,'Isto me pareceu bem; de modo que de vós tomei doze homens, de cada tribo um homem.'),
('acf','dt',1,24,'E foram-se, e subiram à montanha, e chegaram até ao vale de Escol, e o espiaram.'),
('acf','dt',1,25,'E tomaram do fruto da terra nas suas mãos, e no-lo trouxeram e nos informaram, dizendo: Boa é a terra que nos dá o Senhor nosso Deus.'),
('acf','dt',1,26,'Porém vós não quisestes subir; mas fostes rebeldes ao mandado do Senhor nosso Deus.'),
('acf','dt',1,27,'E murmurastes nas vossas tendas, e dissestes: Porquanto o Senhor nos odeia, nos tirou da terra do Egito para nos entregar nas mãos dos amorreus, para destruir-nos.'),
('acf','dt',1,28,'Para onde subiremos? Nossos irmãos fizeram com que se derretesse o nosso coração, dizendo: Maior e mais alto é este povo do que nós, as cidades são grandes e fortificadas até aos céus; e também vimos ali filhos dos gigantes.'),
('acf','dt',1,29,'Então eu vos disse: Não vos espanteis, nem os temais.'),
('acf','dt',1,30,'O Senhor vosso Deus que vai adiante de vós, ele pelejará por vós, conforme a tudo o que fez convosco, diante de vossos olhos, no Egito;'),
('acf','dt',1,31,'Como também no deserto, onde vistes que o Senhor vosso Deus nele vos levou, como um homem leva seu filho, por todo o caminho que andastes, até chegardes a este lugar.'),
('acf','dt',1,32,'Mas nem por isso crestes no Senhor vosso Deus.'),
('acf','dt',1,33,'Que foi adiante de vós por todo o caminho, para vos achar o lugar onde vós deveríeis acampar; de noite no fogo, para vos mostrar o caminho por onde havíeis de andar, e de dia na nuvem.'),
('acf','dt',1,34,'Ouvindo, pois, o Senhor a voz das vossas palavras, indignou-se, e jurou, dizendo:'),
('acf','dt',1,35,'Nenhum dos homens desta maligna geração verá esta boa terra que jurei dar a vossos pais.'),
('acf','dt',1,36,'Salvo Calebe, filho de Jefoné; ele a verá, e a terra que pisou darei a ele e a seus filhos; porquanto perseverou em seguir ao Senhor.'),
('acf','dt',1,37,'Também o Senhor se indignou contra mim por causa de vós, dizendo: Também tu lá não entrarás.'),
('acf','dt',1,38,'Josué, filho de Num, que está diante de ti, ele ali entrará; fortalece-o, porque ele a fará herdar a Israel.'),
('acf','dt',1,39,'E vossos meninos, de quem dissestes: Por presa serão; e vossos filhos, que hoje não conhecem nem o bem nem o mal, eles ali entrarão, e a eles a darei, e eles a possuirão.'),
('acf','dt',1,40,'Porém vós virai-vos, e parti para o deserto, pelo caminho do Mar Vermelho.'),
('acf','dt',1,41,'Então respondestes, e me dissestes: Pecamos contra o Senhor; nós subiremos e pelejaremos, conforme a tudo o que nos ordenou o Senhor nosso Deus. E armastes-vos, cada um de vós, dos seus instrumentos de guerra, e estivestes prestes para subir à montanha.'),
('acf','dt',1,42,'E disse-me o Senhor: Dize-lhes: Não subais nem pelejeis, pois não estou no meio de vós; para que não sejais feridos diante de vossos inimigos.'),
('acf','dt',1,43,'Porém, falando-vos eu, não ouvistes; antes fostes rebeldes ao mandado do Senhor, e vos ensoberbecestes, e subistes à montanha.'),
('acf','dt',1,44,'E os amorreus, que habitavam naquela montanha, vos saíram ao encontro; e perseguiram-vos como fazem as abelhas e vos derrotaram desde Seir até Hormá.'),
('acf','dt',1,45,'Tornando, pois, vós, e chorando perante o Senhor, o Senhor não ouviu a vossa voz, nem vos escutou.'),
('acf','dt',1,46,'Assim permanecestes muitos dias em Cades, pois ali vos demorastes muito.'),
('acf','dt',2,1,'Depois viramo-nos, e caminhamos ao deserto, caminho do Mar Vermelho, como o SENHOR me tinha dito, e muitos dias rodeamos o monte Seir.'),
('acf','dt',2,2,'Então o Senhor me falou, dizendo:'),
('acf','dt',2,3,'Tendes rodeado bastante esta montanha; virai-vos para o norte.'),
('acf','dt',2,4,'E dá ordem ao povo, dizendo: Passareis pelos termos de vossos irmãos, os filhos de Esaú, que habitam em Seir; e eles terão medo de vós; porém guardai-vos bem.'),
('acf','dt',2,5,'Não vos envolvais com eles, porque não vos darei da sua terra nem ainda a pisada da planta de um pé; porquanto a Esaú tenho dado o monte Seir por herança.'),
('acf','dt',2,6,'Comprareis deles, por dinheiro, comida para comerdes; e também água para beber deles comprareis por dinheiro.'),
('acf','dt',2,7,'Pois o Senhor teu Deus te abençoou em toda a obra das tuas mãos; ele sabe que andas por este grande deserto; estes quarenta anos o Senhor teu Deus esteve contigo, coisa nenhuma te faltou.'),
('acf','dt',2,8,'Passando, pois, por nossos irmãos, os filhos de Esaú, que habitavam em Seir, desde o caminho da planície de Elate e de Eziom-Geber, nos viramos e passamos o caminho do deserto de Moabe.'),
('acf','dt',2,9,'Então o Senhor me disse: Não molestes aos de Moabe, e não contendas com eles em peleja, porque não te darei herança da sua terra; porquanto tenho dado a Ar por herança aos filhos de Ló.'),
('acf','dt',2,10,'(Os emins dantes habitaram nela; um povo grande e numeroso, e alto como os gigantes.'),
('acf','dt',2,11,'Também estes foram considerados gigantes como os anaquins; e os moabitas os chamavam emins.'),
('acf','dt',2,12,'Outrora os horeus também habitaram em Seir; porém os filhos de Esaú os lançaram fora, e os destruíram de diante de si, e habitaram no seu lugar, assim como Israel fez à terra da sua herança, que o Senhor lhes tinha dado).'),
('acf','dt',2,13,'Levantai-vos agora, e passai o ribeiro de Zerede. Assim passamos o ribeiro de Zerede.'),
('acf','dt',2,14,'E os dias que caminhamos, desde Cades-Barnéia até que passamos o ribeiro de Zerede, foram trinta e oito anos, até que toda aquela geração dos homens de guerra se consumiu do meio do arraial, como o Senhor lhes jurara.'),
('acf','dt',2,15,'Assim também foi contra eles a mão do Senhor, para os destruir do meio do arraial até os haver consumido.'),
('acf','dt',2,16,'E sucedeu que, sendo já consumidos todos os homens de guerra, pela morte, do meio do povo,'),
('acf','dt',2,17,'O Senhor me falou, dizendo:'),
('acf','dt',2,18,'Hoje passarás a Ar, pelos termos de Moabe;'),
('acf','dt',2,19,'E chegando até defronte dos filhos de Amom, não os molestes, e com eles não contendas; porque da terra dos filhos de Amom não te darei herança, porquanto aos filhos de Ló a tenho dado por herança.'),
('acf','dt',2,20,'(Também essa foi considerada terra de gigantes; antes nela habitavam gigantes, e os amonitas os chamavam zamzumins;'),
('acf','dt',2,21,'Um povo grande, e numeroso, e alto, como os gigantes; e o Senhor os destruiu de diante dos amonitas, e estes os lançaram fora, e habitaram no seu lugar;'),
('acf','dt',2,22,'Assim como fez com os filhos de Esaú, que habitavam em Seir, de diante dos quais destruiu os horeus, e eles os lançaram fora, e habitaram no lugar deles até este dia;'),
('acf','dt',2,23,'Também os caftorins, que saíram de Caftor, destruíram os aveus, que habitavam em Cazerim até Gaza, e habitaram no lugar deles).'),
('acf','dt',2,24,'Levantai-vos, parti e passai o ribeiro de Arnom; eis aqui na tua mão tenho dado a Siom, amorreu, rei de Hesbom, e a sua terra; começa a possuí-la, e contende com eles em peleja.'),
('acf','dt',2,25,'Neste dia começarei a pôr um terror e um medo de ti diante dos povos que estão debaixo de todo o céu; os que ouvirem a tua fama tremerão diante de ti e se angustiarão.'),
('acf','dt',2,26,'Então mandei mensageiros desde o deserto de Quedemote a Siom, rei de Hesbom, com palavras de paz, dizendo:'),
('acf','dt',2,27,'Deixa-me passar pela tua terra; somente pela estrada irei; não me desviarei para a direita nem para a esquerda.'),
('acf','dt',2,28,'A comida, para que eu coma, vender-me-ás por dinheiro, e dar-me-ás por dinheiro a água para que eu beba; tão-somente deixa-me passar a pé;'),
('acf','dt',2,29,'Como fizeram comigo os filhos de Esaú, que habitam em Seir, e os moabitas que habitam em Ar; até que eu passe o Jordão, à terra que o Senhor nosso Deus nos há de dar.'),
('acf','dt',2,30,'Mas Siom, rei de Hesbom, não nos quis deixar passar por sua terra, porquanto o Senhor teu Deus endurecera o seu espírito, e fizera obstinado o seu coração para to dar na tua mão, como hoje se vê.'),
('acf','dt',2,31,'E o Senhor me disse: Eis aqui, tenho começado a dar-te Siom, e a sua terra; começa, pois, a possuí-la para que herdes a sua terra.'),
('acf','dt',2,32,'E Siom saiu-nos ao encontro, ele e todo o seu povo, à peleja, em Jaza;'),
('acf','dt',2,33,'E o Senhor nosso Deus no-lo entregou, e o ferimos a ele, e a seus filhos, e a todo o seu povo.'),
('acf','dt',2,34,'E naquele tempo tomamos todas as suas cidades, e cada uma destruímos com os seus homens, mulheres e crianças; não deixamos a ninguém.'),
('acf','dt',2,35,'Somente tomamos por presa o gado para nós, e o despojo das cidades que tínhamos tomado.'),
('acf','dt',2,36,'Desde Aroer, que está à margem do ribeiro de Arnom, e a cidade que está junto ao ribeiro, até Gileade, nenhuma cidade houve que de nós escapasse; tudo isto o Senhor nosso Deus nos entregou.'),
('acf','dt',2,37,'Somente à terra dos filhos de Amom não chegastes; nem a toda a margem do ribeiro de Jaboque, nem às cidades da montanha, nem a coisa alguma que nos proibira o Senhor nosso Deus.'),
('acf','dt',3,1,'Depois nos viramos e subimos o caminho de Basã; e Ogue, rei de Basã, nos saiu ao encontro, ele e todo o seu povo, à peleja em Edrei.'),
('acf','dt',3,2,'Então o Senhor me disse: Não o temas, porque a ele e a todo o seu povo, e a sua terra, tenho dado na tua mão; e far-lhe-ás como fizeste a Siom, rei dos amorreus, que habitava em Hesbom.'),
('acf','dt',3,3,'E também o Senhor nosso Deus nos deu na nossa mão a Ogue, rei de Basã, e a todo o seu povo; de maneira que o ferimos até que não lhe ficou sobrevivente algum.'),
('acf','dt',3,4,'E naquele tempo tomamos todas as suas cidades; nenhuma cidade houve que lhes não tomássemos; sessenta cidades, toda a região de Argobe, o reino de Ogue em Basã.'),
('acf','dt',3,5,'Todas estas cidades eram fortificadas com altos muros, portas e ferrolhos; e muitas outras cidades sem muros.'),
('acf','dt',3,6,'E destruímo-las como fizemos a Siom, rei de Hesbom, destruindo todas as cidades, homens, mulheres e crianças.'),
('acf','dt',3,7,'Porém todo o gado, e o despojo das cidades, tomamos para nós por presa.'),
('acf','dt',3,8,'Assim naquele tempo tomamos a terra das mãos daqueles dois reis dos amorreus, que estavam além do Jordão; desde o rio de Arnom, até ao monte de Hermom'),
('acf','dt',3,9,'(A Hermom os sidônios chamam Siriom; porém os amorreus o chamam Senir);'),
('acf','dt',3,10,'Todas as cidades do planalto, e todo o Gileade, e todo o Basã, até Salcá e Edrei, cidades do reino de Ogue em Basã.'),
('acf','dt',3,11,'Porque só Ogue, o rei de Basã, restou dos gigantes; eis que o seu leito, um leito de ferro, não está porventura em Rabá dos filhos de Amom? De nove côvados, o seu comprimento, e de quatro côvados, a sua largura, pelo côvado comum.'),
('acf','dt',3,12,'Tomamos, pois, esta terra em possessão naquele tempo: Desde Aroer, que está junto ao ribeiro de Arnom, e a metade da montanha de Gileade, com as suas cidades, tenho dado aos rubenitas e gaditas.'),
('acf','dt',3,13,'E o restante de Gileade, como também todo o Basã, o reino de Ogue, dei à meia tribo de Manassés; toda aquela região de Argobe, por todo o Basã, se chamava a terra dos gigantes.'),
('acf','dt',3,14,'Jair, filho de Manassés, alcançou toda a região de Argobe, até ao termo dos gesuritas, e maacatitas, e a chamou de seu nome, Havote-Jair até este dia.'),
('acf','dt',3,15,'E a Maquir dei Gileade.'),
('acf','dt',3,16,'Mas aos rubenitas e gaditas dei desde Gileade até ao ribeiro de Arnom, cujo meio serve de limite; e até ao ribeiro de Jaboque, o termo dos filhos de Amom.'),
('acf','dt',3,17,'Como também a campina, e o Jordão por termo; desde Quinerete até ao mar da campina, o Mar Salgado, abaixo de Asdote-Pisga para o oriente.'),
('acf','dt',3,18,'E no mesmo tempo vos ordenei, dizendo: O Senhor vosso Deus vos deu esta terra, para possuí-la; passai, pois, armados vós, todos os homens valentes, diante de vossos irmãos, os filhos de Israel.'),
('acf','dt',3,19,'Tão-somente vossas mulheres, e vossas crianças, e vosso gado (porque eu sei que tendes muito gado), ficarão nas vossas cidades, que já vos tenho dado.'),
('acf','dt',3,20,'Até que o Senhor dê descanso a vossos irmãos como a vós; para que eles herdem também a terra que o Senhor vosso Deus lhes há de dar além do Jordão; então voltareis cada qual à sua herança que já vos tenho dado.'),
('acf','dt',3,21,'Também dei ordem a Josué no mesmo tempo, dizendo: Os teus olhos têm visto tudo o que o Senhor vosso Deus tem feito a estes dois reis; assim fará o Senhor a todos os reinos, a que tu passarás.'),
('acf','dt',3,22,'Não os temais, porque o Senhor vosso Deus é o que peleja por vós.'),
('acf','dt',3,23,'Também eu pedi graça ao Senhor no mesmo tempo, dizendo:'),
('acf','dt',3,24,'Senhor DEUS! já começaste a mostrar ao teu servo a tua grandeza e a tua forte mão; pois, que Deus há nos céus e na terra, que possa fazer segundo as tuas obras, e segundo os teus grandes feitos?'),
('acf','dt',3,25,'Rogo-te que me deixes passar, para que veja esta boa terra que está além do Jordão; esta boa montanha, e o Líbano!'),
('acf','dt',3,26,'Porém o Senhor indignou-se muito contra mim por causa de vós, e não me ouviu; antes o Senhor me disse: Basta; não me fales mais deste assunto;'),
('acf','dt',3,27,'Sobe ao cume de Pisga, e levanta os teus olhos ao ocidente, e ao norte, e ao sul, e ao oriente, e vê com os teus olhos; porque não passarás este Jordão.'),
('acf','dt',3,28,'Manda, pois, a Josué, e anima-o, e fortalece-o; porque ele passará adiante deste povo, e o fará possuir a terra que verás.'),
('acf','dt',3,29,'Assim ficamos neste vale, defronte de Bete-Peor.'),
('acf','dt',4,1,'Agora, pois, ó Israel, ouve os estatutos e os juízos que eu vos ensino, para os cumprirdes; para que vivais, e entreis, e possuais a terra que o SENHOR Deus de vossos pais vos dá.'),
('acf','dt',4,2,'Não acrescentareis à palavra que vos mando, nem diminuireis dela, para que guardeis os mandamentos do Senhor vosso Deus, que eu vos mando.'),
('acf','dt',4,3,'Os vossos olhos têm visto o que o Senhor fez por causa de Baal-Peor; pois a todo o homem que seguiu a Baal-Peor o Senhor teu Deus consumiu do meio de ti.'),
('acf','dt',4,4,'Porém vós, que vos achegastes ao Senhor vosso Deus, hoje todos estais vivos.'),
('acf','dt',4,5,'Vedes aqui vos tenho ensinado estatutos e juízos, como me mandou o Senhor meu Deus; para que assim façais no meio da terra a qual ides a herdar.'),
('acf','dt',4,6,'Guardai-os pois, e cumpri-os, porque isso será a vossa sabedoria e o vosso entendimento perante os olhos dos povos, que ouvirão todos estes estatutos, e dirão: Este grande povo é nação sábia e entendida.'),
('acf','dt',4,7,'Pois, que nação há tão grande, que tenha deuses tão chegados como o Senhor nosso Deus, todas as vezes que o invocamos?'),
('acf','dt',4,8,'E que nação há tão grande, que tenha estatutos e juízos tão justos como toda esta lei que hoje ponho perante vós?'),
('acf','dt',4,9,'Tão-somente guarda-te a ti mesmo, e guarda bem a tua alma, que não te esqueças daquelas coisas que os teus olhos têm visto, e não se apartem do teu coração todos os dias da tua vida; e as farás saber a teus filhos, e aos filhos de teus filhos.'),
('acf','dt',4,10,'O dia em que estiveste perante o Senhor teu Deus em Horebe, quando o Senhor me disse: Ajunta-me este povo, e os farei ouvir as minhas palavras, e aprendê-las-ão, para me temerem todos os dias que na terra viverem, e as ensinarão a seus filhos;'),
('acf','dt',4,11,'E vós vos chegastes, e vos pusestes ao pé do monte; e o monte ardia em fogo até ao meio dos céus, e havia trevas, e nuvens e escuridão;'),
('acf','dt',4,12,'Então o Senhor vos falou do meio do fogo; a voz das palavras ouvistes; porém, além da voz, não vistes figura alguma.'),
('acf','dt',4,13,'Então vos anunciou ele a sua aliança que vos ordenou cumprir, os dez mandamentos, e os escreveu em duas tábuas de pedra.'),
('acf','dt',4,14,'Também o Senhor me ordenou ao mesmo tempo que vos ensinasse estatutos e juízos, para que os cumprísseis na terra a qual passais a possuir.'),
('acf','dt',4,15,'Guardai, pois, com diligência as vossas almas, pois nenhuma figura vistes no dia em que o Senhor, em Horebe, falou convosco do meio do fogo;'),
('acf','dt',4,16,'Para que não vos corrompais, e vos façais alguma imagem esculpida na forma de qualquer figura, semelhança de homem ou mulher;'),
('acf','dt',4,17,'Figura de algum animal que haja na terra; figura de alguma ave alada que voa pelos céus;'),
('acf','dt',4,18,'Figura de algum animal que se arrasta sobre a terra; figura de algum peixe que esteja nas águas debaixo da terra;'),
('acf','dt',4,19,'Que não levantes os teus olhos aos céus e vejas o sol, e a lua, e as estrelas, todo o exército dos céus; e sejas impelido a que te inclines perante eles, e sirvas àqueles que o Senhor teu Deus repartiu a todos os povos debaixo de todos os céus.'),
('acf','dt',4,20,'Mas o Senhor vos tomou, e vos tirou da fornalha de ferro do Egito, para que lhe sejais por povo hereditário, como neste dia se vê.'),
('acf','dt',4,21,'Também o Senhor se indignou contra mim por causa das vossas palavras, e jurou que eu não passaria o Jordão, e que não entraria na boa terra que o Senhor teu Deus te dará por herança.'),
('acf','dt',4,22,'Porque eu nesta terra morrerei, não passarei o Jordão; porém vós o passareis, e possuireis aquela boa terra.'),
('acf','dt',4,23,'Guardai-vos e não vos esqueçais da aliança do Senhor vosso Deus, que tem feito convosco, e não façais para vós escultura alguma, imagem de alguma coisa que o Senhor vosso Deus vos proibiu.'),
('acf','dt',4,24,'Porque o Senhor teu Deus é um fogo que consome, um Deus zeloso.'),
('acf','dt',4,25,'Quando, pois, gerardes filhos, e filhos de filhos, e vos envelhecerdes na terra, e vos corromperdes, e fizerdes alguma escultura, semelhança de alguma coisa, e fizerdes o que é mau aos olhos do Senhor teu Deus, para o provocar à ira;'),
('acf','dt',4,26,'Hoje tomo por testemunhas contra vós o céu e a terra, que certamente logo perecereis da terra, a qual passais o Jordão para a possuir; não prolongareis os vossos dias nela, antes sereis de todo destruídos.'),
('acf','dt',4,27,'E o Senhor vos espalhará entre os povos, e ficareis poucos em número entre as nações às quais o Senhor vos conduzirá.'),
('acf','dt',4,28,'E ali servireis a deuses que são obra de mãos de homens, madeira e pedra, que não vêem, nem ouvem, nem comem, nem cheiram.'),
('acf','dt',4,29,'Então dali buscarás ao Senhor teu Deus, e o acharás, quando o buscares de todo o teu coração e de toda a tua alma.'),
('acf','dt',4,30,'Quando estiverdes em angústia, e todas estas coisas te alcançarem, então nos últimos dias voltarás para o Senhor teu Deus, e ouvirás a sua voz.'),
('acf','dt',4,31,'Porquanto o Senhor teu Deus é Deus misericordioso, e não te desamparará, nem te destruirá, nem se esquecerá da aliança que jurou a teus pais.'),
('acf','dt',4,32,'Agora, pois, pergunta aos tempos passados, que te precederam desde o dia em que Deus criou o homem sobre a terra, desde uma extremidade do céu até à outra, se sucedeu jamais coisa tão grande como esta, ou se jamais se ouviu coisa como esta?'),
('acf','dt',4,33,'Ou se algum povo ouviu a voz de Deus falando do meio do fogo, como tu a ouviste, e ficou vivo?'),
('acf','dt',4,34,'Ou se Deus intentou ir tomar para si um povo do meio de outro povo com provas, com sinais, e com milagres, e com peleja, e com mão forte, e com braço estendido, e com grandes espantos, conforme a tudo quanto o Senhor vosso Deus vos fez no Egito aos vossos olhos?'),
('acf','dt',4,35,'A ti te foi mostrado para que soubesses que o Senhor é Deus; nenhum outro há senão ele.'),
('acf','dt',4,36,'Desde os céus te fez ouvir a sua voz, para te ensinar, e sobre a terra te mostrou o seu grande fogo, e ouviste as suas palavras do meio do fogo.'),
('acf','dt',4,37,'E, porquanto amou teus pais, e escolheu a sua descendência depois deles, te tirou do Egito diante de si, com a sua grande força,'),
('acf','dt',4,38,'Para lançar fora de diante de ti nações maiores e mais poderosas do que tu, para te introduzir e te dar a sua terra por herança, como neste dia se vê.'),
('acf','dt',4,39,'Por isso hoje saberás, e refletirás no teu coração, que só o Senhor é Deus, em cima no céu e em baixo na terra; nenhum outro há.'),
('acf','dt',4,40,'E guardarás os seus estatutos e os seus mandamentos, que te ordeno hoje para que te vá bem a ti, e a teus filhos depois de ti, e para que prolongues os dias na terra que o Senhor teu Deus te dá para todo o sempre.'),
('acf','dt',4,41,'Então Moisés separou três cidades além do Jordão, do lado do nascimento do sol;'),
('acf','dt',4,42,'Para que ali se acolhesse o homicida que involuntariamente matasse o seu próximo a quem dantes não tivesse ódio algum; e se acolhesse a uma destas cidades, e vivesse;'),
('acf','dt',4,43,'A Bezer, no deserto, no planalto, para os rubenitas; e a Ramote, em Gileade, para os gaditas; e a Golã, em Basã, para os manassitas.'),
('acf','dt',4,44,'Esta é, pois, a lei que Moisés propôs aos filhos de Israel.'),
('acf','dt',4,45,'Estes são os testemunhos, e os estatutos, e os juízos, que Moisés falou aos filhos de Israel, havendo saído do Egito;'),
('acf','dt',4,46,'Além do Jordão, no vale defronte de Bete-Peor, na terra de Siom, rei dos amorreus, que habitava em Hesbom, a quem feriu Moisés e os filhos de Israel, havendo eles saído do Egito.'),
('acf','dt',4,47,'E tomaram a sua terra em possessão, como também a terra de Ogue, rei de Basã, dois reis dos amorreus, que estavam além do Jordão, do lado do nascimento do sol.'),
('acf','dt',4,48,'Desde Aroer, que está à margem do ribeiro de Arnom, até ao monte Sião, que é Hermom,'),
('acf','dt',4,49,'E toda a campina além do Jordão, do lado do oriente, até ao mar da campina, abaixo de Asdote-Pisga.'),
('acf','dt',5,1,'E chamou Moisés a todo o Israel, e disse-lhes: Ouve, ó Israel, os estatutos e juízos que hoje vos falo aos ouvidos; e aprendê-los-eis, e guardá-los-eis, para os cumprir.'),
('acf','dt',5,2,'O Senhor nosso Deus fez conosco aliança em Horebe.'),
('acf','dt',5,3,'Não com nossos pais fez o Senhor esta aliança, mas conosco, todos os que hoje aqui estamos vivos.'),
('acf','dt',5,4,'Face a face o Senhor falou conosco no monte, do meio do fogo'),
('acf','dt',5,5,'(Naquele tempo eu estava em pé entre o Senhor e vós, para vos notificar a palavra do Senhor; porque temestes o fogo e não subistes ao monte), dizendo:'),
('acf','dt',5,6,'Eu sou o Senhor teu Deus, que te tirei da terra do Egito, da casa da servidão;'),
('acf','dt',5,7,'Não terás outros deuses diante de mim;'),
('acf','dt',5,8,'Não farás para ti imagem de escultura, nem semelhança alguma do que há em cima no céu, nem em baixo na terra, nem nas águas debaixo da terra;'),
('acf','dt',5,9,'Não te encurvarás a elas, nem as servirás; porque eu, o Senhor teu Deus, sou Deus zeloso, que visito a iniqüidade dos pais nos filhos, até a terceira e quarta geração daqueles que me odeiam.'),
('acf','dt',5,10,'E faço misericórdia a milhares dos que me amam e guardam os meus mandamentos.'),
('acf','dt',5,11,'Não tomarás o nome do Senhor teu Deus em vão; porque o Senhor não terá por inocente ao que tomar o seu nome em vão.'),
('acf','dt',5,12,'Guarda o dia de sábado, para o santificar, como te ordenou o Senhor teu Deus.'),
('acf','dt',5,13,'Seis dias trabalharás, e farás todo o teu trabalho.'),
('acf','dt',5,14,'Mas o sétimo dia é o sábado do Senhor teu Deus; não farás nenhum trabalho nele, nem tu, nem teu filho, nem tua filha, nem o teu servo, nem a tua serva, nem o teu boi, nem o teu jumento, nem animal algum teu, nem o estrangeiro que está dentro de tuas portas; para que o teu servo e a tua serva descansem como tu;'),
('acf','dt',5,15,'Porque te lembrarás que foste servo na terra do Egito, e que o Senhor teu Deus te tirou dali com mão forte e braço estendido; por isso o Senhor teu Deus te ordenou que guardasses o dia de sábado.'),
('acf','dt',5,16,'Honra a teu pai e a tua mãe, como o Senhor teu Deus te ordenou, para que se prolonguem os teus dias, e para que te vá bem na terra que te dá o Senhor teu Deus.'),
('acf','dt',5,17,'Não matarás.'),
('acf','dt',5,18,'Não adulterarás.'),
('acf','dt',5,19,'Não furtarás.'),
('acf','dt',5,20,'Não dirás falso testemunho contra o teu próximo.'),
('acf','dt',5,21,'Não cobiçarás a mulher do teu próximo; e não desejarás a casa do teu próximo, nem o seu campo, nem o seu servo, nem a sua serva, nem o seu boi, nem o seu jumento, nem coisa alguma do teu próximo.'),
('acf','dt',5,22,'Estas palavras falou o Senhor a toda a vossa congregação no monte, do meio do fogo, da nuvem e da escuridão, com grande voz, e nada acrescentou; e as escreveu em duas tábuas de pedra, e a mim mas deu.'),
('acf','dt',5,23,'E sucedeu que, ouvindo a voz do meio das trevas, e vendo o monte ardendo em fogo, vos achegastes a mim, todos os cabeças das vossas tribos, e vossos anciãos;'),
('acf','dt',5,24,'E dissestes: Eis aqui o Senhor nosso Deus nos fez ver a sua glória e a sua grandeza, e ouvimos a sua voz do meio do fogo; hoje vimos que Deus fala com o homem, e que este permanece vivo.'),
('acf','dt',5,25,'Agora, pois, por que morreríamos? Pois este grande fogo nos consumiria; se ainda mais ouvíssemos a voz do Senhor nosso Deus morreríamos.'),
('acf','dt',5,26,'Porque, quem há de toda a carne, que ouviu a voz do Deus vivente falando do meio do fogo, como nós, e ficou vivo?'),
('acf','dt',5,27,'Chega-te tu, e ouve tudo o que disser o Senhor nosso Deus; e tu nos dirás tudo o que te disser o Senhor nosso Deus, e o ouviremos, e o cumpriremos.'),
('acf','dt',5,28,'Ouvindo, pois, o Senhor as vossas palavras, quando me faláveis, o Senhor me disse: Eu ouvi as palavras deste povo, que eles te disseram; em tudo falaram bem.'),
('acf','dt',5,29,'Quem dera que eles tivessem tal coração que me temessem, e guardassem todos os meus mandamentos todos os dias, para que bem lhes fosse a eles e a seus filhos para sempre.'),
('acf','dt',5,30,'Vai, dize-lhes: Tornai-vos às vossas tendas.'),
('acf','dt',5,31,'Tu, porém, fica-te aqui comigo, para que eu a ti te diga todos os mandamentos, e estatutos, e juízos, que tu lhes hás de ensinar, para que cumpram na terra que eu lhes darei para possuí-la.'),
('acf','dt',5,32,'Olhai, pois, que façais como vos mandou o Senhor vosso Deus; não vos desviareis, nem para a direita nem para a esquerda.'),
('acf','dt',5,33,'Andareis em todo o caminho que vos manda o Senhor vosso Deus, para que vivais e bem vos suceda, e prolongueis os dias na terra que haveis de possuir.'),
('acf','dt',6,1,'Estes, pois, são os mandamentos, os estatutos e os juízos que mandou o SENHOR vosso Deus para ensinar-vos, para que os cumprísseis na terra a que passais a possuir;'),
('acf','dt',6,2,'Para que temas ao Senhor teu Deus, e guardes todos os seus estatutos e mandamentos, que eu te ordeno, tu, e teu filho, e o filho de teu filho, todos os dias da tua vida, e que teus dias sejam prolongados.'),
('acf','dt',6,3,'Ouve, pois, ó Israel, e atenta em os guardares, para que bem te suceda, e muito te multipliques, como te disse o Senhor Deus de teus pais, na terra que mana leite e mel.'),
('acf','dt',6,4,'Ouve, Israel, o Senhor nosso Deus é o único Senhor.'),
('acf','dt',6,5,'Amarás, pois, o Senhor teu Deus de todo o teu coração, e de toda a tua alma, e de todas as tuas forças.'),
('acf','dt',6,6,'E estas palavras, que hoje te ordeno, estarão no teu coração;'),
('acf','dt',6,7,'E as ensinarás a teus filhos e delas falarás assentado em tua casa, e andando pelo caminho, e deitando-te e levantando-te.'),
('acf','dt',6,8,'Também as atarás por sinal na tua mão, e te serão por frontais entre os teus olhos.'),
('acf','dt',6,9,'E as escreverás nos umbrais de tua casa, e nas tuas portas.'),
('acf','dt',6,10,'Quando, pois, o Senhor teu Deus te introduzir na terra que jurou a teus pais, Abraão, Isaque e Jacó, que te daria, com grandes e boas cidades, que tu não edificaste,'),
('acf','dt',6,11,'E casas cheias de todo o bem, que tu não encheste, e poços cavados, que tu não cavaste, vinhas e olivais, que tu não plantaste, e comeres, e te fartares,'),
('acf','dt',6,12,'Guarda-te, que não te esqueças do Senhor, que te tirou da terra do Egito, da casa da servidão.'),
('acf','dt',6,13,'O Senhor teu Deus temerás e a ele servirás, e pelo seu nome jurarás.'),
('acf','dt',6,14,'Não seguireis outros deuses, os deuses dos povos que houver ao redor de vós;'),
('acf','dt',6,15,'Porque o Senhor teu Deus é um Deus zeloso no meio de ti, para que a ira do Senhor teu Deus se não acenda contra ti e te destrua de sobre a face da terra.'),
('acf','dt',6,16,'Não tentareis o Senhor vosso Deus, como o tentastes em Massá;'),
('acf','dt',6,17,'Diligentemente guardareis os mandamentos do Senhor vosso Deus, como também os seus testemunhos, e seus estatutos, que te tem mandado.'),
('acf','dt',6,18,'E farás o que é reto e bom aos olhos do Senhor, para que bem te suceda, e entres, e possuas a boa terra, a qual o Senhor jurou dar a teus pais.'),
('acf','dt',6,19,'Para que lance fora a todos os teus inimigos de diante de ti, como o Senhor tem falado.'),
('acf','dt',6,20,'Quando teu filho te perguntar no futuro, dizendo: Que significam os testemunhos, e estatutos e juízos que o Senhor nosso Deus vos ordenou?'),
('acf','dt',6,21,'Então dirás a teu filho: Éramos servos de Faraó no Egito; porém o Senhor, com mão forte, nos tirou do Egito;'),
('acf','dt',6,22,'E o Senhor, aos nossos olhos, fez sinais e maravilhas, grandes e terríveis, contra o Egito, contra Faraó e toda sua casa;'),
('acf','dt',6,23,'E dali nos tirou, para nos levar, e nos dar a terra que jurara a nossos pais.'),
('acf','dt',6,24,'E o Senhor nos ordenou que cumpríssemos todos estes estatutos, que temêssemos ao Senhor nosso Deus, para o nosso perpétuo bem, para nos guardar em vida, como no dia de hoje.'),
('acf','dt',6,25,'E será para nós justiça, quando tivermos cuidado de cumprir todos estes mandamentos perante o Senhor nosso Deus, como nos tem ordenado.'),
('acf','dt',7,1,'Quando o SENHOR teu Deus te houver introduzido na terra, à qual vais para a possuir, e tiver lançado fora muitas nações de diante de ti, os heteus, e os girgaseus, e os amorreus, e os cananeus, e os perizeus, e os heveus, e os jebuseus, sete nações mais numerosas e mais poderosas do que tu;'),
('acf','dt',7,2,'E o Senhor teu Deus as tiver dado diante de ti, para as ferir, totalmente as destruirás; não farás com elas aliança, nem terás piedade delas;'),
('acf','dt',7,3,'Nem te aparentarás com elas; não darás tuas filhas a seus filhos, e não tomarás suas filhas para teus filhos;'),
('acf','dt',7,4,'Pois fariam desviar teus filhos de mim, para que servissem a outros deuses; e a ira do Senhor se acenderia contra vós, e depressa vos consumiria.'),
('acf','dt',7,5,'Porém assim lhes fareis: Derrubareis os seus altares, quebrareis as suas estátuas; e cortareis os seus bosques, e queimareis a fogo as suas imagens de escultura.'),
('acf','dt',7,6,'Porque povo santo és ao Senhor teu Deus; o Senhor teu Deus te escolheu, para que lhe fosses o seu povo especial, de todos os povos que há sobre a terra.'),
('acf','dt',7,7,'O Senhor não tomou prazer em vós, nem vos escolheu, porque a vossa multidão era mais do que a de todos os outros povos, pois vós éreis menos em número do que todos os povos;'),
('acf','dt',7,8,'Mas, porque o Senhor vos amava, e para guardar o juramento que fizera a vossos pais, o Senhor vos tirou com mão forte e vos resgatou da casa da servidão, da mão de Faraó, rei do Egito.'),
('acf','dt',7,9,'Saberás, pois, que o Senhor teu Deus, ele é Deus, o Deus fiel, que guarda a aliança e a misericórdia até mil gerações aos que o amam e guardam os seus mandamentos.'),
('acf','dt',7,10,'E retribui no rosto qualquer dos que o odeiam, fazendo-o perecer; não será tardio ao que o odeia; em seu rosto lho pagará.'),
('acf','dt',7,11,'Guarda, pois, os mandamentos e os estatutos e os juízos que hoje te mando cumprir.'),
('acf','dt',7,12,'Será, pois, que, se ouvindo estes juízos, os guardardes e cumprirdes, o Senhor teu Deus te guardará a aliança e a misericórdia que jurou a teus pais;'),
('acf','dt',7,13,'E amar-te-á, e abençoar-te-á, e te fará multiplicar; abençoará o fruto do teu ventre, e o fruto da tua terra, o teu grão, e o teu mosto, e o teu azeite, e a criação das tuas vacas, e o rebanho do teu gado miúdo, na terra que jurou a teus pais dar-te.'),
('acf','dt',7,14,'Bendito serás mais do que todos os povos; não haverá estéril entre ti, seja homem, seja mulher, nem entre os teus animais.'),
('acf','dt',7,15,'E o Senhor de ti desviará toda a enfermidade; sobre ti não porá nenhuma das más doenças dos egípcios, que bem sabes, antes as porá sobre todos os que te odeiam.'),
('acf','dt',7,16,'Pois consumirás a todos os povos que te der o Senhor teu Deus; os teus olhos não os poupará; e não servirás a seus deuses, pois isto te seria por laço.'),
('acf','dt',7,17,'Se disseres no teu coração: Estas nações são mais numerosas do que eu; como as poderei lançar fora?'),
('acf','dt',7,18,'Delas não tenhas temor; não deixes de te lembrar do que o Senhor teu Deus fez a Faraó e a todos os egípcios;'),
('acf','dt',7,19,'Das grandes provas que viram os teus olhos, e dos sinais, e maravilhas, e mão forte, e braço estendido, com que o Senhor teu Deus te tirou; assim fará o Senhor teu Deus com todos os povos, diante dos quais tu temes.'),
('acf','dt',7,20,'E mais, o Senhor teu Deus entre eles mandará vespões, até que pereçam os que ficarem e se esconderem de diante de ti.'),
('acf','dt',7,21,'Não te espantes diante deles; porque o Senhor teu Deus está no meio de ti, Deus grande e terrível.'),
('acf','dt',7,22,'E o Senhor teu Deus lançará fora estas nações pouco a pouco de diante de ti; não poderás destruí-las todas de pronto, para que as feras do campo não se multipliquem contra ti.'),
('acf','dt',7,23,'E o Senhor teu Deus as entregará a ti, e lhes infligirá uma grande confusão até que sejam consumidas.'),
('acf','dt',7,24,'Também os seus reis te entregará na mão, para que apagues os seus nomes de debaixo dos céus; nenhum homem resistirá diante de ti, até que os destruas.'),
('acf','dt',7,25,'As imagens de escultura de seus deuses queimarás a fogo; a prata e o ouro que estão sobre elas não cobiçarás, nem os tomarás para ti, para que não te enlaces neles; pois abominação é ao Senhor teu Deus.'),
('acf','dt',7,26,'Não porás, pois, abominação em tua casa, para que não sejas anátema, assim como ela; de todo a detestarás, e de todo a abominarás, porque anátema é.'),
('acf','dt',8,1,'Todos os mandamentos que hoje vos ordeno guardareis para os cumprir; para que vivais, e vos multipliqueis, e entreis, e possuais a terra que o SENHOR jurou a vossos pais.'),
('acf','dt',8,2,'E te lembrarás de todo o caminho, pelo qual o Senhor teu Deus te guiou no deserto estes quarenta anos, para te humilhar, e te provar, para saber o que estava no teu coração, se guardarias os seus mandamentos, ou não.'),
('acf','dt',8,3,'E te humilhou, e te deixou ter fome, e te sustentou com o maná, que tu não conheceste, nem teus pais o conheceram; para te dar a entender que o homem não viverá só de pão, mas de tudo o que sai da boca do Senhor viverá o homem.'),
('acf','dt',8,4,'Nunca se envelheceu a tua roupa sobre ti, nem se inchou o teu pé nestes quarenta anos.'),
('acf','dt',8,5,'Sabes, pois, no teu coração que, como um homem castiga a seu filho, assim te castiga o Senhor teu Deus.'),
('acf','dt',8,6,'E guarda os mandamentos do Senhor teu Deus, para andares nos seus caminhos e para o temeres.'),
('acf','dt',8,7,'Porque o Senhor teu Deus te põe numa boa terra, terra de ribeiros de águas, de fontes, e de mananciais, que saem dos vales e das montanhas;'),
('acf','dt',8,8,'Terra de trigo e cevada, e de vides e figueiras, e romeiras; terra de oliveiras, de azeite e mel.'),
('acf','dt',8,9,'Terra em que comerás o pão sem escassez, e nada te faltará nela; terra cujas pedras são ferro, e de cujos montes tu cavarás o cobre.'),
('acf','dt',8,10,'Quando, pois, tiveres comido, e fores farto, louvarás ao Senhor teu Deus pela boa terra que te deu.'),
('acf','dt',8,11,'Guarda-te que não te esqueças do Senhor teu Deus, deixando de guardar os seus mandamentos, e os seus juízos, e os seus estatutos que hoje te ordeno;'),
('acf','dt',8,12,'Para não suceder que, havendo tu comido e fores farto, e havendo edificado boas casas, e habitando-as,'),
('acf','dt',8,13,'E se tiverem aumentado os teus gados e os teus rebanhos, e se acrescentar a prata e o ouro, e se multiplicar tudo quanto tens,'),
('acf','dt',8,14,'Se eleve o teu coração e te esqueças do Senhor teu Deus, que te tirou da terra do Egito, da casa da servidão;'),
('acf','dt',8,15,'Que te guiou por aquele grande e terrível deserto de serpentes ardentes, e de escorpiões, e de terra seca, em que não havia água; e tirou água para ti da rocha pederneira;'),
('acf','dt',8,16,'Que no deserto te sustentou com maná, que teus pais não conheceram; para te humilhar, e para te provar, para no fim te fazer bem;'),
('acf','dt',8,17,'E digas no teu coração: A minha força, e a fortaleza da minha mão, me adquiriu este poder.'),
('acf','dt',8,18,'Antes te lembrarás do Senhor teu Deus, que ele é o que te dá força para adquirires riqueza; para confirmar a sua aliança, que jurou a teus pais, como se vê neste dia.'),
('acf','dt',8,19,'Será, porém, que, se de qualquer modo te esqueceres do Senhor teu Deus, e se ouvires outros deuses, e os servires, e te inclinares perante eles, hoje eu testifico contra vós que certamente perecereis.'),
('acf','dt',8,20,'Como as nações que o Senhor destruiu diante de vós, assim vós perecereis, porquanto não queríeis obedecer à voz do Senhor vosso Deus.'),
('acf','dt',9,1,'Ouve, ó Israel, hoje passarás o Jordão, para entrares a possuir nações maiores e mais fortes do que tu; cidades grandes, e muradas até aos céus;'),
('acf','dt',9,2,'Um povo grande e alto, filhos de gigantes, que tu conheces, e de que já ouviste. Quem resistiria diante dos filhos dos gigantes?'),
('acf','dt',9,3,'Sabe, pois, hoje que o Senhor teu Deus, que passa adiante de ti, é um fogo consumidor, que os destruirá, e os derrubará de diante de ti; e tu os lançarás fora, e cedo os desfarás, como o Senhor te tem falado.'),
('acf','dt',9,4,'Quando, pois, o Senhor teu Deus os lançar fora de diante de ti, não fales no teu coração, dizendo: Por causa da minha justiça é que o Senhor me trouxe a esta terra para a possuir; porque pela impiedade destas nações é que o Senhor as lança fora de diante de ti.'),
('acf','dt',9,5,'Não é por causa da tua justiça, nem pela retidão do teu coração que entras a possuir a sua terra, mas pela impiedade destas nações o Senhor teu Deus as lança fora, de diante de ti, e para confirmar a palavra que o Senhor jurou a teus pais, Abraão, Isaque e Jacó.'),
('acf','dt',9,6,'Sabe, pois, que não é por causa da tua justiça que o Senhor teu Deus te dá esta boa terra para possuí-la, pois tu és povo obstinado.'),
('acf','dt',9,7,'Lembra-te, e não te esqueças, de que muito provocaste à ira ao Senhor teu Deus no deserto; desde o dia em que saístes do Egito, até que chegastes a esse lugar, rebeldes fostes contra o Senhor;'),
('acf','dt',9,8,'Pois em Horebe provocastes à ira o Senhor, tanto que o Senhor se indignou contra vós para vos destruir.'),
('acf','dt',9,9,'Subindo eu ao monte a receber as tábuas de pedra, as tábuas da aliança que o Senhor fizera convosco, então fiquei no monte quarenta dias e quarenta noites; pão não comi, e água não bebi;'),
('acf','dt',9,10,'E o Senhor me deu as duas tábuas de pedra, escritas com o dedo de Deus; e nelas estava escrito conforme a todas aquelas palavras que o Senhor tinha falado convosco no monte, do meio do fogo, no dia da assembléia.'),
('acf','dt',9,11,'Sucedeu, pois, que ao fim dos quarenta dias e quarenta noites, o Senhor me deu as duas tábuas de pedra, as tábuas da aliança.'),
('acf','dt',9,12,'E o Senhor me disse: Levanta-te, desce depressa daqui, porque o teu povo, que tiraste do Egito, já se tem corrompido; cedo se desviaram do caminho que eu lhes tinha ordenado; fizeram para si uma imagem de fundição.'),
('acf','dt',9,13,'Falou-me ainda o Senhor, dizendo: Atentei para este povo, e eis que ele é povo obstinado;'),
('acf','dt',9,14,'Deixa-me que os destrua, e apague o seu nome de debaixo dos céus; e te faça a ti nação mais poderosa e mais numerosa do que esta.'),
('acf','dt',9,15,'Então virei-me, e desci do monte; o qual ardia em fogo e as duas tábuas da aliança estavam em ambas as minhas mãos.'),
('acf','dt',9,16,'E olhei, e eis que havíeis pecado contra o Senhor vosso Deus; vós tínheis feito um bezerro de fundição; cedo vos desviastes do caminho que o Senhor vos ordenara.'),
('acf','dt',9,17,'Então peguei das duas tábuas, e as arrojei das minhas mãos, e as quebrei diante dos vossos olhos.'),
('acf','dt',9,18,'E me lancei perante o Senhor, como antes, quarenta dias, e quarenta noites; não comi pão e não bebi água, por causa de todo o vosso pecado que havíeis cometido, fazendo mal aos olhos do Senhor, para o provocar à ira.'),
('acf','dt',9,19,'Porque temi por causa da ira e do furor, com que o Senhor tanto estava irado contra vós para vos destruir; porém ainda por esta vez o Senhor me ouviu.'),
('acf','dt',9,20,'Também o Senhor se irou muito contra Arão para o destruir; mas também orei por Arão ao mesmo tempo.'),
('acf','dt',9,21,'Porém eu tomei o vosso pecado, o bezerro que tínheis feito, e o queimei a fogo, e o pisei, moendo-o bem, até que se desfez em pó; e o seu pó lancei no ribeiro que descia do monte.'),
('acf','dt',9,22,'Também em Taberá, e em Massá, e em Quibrote-Hataavá provocastes muito a ira do Senhor.'),
('acf','dt',9,23,'Quando também o Senhor vos enviou de Cades-Barnéia, dizendo: Subi, e possuí a terra, que vos tenho dado: rebeldes fostes ao mandado do Senhor vosso Deus, e não o crestes, e não obedecestes à sua voz.'),
('acf','dt',9,24,'Rebeldes fostes contra o Senhor desde o dia em que vos conheci.'),
('acf','dt',9,25,'E prostrei-me perante o Senhor; aqueles quarenta dias e quarenta noites estive prostrado, porquanto o Senhor dissera que vos queria destruir.'),
('acf','dt',9,26,'E orei ao SENHOR, dizendo: Senhor DEUS, não destruas o teu povo e a tua herança, que resgataste com a tua grandeza, que tiraste do Egito com mão forte.'),
('acf','dt',9,27,'Lembra-te dos teus servos, Abraão, Isaque, e Jacó. Não atentes para a dureza deste povo, nem para a sua impiedade, nem para o seu pecado;'),
('acf','dt',9,28,'Para que o povo da terra donde nos tiraste não diga: Porquanto o Senhor não os pôde introduzir na terra de que lhes tinha falado, e porque os odiava, os tirou para matá-los no deserto;'),
('acf','dt',9,29,'Todavia são eles o teu povo e a tua herança, que tiraste com a tua grande força e com o teu braço estendido.'),
('acf','dt',10,1,'Naquele mesmo tempo me disse o SENHOR: Alisa duas tábuas de pedra, como as primeiras, e sobe a mim ao monte, e faze-te uma arca de madeira;'),
('acf','dt',10,2,'E naquelas tábuas escreverei as palavras que estavam nas primeiras tábuas, que quebraste, e as porás na arca.'),
('acf','dt',10,3,'Assim, fiz uma arca de madeira de acácia, e alisei duas tábuas de pedra, como as primeiras; e subi ao monte com as duas tábuas na minha mão.'),
('acf','dt',10,4,'Então escreveu nas tábuas, conforme à primeira escritura, os dez mandamentos, que o Senhor vos falara no dia da assembléia, no monte, do meio do fogo; e o Senhor mas deu a mim;'),
('acf','dt',10,5,'E virei-me, e desci do monte, e pus as tábuas na arca que fizera; e ali estão, como o Senhor me ordenou.'),
('acf','dt',10,6,'E partiram os filhos de Israel de Beerote-Bene-Jaacã a Moserá; ali faleceu Arão, e ali foi sepultado, e Eleazar, seu filho, administrou o sacerdócio em seu lugar.'),
('acf','dt',10,7,'Dali partiram a Gudgodá, e de Gudgodá a Jotbatá, terra de ribeiros de águas.'),
('acf','dt',10,8,'No mesmo tempo o Senhor separou a tribo de Levi, para levar a arca da aliança do Senhor, para estar diante do Senhor, para o servir, e para abençoar em seu nome até ao dia de hoje.'),
('acf','dt',10,9,'Por isso Levi não tem parte nem herança com seus irmãos; o Senhor é a sua herança, como o Senhor teu Deus lhe tem falado.'),
('acf','dt',10,10,'E eu estive no monte, como nos primeiros dias, quarenta dias e quarenta noites; e o Senhor me ouviu ainda por esta vez; não quis o Senhor destruir-te.'),
('acf','dt',10,11,'Porém o Senhor me disse: Levanta-te, põe-te a caminho adiante do povo, para que entrem, e possuam a terra que jurei dar a seus pais.'),
('acf','dt',10,12,'Agora, pois, ó Israel, que é que o Senhor teu Deus pede de ti, senão que temas o Senhor teu Deus, que andes em todos os seus caminhos, e o ames, e sirvas ao Senhor teu Deus com todo o teu coração e com toda a tua alma,'),
('acf','dt',10,13,'Que guardes os mandamentos do Senhor, e os seus estatutos, que hoje te ordeno, para o teu bem?'),
('acf','dt',10,14,'Eis que os céus e os céus dos céus são do Senhor teu Deus, a terra e tudo o que nela há.'),
('acf','dt',10,15,'Tão-somente o Senhor se agradou de teus pais para os amar; e a vós, descendência deles, escolheu, depois deles, de todos os povos como neste dia se vê.'),
('acf','dt',10,16,'Circuncidai, pois, o prepúcio do vosso coração, e não mais endureçais a vossa cerviz.'),
('acf','dt',10,17,'Pois o SENHOR vosso Deus é o Deus dos deuses, e o Senhor dos senhores, o Deus grande, poderoso e terrível, que não faz acepção de pessoas, nem aceita recompensas;'),
('acf','dt',10,18,'Que faz justiça ao órfão e à viúva, e ama o estrangeiro, dando-lhe pão e roupa.'),
('acf','dt',10,19,'Por isso amareis o estrangeiro, pois fostes estrangeiros na terra do Egito.'),
('acf','dt',10,20,'Ao Senhor teu Deus temerás; a ele servirás, e a ele te chegarás, e pelo seu nome jurarás.'),
('acf','dt',10,21,'Ele é o teu louvor e o teu Deus, que te fez estas grandes e terríveis coisas que os teus olhos têm visto.'),
('acf','dt',10,22,'Com setenta almas teus pais desceram ao Egito; e agora o Senhor teu Deus te pôs como as estrelas dos céus em multidão.'),
('acf','dt',11,1,'Amarás, pois, ao SENHOR teu Deus, e guardarás as suas ordenanças, e os seus estatutos, e os seus juízos, e os seus mandamentos, todos os dias.'),
('acf','dt',11,2,'E hoje sabereis que falo, não com vossos filhos, que o não sabem, e não viram a instrução do Senhor vosso Deus, a sua grandeza, a sua mão forte, e o seu braço estendido;'),
('acf','dt',11,3,'Nem tampouco os seus sinais, nem os seus feitos, que fez no meio do Egito a Faraó, rei do Egito, e a toda a sua terra;'),
('acf','dt',11,4,'Nem o que fez ao exército dos egípcios, aos seus cavalos e aos seus carros, fazendo passar sobre eles as águas do Mar Vermelho quando vos perseguiam, e como o Senhor os destruiu, até ao dia de hoje;'),
('acf','dt',11,5,'Nem o que vos fez no deserto, até que chegastes a este lugar;'),
('acf','dt',11,6,'E o que fez a Datã e a Abirão, filhos de Eliabe, filho de Rúben; como a terra abriu a sua boca e os tragou com as suas casas e com as suas tendas, como também tudo o que subsistia, e lhes pertencia, no meio de todo o Israel;'),
('acf','dt',11,7,'Porquanto os vossos olhos são os que viram toda a grande obra que fez o Senhor.'),
('acf','dt',11,8,'Guardai, pois, todos os mandamentos que eu vos ordeno hoje, para que sejais fortes, e entreis, e ocupeis a terra que passais a possuir;'),
('acf','dt',11,9,'E para que prolongueis os dias na terra que o Senhor jurou dar a vossos pais e à sua descendência, terra que mana leite e mel.'),
('acf','dt',11,10,'Porque a terra que passas a possuir não é como a terra do Egito, de onde saíste, em que semeavas a tua semente, e a regavas com o teu pé, como a uma horta.'),
('acf','dt',11,11,'Mas a terra que passais a possuir é terra de montes e de vales; da chuva dos céus beberá as águas;'),
('acf','dt',11,12,'Terra de que o Senhor teu Deus tem cuidado; os olhos do Senhor teu Deus estão sobre ela continuamente, desde o princípio até ao fim do ano.'),
('acf','dt',11,13,'E será que, se diligentemente obedecerdes a meus mandamentos que hoje vos ordeno, de amar ao Senhor vosso Deus, e de o servir de todo o vosso coração e de toda a vossa alma,'),
('acf','dt',11,14,'Então darei a chuva da vossa terra a seu tempo, a temporã e a serôdia, para que recolhais o vosso grão, e o vosso mosto e o vosso azeite.'),
('acf','dt',11,15,'E darei erva no teu campo aos teus animais, e comerás, e fartar-te-ás.'),
('acf','dt',11,16,'Guardai-vos, que o vosso coração não se engane, e vos desvieis, e sirvais a outros deuses, e vos inclineis perante eles;'),
('acf','dt',11,17,'E a ira do Senhor se acenda contra vós, e feche ele os céus, e não haja água, e a terra não dê o seu fruto, e cedo pereçais da boa terra que o Senhor vos dá.'),
('acf','dt',11,18,'Ponde, pois, estas minhas palavras no vosso coração e na vossa alma, e atai-as por sinal na vossa mão, para que estejam por frontais entre os vossos olhos.'),
('acf','dt',11,19,'E ensinai-as a vossos filhos, falando delas assentado em tua casa, e andando pelo caminho, e deitando-te, e levantando-te;'),
('acf','dt',11,20,'E escreve-as nos umbrais de tua casa, e nas tuas portas;'),
('acf','dt',11,21,'Para que se multipliquem os vossos dias e os dias de vossos filhos na terra que o Senhor jurou a vossos pais dar-lhes, como os dias dos céus sobre a terra.'),
('acf','dt',11,22,'Porque se diligentemente guardardes todos estes mandamentos, que vos ordeno para os guardardes, amando ao Senhor vosso Deus, andando em todos os seus caminhos, e a ele vos achegardes,'),
('acf','dt',11,23,'Também o Senhor, de diante de vós, lançará fora todas estas nações, e possuireis nações maiores e mais poderosas do que vós.'),
('acf','dt',11,24,'Todo o lugar que pisar a planta do vosso pé será vosso; desde o deserto, e desde o Líbano, desde o rio, o rio Eufrates, até ao mar ocidental, será o vosso termo.'),
('acf','dt',11,25,'Ninguém resistirá diante de vós; o Senhor vosso Deus porá sobre toda a terra, que pisardes, o vosso terror e o temor de vós, como já vos tem dito.'),
('acf','dt',11,26,'Eis que hoje eu ponho diante de vós a bênção e a maldição;'),
('acf','dt',11,27,'A bênção, quando cumprirdes os mandamentos do Senhor vosso Deus, que hoje vos mando;'),
('acf','dt',11,28,'Porém a maldição, se não cumprirdes os mandamentos do Senhor vosso Deus, e vos desviardes do caminho que hoje vos ordeno, para seguirdes outros deuses que não conhecestes.'),
('acf','dt',11,29,'E será que, quando o Senhor teu Deus te introduzir na terra, a que vais para possuí-la, então pronunciarás a bênção sobre o monte Gerizim, e a maldição sobre o monte Ebal.'),
('acf','dt',11,30,'Porventura não estão eles além do Jordão, junto ao caminho do pôr do sol, na terra dos cananeus, que habitam na campina defronte de Gilgal, junto aos carvalhais de Moré?'),
('acf','dt',11,31,'Porque passareis o Jordão para entrardes a possuir a terra, que vos dá o Senhor vosso Deus; e a possuireis, e nela habitareis.'),
('acf','dt',11,32,'Tende, pois, cuidado em cumprir todos os estatutos e os juízos, que eu hoje vos proponho.'),
('acf','dt',12,1,'Estes são os estatutos e os juízos que tereis cuidado em cumprir na terra que vos deu o SENHOR Deus de vossos pais, para a possuir todos os dias que viverdes sobre a terra.'),
('acf','dt',12,2,'Totalmente destruireis todos os lugares, onde as nações que possuireis serviram os seus deuses, sobre as altas montanhas, e sobre os outeiros, e debaixo de toda a árvore frondosa;'),
('acf','dt',12,3,'E derrubareis os seus altares, e quebrareis as suas estátuas, e os seus bosques queimareis a fogo, e destruireis as imagens esculpidas dos seus deuses, e apagareis o seu nome daquele lugar.'),
('acf','dt',12,4,'Assim não fareis ao Senhor vosso Deus;'),
('acf','dt',12,5,'Mas o lugar que o Senhor vosso Deus escolher de todas as vossas tribos, para ali pôr o seu nome, buscareis, para sua habitação, e ali vireis.'),
('acf','dt',12,6,'E ali trareis os vossos holocaustos, e os vossos sacrifícios, e os vossos dízimos, e a oferta alçada da vossa mão, e os vossos votos, e as vossas ofertas voluntárias, e os primogênitos das vossas vacas e das vossas ovelhas.'),
('acf','dt',12,7,'E ali comereis perante o Senhor vosso Deus, e vos alegrareis em tudo em que puserdes a vossa mão, vós e as vossas casas, no que abençoar o Senhor vosso Deus.'),
('acf','dt',12,8,'Não fareis conforme a tudo o que hoje fazemos aqui, cada qual tudo o que bem parece aos seus olhos.'),
('acf','dt',12,9,'Porque até agora não entrastes no descanso e na herança que vos dá o Senhor vosso Deus.'),
('acf','dt',12,10,'Mas passareis o Jordão, e habitareis na terra que vos fará herdar o Senhor vosso Deus; e vos dará repouso de todos os vossos inimigos em redor, e morareis seguros.'),
('acf','dt',12,11,'Então haverá um lugar que escolherá o Senhor vosso Deus para ali fazer habitar o seu nome; ali trareis tudo o que vos ordeno; os vossos holocaustos, e os vossos sacrifícios, e os vossos dízimos, e a oferta alçada da vossa mão, e toda a escolha dos vossos votos que fizerdes ao Senhor.'),
('acf','dt',12,12,'E vos alegrareis perante o Senhor vosso Deus, vós, e vossos filhos, e vossas filhas, e os vossos servos, e as vossas servas, e o levita que está dentro das vossas portas; pois convosco não tem parte nem herança.'),
('acf','dt',12,13,'Guarda-te, que não ofereças os teus holocaustos em todo o lugar que vires;'),
('acf','dt',12,14,'Mas no lugar que o Senhor escolher numa das tuas tribos ali oferecerás os teus holocaustos, e ali farás tudo o que te ordeno.'),
('acf','dt',12,15,'Porém, conforme a todo o desejo da tua alma, matarás e comerás carne, dentro das tuas portas, segundo a bênção do Senhor teu Deus, que te dá em todas as tuas portas; o imundo e o limpo dela comerá, como do corço e do veado;'),
('acf','dt',12,16,'Tão-somente o sangue não comereis; sobre a terra o derramareis como água.'),
('acf','dt',12,17,'Dentro das tuas portas não poderás comer o dízimo do teu grão, nem do teu mosto, nem do teu azeite, nem os primogênitos das tuas vacas, nem das tuas ovelhas; nem nenhum dos teus votos, que houveres prometido, nem as tuas ofertas voluntárias, nem a oferta alçada da tua mão.'),
('acf','dt',12,18,'Mas os comerás perante o Senhor teu Deus, no lugar que escolher o Senhor teu Deus, tu, e teu filho, e a tua filha, e o teu servo, e a tua serva, e o levita que está dentro das tuas portas; e perante o Senhor teu Deus te alegrarás em tudo em que puseres a tua mão.'),
('acf','dt',12,19,'Guarda-te, que não desampares ao levita todos os teus dias na terra.'),
('acf','dt',12,20,'Quando o Senhor teu Deus dilatar os teus termos, como te disse, e disseres: Comerei carne; porquanto a tua alma tem desejo de comer carne; conforme a todo o desejo da tua alma, comerás carne.'),
('acf','dt',12,21,'Se estiver longe de ti o lugar que o Senhor teu Deus escolher, para ali pôr o seu nome, então matarás das tuas vacas e das tuas ovelhas, que o Senhor te tiver dado, como te tenho ordenado; e comerás dentro das tuas portas, conforme a todo o desejo da tua alma.'),
('acf','dt',12,22,'Porém, como se come o corço e o veado, assim comerás; o imundo e o limpo também comerão deles.'),
('acf','dt',12,23,'Somente esforça-te para que não comas o sangue; pois o sangue é vida; pelo que não comerás a vida com a carne;'),
('acf','dt',12,24,'Não o comerás; na terra o derramarás como água.'),
('acf','dt',12,25,'Não o comerás; para que bem te suceda a ti, e a teus filhos, depois de ti, quando fizeres o que for reto aos olhos do Senhor.'),
('acf','dt',12,26,'Porém, as coisas santas que tiveres, e os teus votos tomarás, e virás ao lugar que o Senhor escolher.'),
('acf','dt',12,27,'E oferecerás os teus holocaustos, a carne e o sangue sobre o altar do Senhor teu Deus; e o sangue dos teus sacrifícios se derramará sobre o altar do Senhor teu Deus; porém a carne comerás.'),
('acf','dt',12,28,'Guarda e ouve todas estas palavras que te ordeno, para que bem te suceda a ti e a teus filhos depois de ti para sempre, quando fizeres o que for bom e reto aos olhos do Senhor teu Deus.'),
('acf','dt',12,29,'Quando o Senhor teu Deus desarraigar de diante de ti as nações, aonde vais a possuí-las, e as possuíres e habitares na sua terra,'),
('acf','dt',12,30,'Guarda-te, que não te enlaces seguindo-as, depois que forem destruídas diante de ti; e que não perguntes acerca dos seus deuses, dizendo: Assim como serviram estas nações os seus deuses, do mesmo modo também farei eu.'),
('acf','dt',12,31,'Assim não farás ao Senhor teu Deus; porque tudo o que é abominável ao Senhor, e que ele odeia, fizeram eles a seus deuses; pois até seus filhos e suas filhas queimaram no fogo aos seus deuses.'),
('acf','dt',12,32,'Tudo o que eu te ordeno, observarás para fazer; nada lhe acrescentarás nem diminuirás.'),
('acf','dt',13,1,'Quando profeta ou sonhador de sonhos se levantar no meio de ti, e te der um sinal ou prodígio,'),
('acf','dt',13,2,'E suceder o tal sinal ou prodígio, de que te houver falado, dizendo: Vamos após outros deuses, que não conheceste, e sirvamo-los;'),
('acf','dt',13,3,'Não ouvirás as palavras daquele profeta ou sonhador de sonhos; porquanto o Senhor vosso Deus vos prova, para saber se amais o Senhor vosso Deus com todo o vosso coração, e com toda a vossa alma.'),
('acf','dt',13,4,'Após o Senhor vosso Deus andareis, e a ele temereis, e os seus mandamentos guardareis, e a sua voz ouvireis, e a ele servireis, e a ele vos achegareis.'),
('acf','dt',13,5,'E aquele profeta ou sonhador de sonhos morrerá, pois falou rebeldia contra o Senhor vosso Deus, que vos tirou da terra do Egito, e vos resgatou da casa da servidão, para te apartar do caminho que te ordenou o Senhor teu Deus, para andares nele: assim tirarás o mal do meio de ti.'),
('acf','dt',13,6,'Quando te incitar teu irmão, filho da tua mãe, ou teu filho, ou tua filha, ou a mulher do teu seio, ou teu amigo, que te é como a tua alma, dizendo-te em segredo: Vamos, e sirvamos a outros deuses que não conheceste, nem tu nem teus pais;'),
('acf','dt',13,7,'Dentre os deuses dos povos que estão em redor de vós, perto ou longe de ti, desde uma extremidade da terra até à outra extremidade;'),
('acf','dt',13,8,'Não consentirás com ele, nem o ouvirás; nem o teu olho o poupará, nem terás piedade dele, nem o esconderás;'),
('acf','dt',13,9,'Mas certamente o matarás; a tua mão será a primeira contra ele, para o matar; e depois a mão de todo o povo.'),
('acf','dt',13,10,'E o apedrejarás, até que morra, pois te procurou apartar do Senhor teu Deus, que te tirou da terra do Egito, da casa da servidão;'),
('acf','dt',13,11,'Para que todo o Israel o ouça e o tema, e não torne a fazer semelhante maldade no meio de ti.'),
('acf','dt',13,12,'Quando ouvires dizer, de alguma das tuas cidades que o Senhor teu Deus te dá para ali habitar:'),
('acf','dt',13,13,'Uns homens, filhos de Belial, que saíram do meio de ti, incitaram os moradores da sua cidade, dizendo: Vamos, e sirvamos a outros deuses que não conhecestes;'),
('acf','dt',13,14,'Então inquirirás e investigarás, e com diligência perguntarás; e eis que, sendo verdade, e certo que se fez tal abominação no meio de ti;'),
('acf','dt',13,15,'Certamente ferirás, ao fio da espada, os moradores daquela cidade, destruindo a ela e a tudo o que nela houver, até os animais.'),
('acf','dt',13,16,'E ajuntarás todo o seu despojo no meio da sua praça; e a cidade e todo o seu despojo queimarás totalmente para o Senhor teu Deus, e será montão perpétuo, nunca mais se edificará.'),
('acf','dt',13,17,'Também não se pegará à tua mão nada do anátema, para que o Senhor se aparte do ardor da sua ira, e te faça misericórdia, e tenha piedade de ti, e te multiplique, como jurou a teus pais;'),
('acf','dt',13,18,'Quando ouvires a voz do Senhor teu Deus, para guardares todos os seus mandamentos que hoje te ordeno; para fazeres o que for reto aos olhos do Senhor teu Deus.'),
('acf','dt',14,1,'Filhos sois do SENHOR vosso Deus; não vos dareis golpes, nem fareis calva entre vossos olhos por causa de algum morto.'),
('acf','dt',14,2,'Porque és povo santo ao Senhor teu Deus; e o Senhor te escolheu, de todos os povos que há sobre a face da terra, para lhe seres o seu próprio povo.'),
('acf','dt',14,3,'Nenhuma coisa abominável comereis.'),
('acf','dt',14,4,'Estes são os animais que comereis: o boi, a ovelha, e a cabra.'),
('acf','dt',14,5,'O veado e a corça, e o búfalo, e a cabra montês, e o texugo, e a camurça, e o gamo.'),
('acf','dt',14,6,'Todo o animal que tem unhas fendidas, divididas em duas, que rumina, entre os animais, aquilo comereis.'),
('acf','dt',14,7,'Porém estes não comereis, dos que somente ruminam, ou que têm a unha fendida: o camelo, e a lebre, e o coelho, porque ruminam mas não têm a unha fendida; imundos vos serão.'),
('acf','dt',14,8,'Nem o porco, porque tem unha fendida, mas não rumina; imundo vos será; não comereis da carne destes, e não tocareis nos seus cadáveres.'),
('acf','dt',14,9,'Isto comereis de tudo o que há nas águas; tudo o que tem barbatanas e escamas comereis.'),
('acf','dt',14,10,'Mas tudo o que não tiver barbatanas nem escamas não o comereis; imundo vos será.'),
('acf','dt',14,11,'Toda a ave limpa comereis.'),
('acf','dt',14,12,'Porém estas são as que não comereis: a águia, e o quebrantosso, e o xofrango,'),
('acf','dt',14,13,'E o abutre, e o falcão, e o milhafre, segundo a sua espécie.'),
('acf','dt',14,14,'E todo o corvo, segundo a sua espécie.'),
('acf','dt',14,15,'E o avestruz, e o mocho, e a gaivota, e o gavião, segundo a sua espécie.'),
('acf','dt',14,16,'E o bufo, e a coruja, e a gralha,'),
('acf','dt',14,17,'E o cisne, e o pelicano, e o corvo marinho,'),
('acf','dt',14,18,'E a cegonha, e a garça, segundo a sua espécie, e a poupa, e o morcego.'),
('acf','dt',14,19,'Também todo o inseto que voa, vos será imundo; não se comerá.'),
('acf','dt',14,20,'Toda a ave limpa comereis.'),
('acf','dt',14,21,'Não comereis nenhum animal morto; ao estrangeiro, que está dentro das tuas portas, o darás a comer, ou o venderás ao estranho, porquanto és povo santo ao Senhor teu Deus. Não cozerás o cabrito com leite da sua mãe.'),
('acf','dt',14,22,'Certamente darás os dízimos de todo o fruto da tua semente, que cada ano se recolher do campo.'),
('acf','dt',14,23,'E, perante o Senhor teu Deus, no lugar que escolher para ali fazer habitar o seu nome, comerás os dízimos do teu grão, do teu mosto e do teu azeite, e os primogênitos das tuas vacas e das tuas ovelhas; para que aprendas a temer ao Senhor teu Deus todos os dias.'),
('acf','dt',14,24,'E quando o caminho te for tão comprido que os não possas levar, por estar longe de ti o lugar que escolher o Senhor teu Deus para ali pôr o seu nome, quando o Senhor teu Deus te tiver abençoado;'),
('acf','dt',14,25,'Então vende-os, e ata o dinheiro na tua mão, e vai ao lugar que escolher o Senhor teu Deus;'),
('acf','dt',14,26,'E aquele dinheiro darás por tudo o que deseja a tua alma, por vacas, e por ovelhas, e por vinho, e por bebida forte, e por tudo o que te pedir a tua alma; come-o ali perante o Senhor teu Deus, e alegra-te, tu e a tua casa;'),
('acf','dt',14,27,'Porém não desampararás o levita que está dentro das tuas portas; pois não tem parte nem herança contigo.'),
('acf','dt',14,28,'Ao fim de três anos tirarás todos os dízimos da tua colheita no mesmo ano, e os recolherás dentro das tuas portas;'),
('acf','dt',14,29,'Então virá o levita (pois nem parte nem herança tem contigo), e o estrangeiro, e o órfão, e a viúva, que estão dentro das tuas portas, e comerão, e fartar-se-ão; para que o Senhor teu Deus te abençoe em toda a obra que as tuas mãos fizerem.'),
('acf','dt',15,1,'Ao fim dos sete anos farás remissão.'),
('acf','dt',15,2,'Este, pois, é o modo da remissão: todo o credor remitirá o que emprestou ao seu próximo; não o exigirá do seu próximo ou do seu irmão, pois a remissão do Senhor é apregoada.'),
('acf','dt',15,3,'Do estrangeiro o exigirás; mas o que tiveres em poder de teu irmão a tua mão o remitirá.'),
('acf','dt',15,4,'Exceto quando não houver entre ti pobre algum; pois o Senhor abundantemente te abençoará na terra que o Senhor teu Deus te dará por herança, para possuí-la.'),
('acf','dt',15,5,'Se somente ouvires diligentemente a voz do Senhor teu Deus para cuidares em cumprir todos estes mandamentos que hoje te ordeno;'),
('acf','dt',15,6,'Porque o Senhor teu Deus te abençoará, como te tem falado; assim, emprestarás a muitas nações, mas não tomarás empréstimos; e dominarás sobre muitas nações, mas elas não dominarão sobre ti.'),
('acf','dt',15,7,'Quando entre ti houver algum pobre, de teus irmãos, em alguma das tuas portas, na terra que o Senhor teu Deus te dá, não endurecerás o teu coração, nem fecharás a tua mão a teu irmão que for pobre;'),
('acf','dt',15,8,'Antes lhe abrirás de todo a tua mão, e livremente lhe emprestarás o que lhe falta, quanto baste para a sua necessidade.'),
('acf','dt',15,9,'Guarda-te, que não haja palavra perversa no teu coração, dizendo: Vai-se aproximando o sétimo ano, o ano da remissão; e que o teu olho seja maligno para com teu irmão pobre, e não lhe dês nada; e que ele clame contra ti ao Senhor, e que haja em ti pecado.'),
('acf','dt',15,10,'Livremente lhe darás, e que o teu coração não seja maligno, quando lhe deres; pois por esta causa te abençoará o Senhor teu Deus em toda a tua obra, e em tudo o que puseres a tua mão.'),
('acf','dt',15,11,'Pois nunca deixará de haver pobre na terra; pelo que te ordeno, dizendo: Livremente abrirás a tua mão para o teu irmão, para o teu necessitado, e para o teu pobre na tua terra.'),
('acf','dt',15,12,'Quando teu irmão hebreu ou irmã hebréia se vender a ti, seis anos te servirá, mas no sétimo ano o deixarás ir livre.'),
('acf','dt',15,13,'E, quando o deixares ir livre, não o despedirás vazio.'),
('acf','dt',15,14,'Liberalmente o fornecerás do teu rebanho, e da tua eira, e do teu lagar; daquilo com que o Senhor teu Deus te tiver abençoado lhe darás.'),
('acf','dt',15,15,'E lembrar-te-ás de que foste servo na terra do Egito, e de que o Senhor teu Deus te resgatou; portanto hoje te ordeno isso.'),
('acf','dt',15,16,'Porém se ele te disser: Não sairei de ti; porquanto te amo a ti, e a tua casa, por estar bem contigo;'),
('acf','dt',15,17,'Então tomarás uma sovela, e lhe furarás a orelha à porta, e teu servo será para sempre; e também assim farás à tua serva.'),
('acf','dt',15,18,'Não seja duro aos teus olhos, quando despedi-lo liberto de ti; pois seis anos te serviu em equivalência ao dobro do salário do diarista; assim o Senhor teu Deus te abençoará em tudo o que fizeres.'),
('acf','dt',15,19,'Todo o primogênito que nascer das tuas vacas e das tuas ovelhas, o macho santificarás ao Senhor teu Deus; com o primogênito do teu boi não trabalharás, nem tosquiarás o primogênito das tuas ovelhas.'),
('acf','dt',15,20,'Perante o Senhor teu Deus os comerás de ano em ano, no lugar que o Senhor escolher, tu e a tua casa.'),
('acf','dt',15,21,'Porém, havendo nele algum defeito, se for coxo, ou cego, ou tiver qualquer defeito, não o sacrificarás ao Senhor teu Deus.'),
('acf','dt',15,22,'Nas tuas portas o comerás; o imundo e o limpo o comerão também, como da corça ou do veado.'),
('acf','dt',15,23,'Somente o seu sangue não comerás; sobre a terra o derramarás como água.'),
('acf','dt',16,1,'Guarda o mês de Abibe, e celebra a páscoa ao SENHOR teu Deus; porque no mês de Abibe o SENHOR teu Deus te tirou do Egito, de noite.'),
('acf','dt',16,2,'Então sacrificarás a páscoa ao Senhor teu Deus, das ovelhas e das vacas, no lugar que o Senhor escolher para ali fazer habitar o seu nome.'),
('acf','dt',16,3,'Nela não comerás levedado; sete dias nela comerás pães ázimos, pão de aflição (porquanto apressadamente saíste da terra do Egito), para que te lembres do dia da tua saída da terra do Egito, todos os dias da tua vida.'),
('acf','dt',16,4,'Levedado não aparecerá contigo por sete dias em todos os teus termos; também da carne que matares à tarde, no primeiro dia, nada ficará até à manhã.'),
('acf','dt',16,5,'Não poderás sacrificar a páscoa em nenhuma das tuas portas que te dá o Senhor teu Deus;'),
('acf','dt',16,6,'Senão no lugar que escolher o Senhor teu Deus, para fazer habitar o seu nome, ali sacrificarás a páscoa à tarde, ao pôr do sol, ao tempo determinado da tua saída do Egito.'),
('acf','dt',16,7,'Então a cozerás, e comerás no lugar que escolher o Senhor teu Deus; depois voltarás pela manhã, e irás às tuas tendas.'),
('acf','dt',16,8,'Seis dias comerás pães ázimos e no sétimo dia é solenidade ao Senhor teu Deus; nenhum trabalho farás.'),
('acf','dt',16,9,'Sete semanas contarás; desde que a foice começar na seara iniciarás a contar as sete semanas.'),
('acf','dt',16,10,'Depois celebrarás a festa das semanas ao Senhor teu Deus; o que deres será oferta voluntária da tua mão, segundo o Senhor teu Deus te houver abençoado.'),
('acf','dt',16,11,'E te alegrarás perante o Senhor teu Deus, tu, e teu filho, e tua filha, e o teu servo, e a tua serva, e o levita que está dentro das tuas portas, e o estrangeiro, e o órfão, e a viúva, que estão no meio de ti, no lugar que o Senhor teu Deus escolher para ali fazer habitar o seu nome.'),
('acf','dt',16,12,'E lembrar-te-ás de que foste servo no Egito; e guardarás estes estatutos, e os cumprirás.'),
('acf','dt',16,13,'A festa dos tabernáculos celebrarás sete dias, quando tiveres colhido da tua eira e do teu lagar.'),
('acf','dt',16,14,'E, na tua festa, alegrar-te-ás, tu, e teu filho, e tua filha, e o teu servo, e a tua serva, e o levita, e o estrangeiro, e o órfão, e a viúva, que estão dentro das tuas portas.'),
('acf','dt',16,15,'Sete dias celebrarás a festa ao Senhor teu Deus, no lugar que o Senhor escolher; porque o Senhor teu Deus te há de abençoar em toda a tua colheita, e em todo o trabalho das tuas mãos; por isso certamente te alegrarás.'),
('acf','dt',16,16,'Três vezes no ano todo o homem entre ti aparecerá perante o Senhor teu Deus, no lugar que escolher, na festa dos pães ázimos, e na festa das semanas, e na festa dos tabernáculos; porém não aparecerá vazio perante o Senhor;'),
('acf','dt',16,17,'Cada um, conforme ao dom da sua mão, conforme a bênção do Senhor teu Deus, que lhe tiver dado.'),
('acf','dt',16,18,'Juízes e oficiais porás em todas as tuas cidades que o Senhor teu Deus te der entre as tuas tribos, para que julguem o povo com juízo de justiça.'),
('acf','dt',16,19,'Não torcerás o juízo, não farás acepção de pessoas, nem receberás peitas; porquanto a peita cega os olhos dos sábios, e perverte as palavras dos justos.'),
('acf','dt',16,20,'A justiça, somente a justiça seguirás; para que vivas, e possuas em herança a terra que te dará o Senhor teu Deus.'),
('acf','dt',16,21,'Não plantarás nenhuma árvore junto ao altar do Senhor teu Deus, que fizeres para ti.'),
('acf','dt',16,22,'Nem levantarás imagem, a qual o Senhor teu Deus odeia.'),
('acf','dt',17,1,'Não sacrificarás ao SENHOR teu Deus, boi ou gado miúdo em que haja defeito ou alguma coisa má; pois abominação é ao SENHOR teu Deus.'),
('acf','dt',17,2,'Quando no meio de ti, em alguma das tuas portas que te dá o Senhor teu Deus, se achar algum homem ou mulher que fizer mal aos olhos do Senhor teu Deus, transgredindo a sua aliança.'),
('acf','dt',17,3,'Que se for, e servir a outros deuses, e se encurvar a eles ou ao sol, ou à lua, ou a todo o exército do céu, o que eu não ordenei,'),
('acf','dt',17,4,'E te for denunciado, e o ouvires; então bem o inquirirás; e eis que, sendo verdade, e certo que se fez tal abominação em Israel,'),
('acf','dt',17,5,'Então tirarás o homem ou a mulher que fez este malefício, às tuas portas, e apedrejarás o tal homem ou mulher, até que morra.'),
('acf','dt',17,6,'Por boca de duas testemunhas, ou três testemunhas, será morto o que houver de morrer; por boca de uma só testemunha não morrerá.'),
('acf','dt',17,7,'As mãos das testemunhas serão primeiro contra ele, para matá-lo; e depois as mãos de todo o povo; assim tirarás o mal do meio de ti.'),
('acf','dt',17,8,'Quando alguma coisa te for difícil demais em juízo, entre sangue e sangue, entre demanda e demanda, entre ferida e ferida, em questões de litígios nas tuas portas, então te levantarás, e subirás ao lugar que escolher o Senhor teu Deus;'),
('acf','dt',17,9,'E virás aos sacerdotes levitas, e ao juiz que houver naqueles dias, e inquirirás, e te anunciarão a sentença do juízo.'),
('acf','dt',17,10,'E farás conforme ao mandado da palavra que te anunciarem no lugar que escolher o Senhor; e terás cuidado de fazer conforme a tudo o que te ensinarem.'),
('acf','dt',17,11,'Conforme ao mandado da lei que te ensinarem, e conforme ao juízo que te disserem, farás; da palavra que te anunciarem te não desviarás, nem para a direita nem para a esquerda.'),
('acf','dt',17,12,'O homem, pois, que se houver soberbamente, não dando ouvidos ao sacerdote, que está ali para servir ao Senhor teu Deus, nem ao juiz, esse homem morrerá; e tirarás o mal de Israel;'),
('acf','dt',17,13,'Para que todo o povo o ouça, e tema, e nunca mais se ensoberbeça.'),
('acf','dt',17,14,'Quando entrares na terra que te dá o Senhor teu Deus, e a possuíres, e nela habitares, e disseres: Porei sobre mim um rei, assim como têm todas as nações que estão em redor de mim;'),
('acf','dt',17,15,'Porás certamente sobre ti como rei aquele que escolher o Senhor teu Deus; dentre teus irmãos porás rei sobre ti; não poderás pôr homem estranho sobre ti, que não seja de teus irmãos.'),
('acf','dt',17,16,'Porém ele não multiplicará para si cavalos, nem fará voltar o povo ao Egito para multiplicar cavalos; pois o Senhor vos tem dito: Nunca mais voltareis por este caminho.'),
('acf','dt',17,17,'Tampouco para si multiplicará mulheres, para que o seu coração não se desvie; nem prata nem ouro multiplicará muito para si.'),
('acf','dt',17,18,'Será também que, quando se assentar sobre o trono do seu reino, então escreverá para si num livro, um traslado desta lei, do original que está diante dos sacerdotes levitas.'),
('acf','dt',17,19,'E o terá consigo, e nele lerá todos os dias da sua vida, para que aprenda a temer ao Senhor seu Deus, para guardar todas as palavras desta lei, e estes estatutos, para cumpri-los;'),
('acf','dt',17,20,'Para que o seu coração não se levante sobre os seus irmãos, e não se aparte do mandamento, nem para a direita nem para a esquerda; para que prolongue os seus dias no seu reino, ele e seus filhos no meio de Israel.'),
('acf','dt',18,1,'Os sacerdotes levitas, toda a tribo de Levi, não terão parte nem herança com Israel; das ofertas queimadas do SENHOR e da sua herança comerão.'),
('acf','dt',18,2,'Por isso não terão herança no meio de seus irmãos; o Senhor é a sua herança, como lhes tem dito.'),
('acf','dt',18,3,'Este, pois, será o direito dos sacerdotes, a receber do povo, dos que oferecerem sacrifício, seja boi ou gado miúdo; que darão ao sacerdote a espádua e as queixadas e o bucho.'),
('acf','dt',18,4,'Dar-lhe-ás as primícias do teu grão, do teu mosto e do teu azeite, e as primícias da tosquia das tuas ovelhas.'),
('acf','dt',18,5,'Porque o Senhor teu Deus o escolheu de todas as tuas tribos, para que assista e sirva no nome do Senhor, ele e seus filhos, todos os dias.'),
('acf','dt',18,6,'E, quando chegar um levita de alguma das tuas portas, de todo o Israel, onde habitar; e vier com todo o desejo da sua alma ao lugar que o Senhor escolheu;'),
('acf','dt',18,7,'E servir no nome do Senhor seu Deus, como também todos os seus irmãos, os levitas, que assistem ali perante o Senhor,'),
('acf','dt',18,8,'Igual porção comerão, além das vendas do seu patrimônio.'),
('acf','dt',18,9,'Quando entrares na terra que o Senhor teu Deus te der, não aprenderás a fazer conforme as abominações daquelas nações.'),
('acf','dt',18,10,'Entre ti não se achará quem faça passar pelo fogo a seu filho ou a sua filha, nem adivinhador, nem prognosticador, nem agoureiro, nem feiticeiro;'),
('acf','dt',18,11,'Nem encantador, nem quem consulte a um espírito adivinhador, nem mágico, nem quem consulte os mortos;'),
('acf','dt',18,12,'Pois todo aquele que faz tal coisa é abominação ao Senhor; e por estas abominações o Senhor teu Deus os lança fora de diante de ti.'),
('acf','dt',18,13,'Perfeito serás, como o Senhor teu Deus.'),
('acf','dt',18,14,'Porque estas nações, que hás de possuir, ouvem os prognosticadores e os adivinhadores; porém a ti o Senhor teu Deus não permitiu tal coisa.'),
('acf','dt',18,15,'O Senhor teu Deus te levantará um profeta do meio de ti, de teus irmãos, como eu; a ele ouvireis;'),
('acf','dt',18,16,'Conforme a tudo o que pediste ao Senhor teu Deus em Horebe, no dia da assembléia, dizendo: Não ouvirei mais a voz do Senhor teu Deus, nem mais verei este grande fogo, para que não morra.'),
('acf','dt',18,17,'Então o Senhor me disse: Falaram bem naquilo que disseram.'),
('acf','dt',18,18,'Eis lhes suscitarei um profeta do meio de seus irmãos, como tu, e porei as minhas palavras na sua boca, e ele lhes falará tudo o que eu lhe ordenar.'),
('acf','dt',18,19,'E será que qualquer que não ouvir as minhas palavras, que ele falar em meu nome, eu o requererei dele.'),
('acf','dt',18,20,'Porém o profeta que tiver a presunção de falar alguma palavra em meu nome, que eu não lhe tenha mandado falar, ou o que falar em nome de outros deuses, esse profeta morrerá.'),
('acf','dt',18,21,'E, se disseres no teu coração: Como conhecerei a palavra que o Senhor não falou?'),
('acf','dt',18,22,'Quando o profeta falar em nome do Senhor, e essa palavra não se cumprir, nem suceder assim; esta é palavra que o Senhor não falou; com soberba a falou aquele profeta; não tenhas temor dele.'),
('acf','dt',19,1,'Quando o SENHOR teu Deus desarraigar as nações cuja terra te dará o SENHOR teu Deus, e tu as possuíres, e morares nas suas cidades e nas suas casas,'),
('acf','dt',19,2,'Três cidades separarás, no meio da terra que te dará o Senhor teu Deus para a possuíres.'),
('acf','dt',19,3,'Preparar-te-ás o caminho; e os termos da tua terra, que te fará possuir o Senhor teu Deus, dividirás em três; e isto será para que todo o homicida se acolha ali.'),
('acf','dt',19,4,'E este é o caso tocante ao homicida, que se acolher ali, para que viva; aquele que por engano ferir o seu próximo, a quem não odiava antes;'),
('acf','dt',19,5,'Como aquele que entrar com o seu próximo no bosque, para cortar lenha, e, pondo força na sua mão com o machado para cortar a árvore, o ferro saltar do cabo e ferir o seu próximo e este morrer, aquele se acolherá a uma destas cidades, e viverá;'),
('acf','dt',19,6,'Para que o vingador do sangue não vá após o homicida, quando se enfurecer o seu coração, e o alcançar, por ser comprido o caminho, e lhe tire a vida; porque não é culpado de morte, pois o não odiava antes.'),
('acf','dt',19,7,'Portanto te dou ordem, dizendo: Três cidades separarás.'),
('acf','dt',19,8,'E, se o Senhor teu Deus dilatar os teus termos, como jurou a teus pais, e te der toda a terra que disse daria a teus pais'),
('acf','dt',19,9,'(Quando guardares todos estes mandamentos, que hoje te ordeno, para cumprí-los, amando ao Senhor teu Deus e andando nos seus caminhos todos os dias), então acrescentarás outras três cidades além destas três.'),
('acf','dt',19,10,'Para que o sangue inocente não se derrame no meio da tua terra, que o Senhor teu Deus te dá por herança, e haja sangue sobre ti.'),
('acf','dt',19,11,'Mas, havendo alguém que odeia a seu próximo, e lhe arma ciladas, e se levanta contra ele, e o fere mortalmente, e se acolhe a alguma destas cidades,'),
('acf','dt',19,12,'Então os anciãos da sua cidade mandarão buscá-lo; e dali o tirarão, e o entregarão na mão do vingador do sangue, para que morra.'),
('acf','dt',19,13,'O teu olho não o perdoará; antes tirarás o sangue inocente de Israel, para que bem te suceda.'),
('acf','dt',19,14,'Não mudes o limite do teu próximo, que estabeleceram os antigos na tua herança, que receberás na terra que te dá o Senhor teu Deus para a possuíres.'),
('acf','dt',19,15,'Uma só testemunha contra alguém não se levantará por qualquer iniqüidade, ou por qualquer pecado, seja qual for o pecado que cometeu; pela boca de duas testemunhas, ou pela boca de três testemunhas, se estabelecerá o fato.'),
('acf','dt',19,16,'Quando se levantar testemunha falsa contra alguém, para testificar contra ele acerca de transgressão,'),
('acf','dt',19,17,'Então aqueles dois homens, que tiverem a demanda, se apresentarão perante o Senhor, diante dos sacerdotes e dos juízes que houver naqueles dias.'),
('acf','dt',19,18,'E os juízes inquirirão bem; e eis que, sendo a testemunha falsa, que testificou falsamente contra seu irmão,'),
('acf','dt',19,19,'Far-lhe-eis como cuidou fazer a seu irmão; e assim tirarás o mal do meio de ti.'),
('acf','dt',19,20,'Para que os que ficarem o ouçam e temam, e nunca mais tornem a fazer tal mal no meio de ti.'),
('acf','dt',19,21,'O teu olho não perdoará; vida por vida, olho por olho, dente por dente, mão por mão, pé por pé.'),
('acf','dt',20,1,'Quando saíres à peleja contra teus inimigos, e vires cavalos, e carros, e povo maior em número do que tu, deles não terás temor; pois o SENHOR teu Deus, que te tirou da terra do Egito, está contigo.'),
('acf','dt',20,2,'E será que, quando vos achegardes à peleja, o sacerdote se adiantará, e falará ao povo,'),
('acf','dt',20,3,'E dir-lhe-á: Ouvi, ó Israel, hoje vos achegais à peleja contra os vossos inimigos; não se amoleça o vosso coração: não temais nem tremais, nem vos aterrorizeis diante deles,'),
('acf','dt',20,4,'Pois o Senhor vosso Deus é o que vai convosco, a pelejar contra os vossos inimigos, para salvar-vos.'),
('acf','dt',20,5,'Então os oficiais falarão ao povo, dizendo: Qual é o homem que edificou casa nova e ainda não a consagrou? Vá, e torne-se à sua casa para que porventura não morra na peleja e algum outro a consagre.'),
('acf','dt',20,6,'E qual é o homem que plantou uma vinha e ainda não a desfrutou? Vá, e torne-se à sua casa, para que porventura não morra na peleja e algum outro a desfrute.'),
('acf','dt',20,7,'E qual é o homem que está desposado com alguma mulher e ainda não a recebeu? Vá, e torne-se à sua casa, para que porventura não morra na peleja e algum outro homem a receba.'),
('acf','dt',20,8,'E continuarão os oficiais a falar ao povo, dizendo: Qual é o homem medroso e de coração tímido? Vá, e torne-se à sua casa, para que o coração de seus irmãos não se derreta como o seu coração.'),
('acf','dt',20,9,'E será que, quando os oficiais acabarem de falar ao povo, então designarão os capitães dos exércitos para a dianteira do povo.'),
('acf','dt',20,10,'Quando te achegares a alguma cidade para combatê-la, apregoar-lhe-ás a paz.'),
('acf','dt',20,11,'E será que, se te responder em paz, e te abrir as portas, todo o povo que se achar nela te será tributário e te servirá.'),
('acf','dt',20,12,'Porém, se ela não fizer paz contigo, mas antes te fizer guerra, então a sitiarás.'),
('acf','dt',20,13,'E o Senhor teu Deus a dará na tua mão; e todo o homem que houver nela passarás ao fio da espada.'),
('acf','dt',20,14,'Porém, as mulheres, e as crianças, e os animais; e tudo o que houver na cidade, todo o seu despojo, tomarás para ti; e comerás o despojo dos teus inimigos, que te deu o Senhor teu Deus.'),
('acf','dt',20,15,'Assim farás a todas as cidades que estiverem mui longe de ti, que não forem das cidades destas nações.'),
('acf','dt',20,16,'Porém, das cidades destas nações, que o Senhor teu Deus te dá em herança, nenhuma coisa que tem fôlego deixarás com vida.'),
('acf','dt',20,17,'Antes destruí-las-ás totalmente: aos heteus, e aos amorreus, e aos cananeus, e aos perizeus, e aos heveus, e aos jebuseus, como te ordenou o Senhor teu Deus.'),
('acf','dt',20,18,'Para que não vos ensinem a fazer conforme a todas as suas abominações, que fizeram a seus deuses, e pequeis contra o Senhor vosso Deus.'),
('acf','dt',20,19,'Quando sitiares uma cidade por muitos dias, pelejando contra ela para a tomar, não destruirás o seu arvoredo, colocando nele o machado, porque dele comerás; pois que não o cortarás (pois o arvoredo do campo é mantimento para o homem), para empregar no cerco.'),
('acf','dt',20,20,'Mas as árvores que souberes que não são árvores de alimento, destruí-las-ás e cortá-las-ás; e contra a cidade que guerrear contra ti edificarás baluartes, até que esta seja vencida.'),
('acf','dt',21,1,'Quando na terra que te der o SENHOR teu Deus, para possuí-la, se achar um morto, caído no campo, sem que se saiba quem o matou,'),
('acf','dt',21,2,'Então sairão os teus anciãos e os teus juízes, e medirão a distância até as cidades que estiverem em redor do morto;'),
('acf','dt',21,3,'E, na cidade mais próxima ao morto, os anciãos da mesma cidade tomarão uma novilha da manada, que não tenha trabalhado nem tenha puxado com o jugo;'),
('acf','dt',21,4,'E os anciãos daquela cidade trarão a novilha a um vale áspero, que nunca foi lavrado nem semeado; e ali, naquele vale, degolarão a novilha;'),
('acf','dt',21,5,'Então se achegarão os sacerdotes, filhos de Levi; pois o Senhor teu Deus os escolheu para o servirem, e para abençoarem em nome do Senhor; e pela sua palavra se decidirá toda a demanda e todo o ferimento;'),
('acf','dt',21,6,'E todos os anciãos da mesma cidade, mais próxima ao morto, lavarão as suas mãos sobre a novilha degolada no vale;'),
('acf','dt',21,7,'E protestarão, e dirão: As nossas mãos não derramaram este sangue, e os nossos olhos o não viram.'),
('acf','dt',21,8,'Sê propício ao teu povo Israel, que tu, ó Senhor, resgataste, e não ponhas o sangue inocente no meio do teu povo Israel. E aquele sangue lhes será expiado.'),
('acf','dt',21,9,'Assim tirarás o sangue inocente do meio de ti; pois farás o que é reto aos olhos do Senhor.'),
('acf','dt',21,10,'Quando saíres à peleja contra os teus inimigos, e o Senhor teu Deus os entregar nas tuas mãos, e tu deles levares prisioneiros,'),
('acf','dt',21,11,'E tu entre os presos vires uma mulher formosa à vista, e a cobiçares, e a tomares por mulher,'),
('acf','dt',21,12,'Então a trarás para a tua casa; e ela rapará a cabeça e cortará as suas unhas.'),
('acf','dt',21,13,'E despirá o vestido do seu cativeiro, e se assentará na tua casa, e chorará a seu pai e a sua mãe um mês inteiro; e depois chegarás a ela, e tu serás seu marido e ela tua mulher.'),
('acf','dt',21,14,'E será que, se te não contentares dela, a deixarás ir à sua vontade; mas de modo algum a venderás por dinheiro, nem a tratarás como escrava, pois a tens humilhado.'),
('acf','dt',21,15,'Quando um homem tiver duas mulheres, uma a quem ama e outra a quem despreza, e a amada e a desprezada lhe derem filhos, e o filho primogênito for da desprezada,'),
('acf','dt',21,16,'Será que, no dia em que fizer herdar a seus filhos o que tiver, não poderá dar a primogenitura ao filho da amada, preferindo-o ao filho da desprezada, que é o primogênito.'),
('acf','dt',21,17,'Mas ao filho da desprezada reconhecerá por primogênito, dando-lhe dobrada porção de tudo quanto tiver; porquanto aquele é o princípio da sua força, o direito da primogenitura é dele.'),
('acf','dt',21,18,'Quando alguém tiver um filho contumaz e rebelde, que não obedecer à voz de seu pai e à voz de sua mãe, e, castigando-o eles, lhes não der ouvidos,'),
('acf','dt',21,19,'Então seu pai e sua mãe pegarão nele, e o levarão aos anciãos da sua cidade, e à porta do seu lugar;'),
('acf','dt',21,20,'E dirão aos anciãos da cidade: Este nosso filho é rebelde e contumaz, não dá ouvidos à nossa voz; é um comilão e um beberrão.'),
('acf','dt',21,21,'Então todos os homens da sua cidade o apedrejarão, até que morra; e tirarás o mal do meio de ti, e todo o Israel ouvirá e temerá.'),
('acf','dt',21,22,'Quando também em alguém houver pecado, digno do juízo de morte, e for morto, e o pendurares num madeiro,'),
('acf','dt',21,23,'O seu cadáver não permanecerá no madeiro, mas certamente o enterrarás no mesmo dia; porquanto o pendurado é maldito de Deus; assim não contaminarás a tua terra, que o Senhor teu Deus te dá em herança.'),
('acf','dt',22,1,'Vendo extraviado o boi ou ovelha de teu irmão, não te desviarás deles; restituí-los-ás sem falta a teu irmão.'),
('acf','dt',22,2,'E se teu irmão não estiver perto de ti, ou não o conheceres, recolhê-los-ás na tua casa, para que fiquem contigo, até que teu irmão os busque, e tu lhos restituirás.'),
('acf','dt',22,3,'Assim também farás com o seu jumento, e assim farás com as suas roupas; assim farás também com toda a coisa perdida, que se perder de teu irmão, e tu a achares; não te poderás omitir.'),
('acf','dt',22,4,'Se vires o jumento que é de teu irmão, ou o seu boi, caídos no caminho, não te desviarás deles; sem falta o ajudarás a levantá-los.'),
('acf','dt',22,5,'Não haverá traje de homem na mulher, e nem vestirá o homem roupa de mulher; porque, qualquer que faz isto, abominação é ao Senhor teu Deus.'),
('acf','dt',22,6,'Quando encontrares pelo caminho um ninho de ave numa árvore, ou no chão, com passarinhos, ou ovos, e a mãe posta sobre os passarinhos, ou sobre os ovos, não tomarás a mãe com os filhotes;'),
('acf','dt',22,7,'Deixarás ir livremente a mãe, e os filhotes tomarás para ti; para que te vá bem e para que prolongues os teus dias.'),
('acf','dt',22,8,'Quando edificares uma casa nova, farás um parapeito, no eirado, para que não ponhas culpa de sangue na tua casa, se alguém de algum modo cair dela.'),
('acf','dt',22,9,'Não semearás a tua vinha com diferentes espécies de semente, para que não se degenere o fruto da semente que semeares, e a novidade da vinha.'),
('acf','dt',22,10,'Com boi e com jumento não lavrarás juntamente.'),
('acf','dt',22,11,'Não te vestirás de diversos estofos de lã e linho juntamente.'),
('acf','dt',22,12,'Franjas porás nas quatro bordas da tua manta, com que te cobrires.'),
('acf','dt',22,13,'Quando um homem tomar mulher e, depois de coabitar com ela, a desprezar,'),
('acf','dt',22,14,'E lhe imputar coisas escandalosas, e contra ela divulgar má fama, dizendo: Tomei esta mulher, e me cheguei a ela, porém não a achei virgem;'),
('acf','dt',22,15,'Então o pai da moça e sua mãe tomarão os sinais da virgindade da moça, e levá-los-ão aos anciãos da cidade, à porta;'),
('acf','dt',22,16,'E o pai da moça dirá aos anciãos: Eu dei minha filha por mulher a este homem, porém ele a despreza;'),
('acf','dt',22,17,'E eis que lhe imputou coisas escandalosas, dizendo: Não achei virgem a tua filha; porém eis aqui os sinais da virgindade de minha filha. E estenderão a roupa diante dos anciãos da cidade.'),
('acf','dt',22,18,'Então os anciãos da mesma cidade tomarão aquele homem, e o castigarão.'),
('acf','dt',22,19,'E o multarão em cem siclos de prata, e os darão ao pai da moça; porquanto divulgou má fama sobre uma virgem de Israel. E lhe será por mulher, em todos os seus dias não a poderá despedir.'),
('acf','dt',22,20,'Porém se isto for verdadeiro, isto é, que a virgindade não se achou na moça,'),
('acf','dt',22,21,'Então levarão a moça à porta da casa de seu pai, e os homens da sua cidade a apedrejarão, até que morra; pois fez loucura em Israel, prostituindo-se na casa de seu pai; assim tirarás o mal do meio de ti.'),
('acf','dt',22,22,'Quando um homem for achado deitado com mulher que tenha marido, então ambos morrerão, o homem que se deitou com a mulher, e a mulher; assim tirarás o mal de Israel.'),
('acf','dt',22,23,'Quando houver moça virgem, desposada, e um homem a achar na cidade, e se deitar com ela,'),
('acf','dt',22,24,'Então trareis ambos à porta daquela cidade, e os apedrejareis, até que morram; a moça, porquanto não gritou na cidade, e o homem, porquanto humilhou a mulher do seu próximo; assim tirarás o mal do meio de ti.'),
('acf','dt',22,25,'E se algum homem no campo achar uma moça desposada, e o homem a forçar, e se deitar com ela, então morrerá só o homem que se deitou com ela;'),
('acf','dt',22,26,'Porém à moça não farás nada. A moça não tem culpa de morte; porque, como o homem que se levanta contra o seu próximo, e lhe tira a vida, assim é este caso.'),
('acf','dt',22,27,'Pois a achou no campo; a moça desposada gritou, e não houve quem a livrasse.'),
('acf','dt',22,28,'Quando um homem achar uma moça virgem, que não for desposada, e pegar nela, e se deitar com ela, e forem apanhados,'),
('acf','dt',22,29,'Então o homem que se deitou com ela dará ao pai da moça cinqüenta siclos de prata; e porquanto a humilhou, lhe será por mulher; não a poderá despedir em todos os seus dias.'),
('acf','dt',22,30,'Nenhum homem tomará a mulher de seu pai, nem descobrirá a nudez de seu pai.'),
('acf','dt',23,1,'Aquele a quem forem trilhados os testículos, ou cortado o membro viril, não entrará na congregação do SENHOR.'),
('acf','dt',23,2,'Nenhum bastardo entrará na congregação do Senhor; nem ainda a sua décima geração entrará na congregação do Senhor.'),
('acf','dt',23,3,'Nenhum amonita nem moabita entrará na congregação do Senhor; nem ainda a sua décima geração entrará na congregação do Senhor eternamente.'),
('acf','dt',23,4,'Porquanto não saíram com pão e água, a receber-vos no caminho, quando saíeis do Egito; e porquanto alugaram contra ti a Balaão, filho de Beor, de Petor, de mesopotâmia, para te amaldiçoar.'),
('acf','dt',23,5,'Porém o Senhor teu Deus não quis ouvir Balaão; antes o Senhor teu Deus trocou em bênção a maldição; porquanto o Senhor teu Deus te amava.'),
('acf','dt',23,6,'Não lhes procurarás nem paz nem bem em todos os teus dias para sempre.'),
('acf','dt',23,7,'Não abominarás o edomeu, pois é teu irmão; nem abominarás o egípcio, pois estrangeiro foste na sua terra.'),
('acf','dt',23,8,'Os filhos que lhes nascerem na terceira geração, cada um deles entrará na congregação do Senhor.'),
('acf','dt',23,9,'Quando o exército sair contra os teus inimigos, então te guardarás de toda a coisa má.'),
('acf','dt',23,10,'Quando entre ti houver alguém que, por algum acidente noturno, não estiver limpo, sairá fora do arraial; não entrará no meio dele.'),
('acf','dt',23,11,'Porém será que, declinando a tarde, se lavará em água; e, em se pondo o sol, entrará no meio do arraial.'),
('acf','dt',23,12,'Também terás um lugar fora do arraial, para onde sairás.'),
('acf','dt',23,13,'E entre as tuas armas terás uma pá; e será que, quando estiveres assentado, fora, então com ela cavarás e, virando-te, cobrirás o que defecaste.'),
('acf','dt',23,14,'Porquanto o Senhor teu Deus anda no meio de teu arraial, para te livrar, e entregar a ti os teus inimigos; pelo que o teu arraial será santo, para que ele não veja coisa feia em ti, e se aparte de ti.'),
('acf','dt',23,15,'Não entregarás a seu senhor o servo que, tendo fugido dele, se acolher a ti;'),
('acf','dt',23,16,'Contigo ficará, no meio de ti, no lugar que escolher em alguma das tuas portas, onde lhe agradar; não o oprimirás.'),
('acf','dt',23,17,'Não haverá prostituta dentre as filhas de Israel; nem haverá sodomita dentre os filhos de Israel.'),
('acf','dt',23,18,'Não trarás o salário da prostituta nem preço de um sodomita à casa do Senhor teu Deus por qualquer voto; porque ambos são igualmente abominação ao Senhor teu Deus.'),
('acf','dt',23,19,'A teu irmão não emprestarás com juros, nem dinheiro, nem comida, nem qualquer coisa que se empreste com juros.'),
('acf','dt',23,20,'Ao estranho emprestarás com juros, porém a teu irmão não emprestarás com juros; para que o Senhor teu Deus te abençoe em tudo que puseres a tua mão, na terra a qual vais a possuir.'),
('acf','dt',23,21,'Quando fizeres algum voto ao Senhor teu Deus, não tardarás em cumpri-lo; porque o Senhor teu Deus certamente o requererá de ti, e em ti haverá pecado.'),
('acf','dt',23,22,'Porém, abstendo-te de votar, não haverá pecado em ti.'),
('acf','dt',23,23,'O que saiu dos teus lábios guardarás, e cumprirás, tal como voluntariamente votaste ao Senhor teu Deus, declarando-o pela tua boca.'),
('acf','dt',23,24,'Quando entrares na vinha do teu próximo, comerás uvas conforme ao teu desejo até te fartares, porém não as porás no teu cesto.'),
('acf','dt',23,25,'Quando entrares na seara do teu próximo, com a tua mão arrancarás as espigas; porém não porás a foice na seara do teu próximo.'),
('acf','dt',24,1,'Quando um homem tomar uma mulher e se casar com ela, então será que, se não achar graça em seus olhos, por nela encontrar coisa indecente, far-lhe-á uma carta de repúdio, e lha dará na sua mão, e a despedirá da sua casa.'),
('acf','dt',24,2,'Se ela, pois, saindo da sua casa, for e se casar com outro homem,'),
('acf','dt',24,3,'E este também a desprezar, e lhe fizer carta de repúdio, e lha der na sua mão, e a despedir da sua casa, ou se este último homem, que a tomou para si por mulher, vier a morrer,'),
('acf','dt',24,4,'Então seu primeiro marido, que a despediu, não poderá tornar a tomá-la, para que seja sua mulher, depois que foi contaminada; pois é abominação perante o Senhor; assim não farás pecar a terra que o Senhor teu Deus te dá por herança.'),
('acf','dt',24,5,'Quando um homem for recém-casado não sairá à guerra, nem se lhe imporá encargo algum; por um ano inteiro ficará livre na sua casa para alegrar a mulher, que tomou.'),
('acf','dt',24,6,'Não se tomará em penhor ambas as mós, nem a mó de cima nem a de baixo; pois se penhoraria assim a vida.'),
('acf','dt',24,7,'Quando se achar alguém que tiver furtado um dentre os seus irmãos, dos filhos de Israel, e escravizá-lo, ou vendê-lo, esse ladrão morrerá, e tirarás o mal do meio de ti.'),
('acf','dt',24,8,'Guarda-te da praga da lepra, e tenhas grande cuidado de fazer conforme a tudo o que te ensinarem os sacerdotes levitas; como lhes tenho ordenado, terás cuidado de o fazer.'),
('acf','dt',24,9,'Lembra-te do que o Senhor teu Deus fez a Miriã no caminho, quando saíste do Egito.'),
('acf','dt',24,10,'Quando emprestares alguma coisa ao teu próximo, não entrarás em sua casa, para lhe tirar o penhor.'),
('acf','dt',24,11,'Fora ficarás; e o homem, a quem emprestaste, te trará fora o penhor.'),
('acf','dt',24,12,'Porém, se for homem pobre, não te deitarás com o seu penhor.'),
('acf','dt',24,13,'Em se pondo o sol, sem falta lhe restituirás o penhor; para que durma na sua roupa, e te abençoe; e isto te será justiça diante do Senhor teu Deus.'),
('acf','dt',24,14,'Não oprimirás o diarista pobre e necessitado de teus irmãos, ou de teus estrangeiros, que está na tua terra e nas tuas portas.'),
('acf','dt',24,15,'No seu dia lhe pagarás a sua diária, e o sol não se porá sobre isso; porquanto pobre é, e sua vida depende disso; para que não clame contra ti ao Senhor, e haja em ti pecado.'),
('acf','dt',24,16,'Os pais não morrerão pelos filhos, nem os filhos pelos pais; cada um morrerá pelo seu pecado.'),
('acf','dt',24,17,'Não perverterás o direito do estrangeiro e do órfão; nem tomarás em penhor a roupa da viúva.'),
('acf','dt',24,18,'Mas lembrar-te-ás de que foste servo no Egito, e de que o Senhor teu Deus te livrou dali; pelo que te ordeno que faças isso.'),
('acf','dt',24,19,'Quando no teu campo colheres a tua colheita, e esqueceres um molho no campo, não tornarás a tomá-lo; para o estrangeiro, para o órfão, e para a viúva será; para que o Senhor teu Deus te abençoe em toda a obra das tuas mãos,'),
('acf','dt',24,20,'Quando sacudires a tua oliveira, não voltarás para colher o fruto dos ramos; para o estrangeiro, para o órfão, e para a viúva será.'),
('acf','dt',24,21,'Quando vindimares a tua vinha, não voltarás para rebuscá-la; para o estrangeiro, para o órfão, e para a viúva será.'),
('acf','dt',24,22,'E lembrar-te-ás de que foste servo na terra do Egito; portanto te ordeno que faças isso.'),
('acf','dt',25,1,'Quando houver contenda entre alguns, e vierem a juízo, para que os julguem, ao justo justificarão, e ao injusto condenarão.'),
('acf','dt',25,2,'E será que, se o injusto merecer açoites, o juiz o fará deitar-se, para que seja açoitado diante de si; segundo a sua culpa, será o número de açoites.'),
('acf','dt',25,3,'Quarenta açoites lhe fará dar, não mais; para que, porventura, se lhe fizer dar mais açoites do que estes, teu irmão não fique envilecido aos teus olhos.'),
('acf','dt',25,4,'Não atarás a boca ao boi, quando trilhar.'),
('acf','dt',25,5,'Quando irmãos morarem juntos, e um deles morrer, e não tiver filho, então a mulher do falecido não se casará com homem estranho, de fora; seu cunhado estará com ela, e a receberá por mulher, e fará a obrigação de cunhado para com ela.'),
('acf','dt',25,6,'E o primogênito que ela lhe der será sucessor do nome do seu irmão falecido, para que o seu nome não se apague em Israel.'),
('acf','dt',25,7,'Porém, se o homem não quiser tomar sua cunhada, esta subirá à porta dos anciãos, e dirá: Meu cunhado recusa suscitar a seu irmão nome em Israel; não quer cumprir para comigo o dever de cunhado.'),
('acf','dt',25,8,'Então os anciãos da sua cidade o chamarão, e com ele falarão; e, se ele persistir, e disser: Não quero tomá-la;'),
('acf','dt',25,9,'Então sua cunhada se chegará a ele na presença dos anciãos, e lhe descalçará o sapato do pé, e lhe cuspirá no rosto, e protestará, e dirá: Assim se fará ao homem que não edificar a casa de seu irmão;'),
('acf','dt',25,10,'E o seu nome se chamará em Israel: A casa do descalçado.'),
('acf','dt',25,11,'Quando pelejarem dois homens, um contra o outro, e a mulher de um chegar para livrar a seu marido da mão do que o fere, e ela estender a sua mão, e lhe pegar pelas suas vergonhas,'),
('acf','dt',25,12,'Então cortar-lhe-ás a mão; não a poupará o teu olho.'),
('acf','dt',25,13,'Na tua bolsa não terás pesos diversos, um grande e um pequeno.'),
('acf','dt',25,14,'Na tua casa não terás dois tipos de efa, um grande e um pequeno.'),
('acf','dt',25,15,'Peso inteiro e justo terás; efa inteiro e justo terás; para que se prolonguem os teus dias na terra que te dará o Senhor teu Deus.'),
('acf','dt',25,16,'Porque abominação é ao Senhor teu Deus todo aquele que faz isto, todo aquele que fizer injustiça.'),
('acf','dt',25,17,'Lembra-te do que te fez Amaleque no caminho, quando saías do Egito;'),
('acf','dt',25,18,'Como te saiu ao encontro no caminho, e feriu na tua retaguarda todos os fracos que iam atrás de ti, estando tu cansado e afadigado; e não temeu a Deus.'),
('acf','dt',25,19,'Será, pois, que, quando o Senhor teu Deus te tiver dado repouso de todos os teus inimigos em redor, na terra que o Senhor teu Deus te dá por herança, para possuí-la, então apagarás a memória de Amaleque de debaixo do céu; não te esqueças.'),
('acf','dt',26,1,'E será que, quando entrares na terra que o SENHOR teu Deus te der por herança, e a possuíres, e nela habitares,'),
('acf','dt',26,2,'Então tomarás das primícias de todos os frutos do solo, que recolheres da terra, que te dá o Senhor teu Deus, e as porás num cesto, e irás ao lugar que escolher o Senhor teu Deus, para ali fazer habitar o seu nome.'),
('acf','dt',26,3,'E irás ao sacerdote, que houver naqueles dias, e dir-lhe-ás: Hoje declaro perante o Senhor teu Deus que entrei na terra que o Senhor jurou a nossos pais dar-nos.'),
('acf','dt',26,4,'E o sacerdote tomará o cesto da tua mão, e o porá diante do altar do Senhor teu Deus.'),
('acf','dt',26,5,'Então testificarás perante o Senhor teu Deus, e dirás: Arameu, prestes a perecer, foi meu pai, e desceu ao Egito, e ali peregrinou com pouca gente, porém ali cresceu até vir a ser nação grande, poderosa, e numerosa.'),
('acf','dt',26,6,'Mas os egípcios nos maltrataram e nos afligiram, e sobre nós impuseram uma dura servidão.'),
('acf','dt',26,7,'Então clamamos ao Senhor Deus de nossos pais; e o Senhor ouviu a nossa voz, e atentou para a nossa miséria, e para o nosso trabalho, e para a nossa opressão.'),
('acf','dt',26,8,'E o Senhor nos tirou do Egito com mão forte, e com braço estendido, e com grande espanto, e com sinais, e com milagres;'),
('acf','dt',26,9,'E nos trouxe a este lugar, e nos deu esta terra, terra que mana leite e mel.'),
('acf','dt',26,10,'E eis que agora eu trouxe as primícias dos frutos da terra que tu, ó Senhor, me deste. Então as porás perante o Senhor teu Deus, e te inclinarás perante o Senhor teu Deus,'),
('acf','dt',26,11,'E te alegrarás por todo o bem que o Senhor teu Deus te tem dado a ti e à tua casa, tu e o levita, e o estrangeiro que está no meio de ti.'),
('acf','dt',26,12,'Quando acabares de separar todos os dízimos da tua colheita no ano terceiro, que é o ano dos dízimos, então os darás ao levita, ao estrangeiro, ao órfão e à viúva, para que comam dentro das tuas portas, e se fartem;'),
('acf','dt',26,13,'E dirás perante o Senhor teu Deus: Tirei da minha casa as coisas consagradas e as dei também ao levita, e ao estrangeiro, e ao órfão e à viúva, conforme a todos os teus mandamentos que me tens ordenado; não transgredi os teus mandamentos, nem deles me esqueci;'),
('acf','dt',26,14,'Delas não comi no meu luto, nem delas nada tirei quando imundo, nem delas dei para os mortos; obedeci à voz do Senhor meu Deus; conforme a tudo o que me ordenaste, tenho feito.'),
('acf','dt',26,15,'Olha desde a tua santa habitação, desde o céu, e abençoa o teu povo, a Israel, e a terra que nos deste, como juraste a nossos pais, terra que mana leite e mel.'),
('acf','dt',26,16,'Neste dia, o Senhor teu Deus te manda cumprir estes estatutos e juízos; guarda-os pois, e cumpre-os com todo o teu coração e com toda a tua alma.'),
('acf','dt',26,17,'Hoje declaraste ao Senhor que ele te será por Deus, e que andarás nos seus caminhos, e guardarás os seus estatutos, e os seus mandamentos, e os seus juízos, e darás ouvidos à sua voz.'),
('acf','dt',26,18,'E o Senhor hoje te declarou que tu lhe serás por seu próprio povo, como te tem dito, e que guardarás todos os seus mandamentos.'),
('acf','dt',26,19,'Para assim te exaltar sobre todas as nações que criou, para louvor, e para fama, e para glória, e para que sejas um povo santo ao Senhor teu Deus, como tem falado.'),
('acf','dt',27,1,'E deram ordem, Moisés e os anciãos, ao povo de Israel, dizendo: Guardai todos estes mandamentos que hoje vos ordeno;'),
('acf','dt',27,2,'Será, pois, que, no dia em que passares o Jordão à terra que te der o Senhor teu Deus, levantar-te-ás umas pedras grandes, e as caiarás.'),
('acf','dt',27,3,'E, havendo-o passado, escreverás nelas todas as palavras desta lei, para entrares na terra que te der o Senhor teu Deus, terra que mana leite e mel, como te falou o Senhor Deus de teus pais.'),
('acf','dt',27,4,'Será, pois, que, quando houveres passado o Jordão, levantareis estas pedras, que hoje vos ordeno, no monte Ebal, e as caiarás.'),
('acf','dt',27,5,'E ali edificarás um altar ao Senhor teu Deus, um altar de pedras; não alçarás instrumento de ferro sobre elas.'),
('acf','dt',27,6,'De pedras brutas edificarás o altar do Senhor teu Deus; e sobre ele oferecerás holocaustos ao Senhor teu Deus.'),
('acf','dt',27,7,'Também sacrificarás ofertas pacíficas, e ali comerás perante o Senhor teu Deus, e te alegrarás.'),
('acf','dt',27,8,'E naquelas pedras escreverás todas as palavras desta lei, exprimindo-as nitidamente.'),
('acf','dt',27,9,'Falou mais Moisés, juntamente com os sacerdotes levitas, a todo o Israel, dizendo: Guarda silêncio e ouve, ó Israel! Hoje vieste a ser povo do Senhor teu Deus.'),
('acf','dt',27,10,'Portanto obedecerás à voz do Senhor teu Deus, e cumprirás os seus mandamentos e os seus estatutos que hoje te ordeno.'),
('acf','dt',27,11,'E Moisés deu ordem naquele dia ao povo, dizendo:'),
('acf','dt',27,12,'Quando houverdes passado o Jordão, estes estarão sobre o monte Gerizim, para abençoarem o povo: Simeão, e Levi, e Judá, e Issacar, e José, e Benjamim;'),
('acf','dt',27,13,'E estes estarão sobre o monte Ebal para amaldiçoar: Rúben, Gade, e Aser, e Zebulom, Dã e Naftali.'),
('acf','dt',27,14,'E os levitas testificarão a todo o povo de Israel em alta voz, e dirão:'),
('acf','dt',27,15,'Maldito o homem que fizer imagem de escultura, ou de fundição, abominação ao Senhor, obra da mão do artífice, e a puser em um lugar escondido. E todo o povo, respondendo, dirá: Amém.'),
('acf','dt',27,16,'Maldito aquele que desprezar a seu pai ou a sua mãe. E todo o povo dirá: Amém.'),
('acf','dt',27,17,'Maldito aquele que remover os limites do seu próximo. E todo o povo dirá: Amém.'),
('acf','dt',27,18,'Maldito aquele que fizer que o cego erre de caminho. E todo o povo dirá: Amém.'),
('acf','dt',27,19,'Maldito aquele que perverter o direito do estrangeiro, do órfão e da viúva. E todo o povo dirá: Amém.'),
('acf','dt',27,20,'Maldito aquele que se deitar com a mulher de seu pai, porquanto descobriu a nudez de seu pai. E todo o povo dirá: Amém.'),
('acf','dt',27,21,'Maldito aquele que se deitar com algum animal. E todo o povo dirá: Amém.'),
('acf','dt',27,22,'Maldito aquele que se deitar com sua irmã, filha de seu pai, ou filha de sua mãe. E todo o povo dirá: Amém.'),
('acf','dt',27,23,'Maldito aquele que se deitar com sua sogra. E todo o povo dirá: Amém.'),
('acf','dt',27,24,'Maldito aquele que ferir ao seu próximo em oculto. E todo o povo dirá: Amém.'),
('acf','dt',27,25,'Maldito aquele que aceitar suborno para ferir uma pessoa inocente. E todo o povo dirá: Amém.'),
('acf','dt',27,26,'Maldito aquele que não confirmar as palavras desta lei, não as cumprindo. E todo o povo dirá: Amém.'),
('acf','dt',28,1,'E será que, se ouvires a voz do SENHOR teu Deus, tendo cuidado de guardar todos os seus mandamentos que eu hoje te ordeno, o SENHOR teu Deus te exaltará sobre todas as nações da terra.'),
('acf','dt',28,2,'E todas estas bênçãos virão sobre ti e te alcançarão, quando ouvires a voz do Senhor teu Deus:'),
('acf','dt',28,3,'Bendito serás na cidade, e bendito serás no campo.'),
('acf','dt',28,4,'Bendito o fruto do teu ventre, e o fruto da tua terra, e o fruto dos teus animais; e as crias das tuas vacas e das tuas ovelhas.'),
('acf','dt',28,5,'Bendito o teu cesto e a tua amassadeira.'),
('acf','dt',28,6,'Bendito serás ao entrares, e bendito serás ao saíres.'),
('acf','dt',28,7,'O Senhor entregará, feridos diante de ti, os teus inimigos, que se levantarem contra ti; por um caminho sairão contra ti, mas por sete caminhos fugirão da tua presença.'),
('acf','dt',28,8,'O Senhor mandará que a bênção esteja contigo nos teus celeiros, e em tudo o que puseres a tua mão; e te abençoará na terra que te der o Senhor teu Deus.'),
('acf','dt',28,9,'O Senhor te confirmará para si como povo santo, como te tem jurado, quando guardares os mandamentos do Senhor teu Deus, e andares nos seus caminhos.'),
('acf','dt',28,10,'E todos os povos da terra verão que é invocado sobre ti o nome do Senhor, e terão temor de ti.'),
('acf','dt',28,11,'E o Senhor te dará abundância de bens no fruto do teu ventre, e no fruto dos teus animais, e no fruto do teu solo, sobre a terra que o Senhor jurou a teus pais te dar.'),
('acf','dt',28,12,'O Senhor te abrirá o seu bom tesouro, o céu, para dar chuva à tua terra no seu tempo, e para abençoar toda a obra das tuas mãos; e emprestarás a muitas nações, porém tu não tomarás emprestado.'),
('acf','dt',28,13,'E o Senhor te porá por cabeça, e não por cauda; e só estarás em cima, e não debaixo, se obedeceres aos mandamentos do Senhor teu Deus, que hoje te ordeno, para os guardar e cumprir.'),
('acf','dt',28,14,'E não te desviarás de todas as palavras que hoje te ordeno, nem para a direita nem para a esquerda, andando após outros deuses, para os servires.'),
('acf','dt',28,15,'Será, porém, que, se não deres ouvidos à voz do Senhor teu Deus, para não cuidares em cumprir todos os seus mandamentos e os seus estatutos, que hoje te ordeno, então virão sobre ti todas estas maldições, e te alcançarão:'),
('acf','dt',28,16,'Maldito serás tu na cidade, e maldito serás no campo.'),
('acf','dt',28,17,'Maldito o teu cesto e a tua amassadeira.'),
('acf','dt',28,18,'Maldito o fruto do teu ventre, e o fruto da tua terra, e as crias das tuas vacas, e das tuas ovelhas.'),
('acf','dt',28,19,'Maldito serás ao entrares, e maldito serás ao saíres.'),
('acf','dt',28,20,'O Senhor mandará sobre ti a maldição; a confusão e a derrota em tudo em que puseres a mão para fazer; até que sejas destruído, e até que repentinamente pereças, por causa da maldade das tuas obras, pelas quais me deixaste.'),
('acf','dt',28,21,'O Senhor fará pegar em ti a pestilência, até que te consuma da terra a que passas a possuir.'),
('acf','dt',28,22,'O Senhor te ferirá com a tísica e com a febre, e com a inflamação, e com o calor ardente, e com a secura, e com crestamento e com ferrugem; e te perseguirão até que pereças.'),
('acf','dt',28,23,'E os teus céus, que estão sobre a cabeça, serão de bronze; e a terra que está debaixo de ti, será de ferro.'),
('acf','dt',28,24,'O Senhor dará por chuva sobre a tua terra, pó e poeira; dos céus descerá sobre ti, até que pereças.'),
('acf','dt',28,25,'O Senhor te fará cair diante dos teus inimigos; por um caminho sairás contra eles, e por sete caminhos fugirás de diante deles, e serás espalhado por todos os reinos da terra.'),
('acf','dt',28,26,'E o teu cadáver servirá de comida a todas as aves dos céus, e aos animais da terra; e ninguém os espantará.'),
('acf','dt',28,27,'O Senhor te ferirá com as úlceras do Egito, com tumores, e com sarna, e com coceira, de que não possas curar-te;'),
('acf','dt',28,28,'O Senhor te ferirá com loucura, e com cegueira, e com pasmo de coração;'),
('acf','dt',28,29,'E apalparás ao meio-dia, como o cego apalpa na escuridão, e não prosperarás nos teus caminhos; porém somente serás oprimido e roubado todos os dias, e não haverá quem te salve.'),
('acf','dt',28,30,'Desposar-te-ás com uma mulher, porém outro homem dormirá com ela; edificarás uma casa, porém não morarás nela; plantarás uma vinha, porém não aproveitarás o seu fruto.'),
('acf','dt',28,31,'O teu boi será morto aos teus olhos, porém dele não comerás; o teu jumento será roubado diante de ti, e não voltará a ti; as tuas ovelhas serão dadas aos teus inimigos, e não haverá quem te salve.'),
('acf','dt',28,32,'Teus filhos e tuas filhas serão dados a outro povo, os teus olhos o verão, e por eles desfalecerão todo o dia; porém não haverá poder na tua mão.'),
('acf','dt',28,33,'O fruto da tua terra e todo o teu trabalho, comerá um povo que nunca conheceste; e tu serás oprimido e quebrantado todos os dias.'),
('acf','dt',28,34,'E enlouquecerás com o que vires com os teus olhos.'),
('acf','dt',28,35,'O Senhor te ferirá com úlceras malignas nos joelhos e nas pernas, de que não possas sarar, desde a planta do teu pé até ao alto da cabeça.'),
('acf','dt',28,36,'O Senhor te levará a ti e a teu rei, que tiveres posto sobre ti, a uma nação que não conheceste, nem tu nem teus pais; e ali servirás a outros deuses, ao pau e à pedra.'),
('acf','dt',28,37,'E serás por pasmo, por ditado, e por fábula, entre todos os povos a que o Senhor te levará.'),
('acf','dt',28,38,'Lançarás muita semente ao campo; porém colherás pouco, porque o gafanhoto a consumirá.'),
('acf','dt',28,39,'Plantarás vinhas, e cultivarás; porém não beberás vinho, nem colherás as uvas; porque o bicho as colherá.'),
('acf','dt',28,40,'Em todos os termos terás oliveiras; porém não te ungirás com azeite; porque a azeitona cairá da tua oliveira.'),
('acf','dt',28,41,'Filhos e filhas gerarás; porém não serão para ti; porque irão em cativeiro.'),
('acf','dt',28,42,'Todo o teu arvoredo e o fruto da tua terra consumirá a lagarta.'),
('acf','dt',28,43,'O estrangeiro, que está no meio de ti, se elevará muito sobre ti, e tu mais baixo descerás;'),
('acf','dt',28,44,'Ele te emprestará a ti, porém tu não emprestarás a ele; ele será por cabeça, e tu serás por cauda.'),
('acf','dt',28,45,'E todas estas maldições virão sobre ti, e te perseguirão, e te alcançarão, até que sejas destruído; porquanto não ouviste à voz do Senhor teu Deus, para guardares os seus mandamentos, e os seus estatutos, que te tem ordenado;'),
('acf','dt',28,46,'E serão entre ti por sinal e por maravilha, como também entre a tua descendência para sempre.'),
('acf','dt',28,47,'Porquanto não serviste ao Senhor teu Deus com alegria e bondade de coração, pela abundância de tudo.'),
('acf','dt',28,48,'Assim servirás aos teus inimigos, que o Senhor enviará contra ti, com fome e com sede, e com nudez, e com falta de tudo; e sobre o teu pescoço porá um jugo de ferro, até que te tenha destruído.'),
('acf','dt',28,49,'O Senhor levantará contra ti uma nação de longe, da extremidade da terra, que voa como a águia, nação cuja língua não entenderás;'),
('acf','dt',28,50,'Nação feroz de rosto, que não respeitará o rosto do velho, nem se apiedará do moço;'),
('acf','dt',28,51,'E comerá o fruto dos teus animais, e o fruto da tua terra, até que sejas destruído; e não te deixará grão, mosto, nem azeite, nem crias das tuas vacas, nem das tuas ovelhas, até que te haja consumido;'),
('acf','dt',28,52,'E sitiar-te-á em todas as tuas portas, até que venham a cair os teus altos e fortes muros, em que confiavas em toda a tua terra; e te sitiará em todas as tuas portas, em toda a tua terra que te tem dado o Senhor teu Deus.'),
('acf','dt',28,53,'E comerás o fruto do teu ventre, a carne de teus filhos e de tuas filhas, que te der o Senhor teu Deus, no cerco e no aperto com que os teus inimigos te apertarão.'),
('acf','dt',28,54,'Quanto ao homem mais mimoso e delicado no meio de ti, o seu olho será maligno para com o seu irmão, e para com a mulher do seu regaço, e para com os demais de seus filhos que ainda lhe ficarem;'),
('acf','dt',28,55,'De sorte que não dará a nenhum deles da carne de seus filhos, que ele comer; porquanto nada lhe ficou de resto no cerco e no aperto, com que o teu inimigo te apertará em todas as tuas portas.'),
('acf','dt',28,56,'E quanto à mulher mais mimosa e delicada no meio de ti, que de mimo e delicadeza nunca tentou pôr a planta de seu pé sobre a terra, será maligno o seu olho contra o homem de seu regaço, e contra seu filho, e contra sua filha;'),
('acf','dt',28,57,'E isto por causa de suas páreas, que saírem dentre os seus pés, e para com os seus filhos que tiver, porque os comerá às escondidas pela falta de tudo, no cerco e no aperto, com que o teu inimigo te apertará nas tuas portas.'),
('acf','dt',28,58,'Se não tiveres cuidado de guardar todas as palavras desta lei, que estão escritas neste livro, para temeres este nome glorioso e temível, o SENHOR TEU DEUS,'),
('acf','dt',28,59,'Então o Senhor fará espantosas as tuas pragas, e as pragas de tua descendência, grandes e permanentes pragas, e enfermidades malignas e duradouras;'),
('acf','dt',28,60,'E fará tornar sobre ti todos os males do Egito, de que tu tiveste temor, e se apegarão a ti.'),
('acf','dt',28,61,'Também o Senhor fará vir sobre ti toda a enfermidade e toda a praga, que não está escrita no livro desta lei, até que sejas destruído.'),
('acf','dt',28,62,'E ficareis poucos em número, em lugar de haverem sido como as estrelas dos céus em multidão; porquanto não destes ouvidos à voz do Senhor teu Deus.'),
('acf','dt',28,63,'E será que, assim como o Senhor se deleitava em vós, em fazer-vos bem e multiplicar-vos, assim o Senhor se deleitará em destruir-vos e consumir-vos; e desarraigados sereis da terra a qual passais a possuir.'),
('acf','dt',28,64,'E o Senhor vos espalhará entre todos os povos, desde uma extremidade da terra até à outra; e ali servireis a outros deuses que não conheceste, nem tu nem teus pais; ao pau e à pedra.'),
('acf','dt',28,65,'E nem ainda entre estas nações descansarás, nem a planta de teu pé terá repouso; porquanto o Senhor ali te dará coração agitado, e desfalecimento de olhos, e desmaio da alma.'),
('acf','dt',28,66,'E a tua vida, como em suspenso, estará diante de ti; e estremecerás de noite e de dia, e não crerás na tua própria vida.'),
('acf','dt',28,67,'Pela manhã dirás: Ah! quem me dera ver a noite! E à tarde dirás: ah! quem me dera ver a manhã! pelo pasmo de teu coração, que sentirás, e pelo que verás com os teus olhos.'),
('acf','dt',28,68,'E o Senhor te fará voltar ao Egito em navios, pelo caminho de que te tenho dito; nunca jamais o verás; e ali sereis vendidos como escravos e escravas aos vossos inimigos; mas não haverá quem vos compre.'),
('acf','dt',29,1,'Estas são as palavras da aliança que o SENHOR ordenou a Moisés que fizesse com os filhos de Israel, na terra de Moabe, além da aliança que fizera com eles em Horebe.'),
('acf','dt',29,2,'E chamou Moisés a todo o Israel, e disse-lhes: Tendes visto tudo quanto o Senhor fez perante vossos olhos, na terra do Egito, a Faraó, e a todos os seus servos, e a toda a sua terra;'),
('acf','dt',29,3,'As grandes provas que os teus olhos têm visto, aqueles sinais e grandes maravilhas;'),
('acf','dt',29,4,'Porém não vos tem dado o Senhor um coração para entender, nem olhos para ver, nem ouvidos para ouvir, até ao dia de hoje.'),
('acf','dt',29,5,'E quarenta anos vos fiz andar pelo deserto; não se envelheceram sobre vós as vossas vestes, e nem se envelheceu o vosso sapato no vosso pé.'),
('acf','dt',29,6,'Pão não comestes, e vinho e bebida forte não bebestes; para que soubésseis que eu sou o Senhor vosso Deus.'),
('acf','dt',29,7,'Vindo vós, pois, a este lugar, Siom, rei de Hesbom, e Ogue, rei de Basã, nos saíram ao encontro, à peleja, e nós os ferimos;'),
('acf','dt',29,8,'E tomamos a sua terra e a demos por herança aos rubenitas, e aos gaditas, e à meia tribo dos manassitas.'),
('acf','dt',29,9,'Guardai, pois, as palavras desta aliança, e cumpri-as, para que prospereis em tudo quanto fizerdes.'),
('acf','dt',29,10,'Vós todos estais hoje perante o Senhor vosso Deus; os capitães de vossas tribos, vossos anciãos, e os vossos oficiais, todos os homens de Israel;'),
('acf','dt',29,11,'Os vossos meninos, as vossas mulheres, e o estrangeiro que está no meio do vosso arraial; desde o rachador da vossa lenha até ao tirador da vossa água;'),
('acf','dt',29,12,'Para entrardes na aliança do Senhor teu Deus, e no seu juramento que o Senhor teu Deus hoje faz convosco;'),
('acf','dt',29,13,'Para que hoje te confirme por seu povo, e ele te seja por Deus, como te tem dito, e como jurou a teus pais, Abraão, Isaque e Jacó.'),
('acf','dt',29,14,'E não somente convosco faço esta aliança e este juramento;'),
('acf','dt',29,15,'Mas com aquele que hoje está aqui em pé conosco perante o Senhor nosso Deus, e com aquele que hoje não está aqui conosco.'),
('acf','dt',29,16,'Porque vós sabeis como habitamos na terra do Egito, e como passamos pelo meio das nações pelas quais passastes;'),
('acf','dt',29,17,'E vistes as suas abominações, e os seus ídolos, o pau e a pedra, a prata e o ouro que havia entre eles,'),
('acf','dt',29,18,'Para que entre vós não haja homem, nem mulher, nem família, nem tribo, cujo coração hoje se desvie do Senhor nosso Deus, para que vá servir aos deuses destas nações; para que entre vós não haja raiz que dê veneno e fel;'),
('acf','dt',29,19,'E aconteça que, alguém ouvindo as palavras desta maldição, se abençoe no seu coração, dizendo: Terei paz, ainda que ande conforme o parecer do meu coração; para acrescentar à sede a bebedeira.'),
('acf','dt',29,20,'O Senhor não lhe quererá perdoar; mas fumegará a ira do Senhor e o seu zelo contra esse homem, e toda a maldição escrita neste livro pousará sobre ele; e o Senhor apagará o seu nome de debaixo do céu.'),
('acf','dt',29,21,'E o Senhor o separará para mal, de todas as tribos de Israel, conforme a todas as maldições da aliança escrita no livro desta lei.'),
('acf','dt',29,22,'Então dirá à geração vindoura, os vossos filhos, que se levantarem depois de vós, e o estrangeiro que virá de terras remotas, vendo as pragas desta terra, e as suas doenças, com que o Senhor a terá afligido;'),
('acf','dt',29,23,'E toda a sua terra abrasada com enxofre, e sal, de sorte que não será semeada, e nada produzirá, nem nela crescerá erva alguma; assim como foi a destruição de Sodoma e de Gomorra, de Admá e de Zeboim, que o Senhor destruiu na sua ira e no seu furor.'),
('acf','dt',29,24,'E todas as nações dirão: Por que fez o Senhor assim com esta terra? Qual foi a causa do furor desta tão grande ira?'),
('acf','dt',29,25,'Então se dirá: Porquanto deixaram a aliança do Senhor Deus de seus pais, que com eles tinha feito, quando os tirou do Egito;'),
('acf','dt',29,26,'E foram, e serviram a outros deuses, e se inclinaram diante deles; deuses que eles não conheceram, e nenhum dos quais lhes tinha sido dado.'),
('acf','dt',29,27,'Por isso a ira do Senhor se acendeu contra esta terra, para trazer sobre ela toda a maldição que está escrita neste livro.'),
('acf','dt',29,28,'E o Senhor os arrancou da sua terra com ira, e com indignação, e com grande furor, e os lançou em outra terra como neste dia se vê.'),
('acf','dt',29,29,'As coisas encobertas pertencem ao Senhor nosso Deus, porém as reveladas nos pertencem a nós e a nossos filhos para sempre, para que cumpramos todas as palavras desta lei.'),
('acf','dt',30,1,'E será que, sobrevindo-te todas estas coisas, a bênção ou a maldição, que tenho posto diante de ti, e te recordares delas entre todas as nações, para onde te lançar o SENHOR teu Deus,'),
('acf','dt',30,2,'E te converteres ao Senhor teu Deus, e deres ouvidos à sua voz, conforme a tudo o que eu te ordeno hoje, tu e teus filhos, com todo o teu coração, e com toda a tua alma,'),
('acf','dt',30,3,'Então o Senhor teu Deus te fará voltar do teu cativeiro, e se compadecerá de ti, e tornará a ajuntar-te dentre todas as nações entre as quais te espalhou o Senhor teu Deus.'),
('acf','dt',30,4,'Ainda que os teus desterrados estejam na extremidade do céu, desde ali te ajuntará o Senhor teu Deus, e te tomará dali;'),
('acf','dt',30,5,'E o Senhor teu Deus te trará à terra que teus pais possuíram, e a possuirás; e te fará bem, e te multiplicará mais do que a teus pais.'),
('acf','dt',30,6,'E o Senhor teu Deus circuncidará o teu coração, e o coração de tua descendência, para amares ao Senhor teu Deus com todo o coração, e com toda a tua alma, para que vivas.'),
('acf','dt',30,7,'E o Senhor teu Deus porá todas estas maldições sobre os teus inimigos, e sobre os que te odiarem, que te perseguirem.'),
('acf','dt',30,8,'Converter-te-ás, pois, e darás ouvidos à voz do Senhor; cumprirás todos os seus mandamentos que hoje te ordeno.'),
('acf','dt',30,9,'E o Senhor teu Deus te fará prosperar em toda a obra das tuas mãos, no fruto do teu ventre, e no fruto dos teus animais, e no fruto da tua terra para o teu bem; porquanto o Senhor tornará a alegrar-se em ti para te fazer bem, como se alegrou em teus pais,'),
('acf','dt',30,10,'Quando deres ouvidos à voz do Senhor teu Deus, guardando os seus mandamentos e os seus estatutos, escritos neste livro da lei, quando te converteres ao Senhor teu Deus com todo o teu coração, e com toda a tua alma.'),
('acf','dt',30,11,'Porque este mandamento, que hoje te ordeno, não te é encoberto, e tampouco está longe de ti.'),
('acf','dt',30,12,'Não está nos céus, para dizeres: Quem subirá por nós aos céus, que no-lo traga, e no-lo faça ouvir, para que o cumpramos?'),
('acf','dt',30,13,'Nem tampouco está além do mar, para dizeres: Quem passará por nós além do mar, para que no-lo traga, e no-lo faça ouvir, para que o cumpramos?'),
('acf','dt',30,14,'Porque esta palavra está mui perto de ti, na tua boca, e no teu coração, para a cumprires.'),
('acf','dt',30,15,'Vês aqui, hoje te tenho proposto a vida e o bem, e a morte e o mal;'),
('acf','dt',30,16,'Porquanto te ordeno hoje que ames ao Senhor teu Deus, que andes nos seus caminhos, e que guardes os seus mandamentos, e os seus estatutos, e os seus juízos, para que vivas, e te multipliques, e o Senhor teu Deus te abençoe na terra a qual entras a possuir.'),
('acf','dt',30,17,'Porém se o teu coração se desviar, e não quiseres dar ouvidos, e fores seduzido para te inclinares a outros deuses, e os servires,'),
('acf','dt',30,18,'Então eu vos declaro hoje que, certamente, perecereis; não prolongareis os dias na terra a que vais, passando o Jordão, para que, entrando nela, a possuas;'),
('acf','dt',30,19,'Os céus e a terra tomo hoje por testemunhas contra vós, de que te tenho proposto a vida e a morte, a bênção e a maldição; escolhe pois a vida, para que vivas, tu e a tua descendência,'),
('acf','dt',30,20,'Amando ao Senhor teu Deus, dando ouvidos à sua voz, e achegando-te a ele; pois ele é a tua vida, e o prolongamento dos teus dias; para que fiques na terra que o Senhor jurou a teus pais, a Abraão, a Isaque, e a Jacó, que lhes havia de dar.'),
('acf','dt',31,1,'Depois foi Moisés, e falou estas palavras a todo o Israel,'),
('acf','dt',31,2,'E disse-lhes: Da idade de cento e vinte anos sou eu hoje; já não poderei mais sair e entrar; além disto o Senhor me disse: Não passarás o Jordão.'),
('acf','dt',31,3,'O Senhor teu Deus passará adiante de ti; ele destruirá estas nações de diante de ti, para que as possuas; Josué passará adiante de ti, como o Senhor tem falado.'),
('acf','dt',31,4,'E o Senhor lhes fará como fez a Siom e a Ogue, reis dos amorreus, e à sua terra, os quais destruiu.'),
('acf','dt',31,5,'Quando, pois, o Senhor vo-los der diante de vós, então com eles fareis conforme a todo o mandamento que vos tenho ordenado.'),
('acf','dt',31,6,'Esforçai-vos, e animai-vos; não temais, nem vos espanteis diante deles; porque o Senhor teu Deus é o que vai contigo; não te deixará nem te desamparará.'),
('acf','dt',31,7,'E chamou Moisés a Josué, e lhe disse aos olhos de todo o Israel: Esforça-te e anima-te; porque com este povo entrarás na terra que o Senhor jurou a teus pais lhes dar; e tu os farás herdá-la.'),
('acf','dt',31,8,'O Senhor, pois, é aquele que vai adiante de ti; ele será contigo, não te deixará, nem te desamparará; não temas, nem te espantes.'),
('acf','dt',31,9,'E Moisés escreveu esta lei, e a deu aos sacerdotes, filhos de Levi, que levavam a arca da aliança do Senhor, e a todos os anciãos de Israel.'),
('acf','dt',31,10,'E ordenou-lhes Moisés, dizendo: Ao fim de cada sete anos, no tempo determinado do ano da remissão, na festa dos tabernáculos,'),
('acf','dt',31,11,'Quando todo o Israel vier a comparecer perante o Senhor teu Deus, no lugar que ele escolher, lerás esta lei diante de todo o Israel aos seus ouvidos.'),
('acf','dt',31,12,'Ajunta o povo, os homens e as mulheres, os meninos e os estrangeiros que estão dentro das tuas portas, para que ouçam e aprendam e temam ao Senhor vosso Deus, e tenham cuidado de fazer todas as palavras desta lei;'),
('acf','dt',31,13,'E que seus filhos, que não a souberem, ouçam e aprendam a temer ao Senhor vosso Deus, todos os dias que viverdes sobre a terra a qual ides, passando o Jordão, para a possuir.'),
('acf','dt',31,14,'E disse o Senhor a Moisés: Eis que os teus dias são chegados, para que morras; chama a Josué, e apresentai-vos na tenda da congregação, para que eu lhe dê ordens. Assim foram Moisés e Josué, e se apresentaram na tenda da congregação.'),
('acf','dt',31,15,'Então o Senhor apareceu na tenda, na coluna de nuvem; e a coluna de nuvem estava sobre a porta da tenda.'),
('acf','dt',31,16,'E disse o Senhor a Moisés: Eis que dormirás com teus pais; e este povo se levantará, e prostituir-se-á indo após os deuses estranhos na terra, para cujo meio vai, e me deixará, e anulará a minha aliança que tenho feito com ele.'),
('acf','dt',31,17,'Assim se acenderá a minha ira naquele dia contra ele, e desampará-lo-ei, e esconderei o meu rosto dele, para que seja devorado; e tantos males e angústias o alcançarão, que dirá naquele dia: Não me alcançaram estes males, porque o meu Deus não está no meio de mim?'),
('acf','dt',31,18,'Esconderei, pois, totalmente o meu rosto naquele dia, por todo o mal que tiver feito, por se haverem tornado a outros deuses.'),
('acf','dt',31,19,'Agora, pois, escrevei-vos este cântico, e ensinai-o aos filhos de Israel; ponde-o na sua boca, para que este cântico me seja por testemunha contra os filhos de Israel.'),
('acf','dt',31,20,'Porque introduzirei o meu povo na terra que jurei a seus pais, que mana leite e mel; e comerá, e se fartará, e se engordará; então se tornará a outros deuses, e os servirá, e me irritarão, e anularão a minha aliança.'),
('acf','dt',31,21,'E será que, quando o alcançarem muitos males e angústias, então este cântico responderá contra ele por testemunha, pois não será esquecido da boca de sua descendência; porquanto conheço a sua imaginação, o que ele faz hoje, antes que o introduza na terra que tenho jurado.'),
('acf','dt',31,22,'Assim Moisés escreveu este cântico naquele dia, e o ensinou aos filhos de Israel.'),
('acf','dt',31,23,'E ordenou a Josué, filho de Num, e disse: Esforça-te e anima-te; porque tu introduzirás os filhos de Israel na terra que lhes jurei; e eu serei contigo.'),
('acf','dt',31,24,'E aconteceu que, acabando Moisés de escrever num livro, todas as palavras desta lei,'),
('acf','dt',31,25,'Deu ordem aos levitas, que levavam a arca da aliança do Senhor, dizendo:'),
('acf','dt',31,26,'Tomai este livro da lei, e ponde-o ao lado da arca da aliança do Senhor vosso Deus, para que ali esteja por testemunha contra ti.'),
('acf','dt',31,27,'Porque conheço a tua rebelião e a tua dura cerviz; eis que, vivendo eu ainda hoje convosco, rebeldes fostes contra o Senhor; e quanto mais depois da minha morte?'),
('acf','dt',31,28,'Ajuntai perante mim todos os anciãos das vossas tribos, e vossos oficiais, e aos seus ouvidos falarei estas palavras, e contra eles por testemunhas tomarei o céu e a terra.'),
('acf','dt',31,29,'Porque eu sei que depois da minha morte certamente vos corrompereis, e vos desviareis do caminho que vos ordenei; então este mal vos alcançará nos últimos dias, quando fizerdes mal aos olhos do Senhor, para o provocar à ira com a obra das vossas mãos.'),
('acf','dt',31,30,'Então Moisés falou as palavras deste cântico aos ouvidos de toda a congregação de Israel, até se acabarem.'),
('acf','dt',32,1,'Inclinai os ouvidos, ó céus, e falarei; e ouça a terra as palavras da minha boca.'),
('acf','dt',32,2,'Goteje a minha doutrina como a chuva, destile a minha palavra como o orvalho, como chuvisco sobre a erva e como gotas de água sobre a relva.'),
('acf','dt',32,3,'Porque apregoarei o nome do Senhor; engrandecei a nosso Deus.'),
('acf','dt',32,4,'Ele é a Rocha, cuja obra é perfeita, porque todos os seus caminhos justos são; Deus é a verdade, e não há nele injustiça; justo e reto é.'),
('acf','dt',32,5,'Corromperam-se contra ele; não são seus filhos, mas a sua mancha; geração perversa e distorcida é.'),
('acf','dt',32,6,'Recompensais assim ao Senhor, povo louco e ignorante? Não é ele teu pai que te adquiriu, te fez e te estabeleceu?'),
('acf','dt',32,7,'Lembra-te dos dias da antiguidade, atenta para os anos de muitas gerações: pergunta a teu pai, e ele te informará; aos teus anciãos, e eles te dirão.'),
('acf','dt',32,8,'Quando o Altíssimo distribuía as heranças às nações, quando dividia os filhos de Adão uns dos outros, estabeleceu os termos dos povos, conforme o número dos filhos de Israel.'),
('acf','dt',32,9,'Porque a porção do Senhor é o seu povo; Jacó é a parte da sua herança.'),
('acf','dt',32,10,'Achou-o numa terra deserta, e num ermo solitário cheio de uivos; cercou-o, instruiu-o, e guardou-o como a menina do seu olho.'),
('acf','dt',32,11,'Como a águia desperta a sua ninhada, move-se sobre os seus filhos, estende as suas asas, toma-os, e os leva sobre as suas asas,'),
('acf','dt',32,12,'Assim só o Senhor o guiou; e não havia com ele deus estranho.'),
('acf','dt',32,13,'Ele o fez cavalgar sobre as alturas da terra, e comer os frutos do campo, e o fez chupar mel da rocha e azeite da dura pederneira.'),
('acf','dt',32,14,'Manteiga de vacas, e leite de ovelhas, com a gordura dos cordeiros e dos carneiros que pastam em Basã, e dos bodes, com o mais escolhido trigo; e bebeste o sangue das uvas, o vinho puro.'),
('acf','dt',32,15,'E, engordando-se Jesurum, deu coices (engordaste-te, engrossaste-te, e de gordura te cobriste) e deixou a Deus, que o fez, e desprezou a Rocha da sua salvação.'),
('acf','dt',32,16,'Com deuses estranhos o provocaram a zelos; com abominações o irritaram.'),
('acf','dt',32,17,'Sacrifícios ofereceram aos demônios, não a Deus; aos deuses que não conheceram, novos deuses que vieram há pouco, aos quais não temeram vossos pais.'),
('acf','dt',32,18,'Esqueceste-te da Rocha que te gerou; e em esquecimento puseste o Deus que te formou;'),
('acf','dt',32,19,'O que vendo o Senhor, os desprezou, por ter sido provocado à ira contra seus filhos e suas filhas;'),
('acf','dt',32,20,'E disse: Esconderei o meu rosto deles, verei qual será o seu fim; porque são geração perversa, filhos em quem não há lealdade.'),
('acf','dt',32,21,'A zelos me provocaram com aquilo que não é Deus; com as suas vaidades me provocaram à ira: portanto eu os provocarei a zelos com o que não é povo; com nação louca os despertarei à ira.'),
('acf','dt',32,22,'Porque um fogo se acendeu na minha ira, e arderá até ao mais profundo do inferno, e consumirá a terra com a sua colheita, e abrasará os fundamentos dos montes.'),
('acf','dt',32,23,'Males amontoarei sobre eles; as minhas setas esgotarei contra eles.'),
('acf','dt',32,24,'Consumidos serão de fome, comidos pela febre ardente e de peste amarga; e contra eles enviarei dentes de feras, com ardente veneno de serpentes do pó.'),
('acf','dt',32,25,'Por fora devastará a espada, e por dentro o pavor; ao jovem, juntamente com a virgem, assim à criança de peito como ao homem encanecido.'),
('acf','dt',32,26,'Eu disse: Por todos os cantos os espalharei; farei cessar a sua memória dentre os homens,'),
('acf','dt',32,27,'Se eu não receasse a ira do inimigo, para que os seus adversários não se iludam, e para que não digam: A nossa mão está exaltada; o Senhor não fez tudo isto.'),
('acf','dt',32,28,'Porque são gente falta de conselhos, e neles não há entendimento.'),
('acf','dt',32,29,'Quem dera eles fossem sábios! Que isto entendessem, e atentassem para o seu fim!'),
('acf','dt',32,30,'Como poderia ser que um só perseguisse mil, e dois fizessem fugir dez mil, se a sua Rocha os não vendera, e o Senhor os não entregara?'),
('acf','dt',32,31,'Porque a sua rocha não é como a nossa Rocha, sendo até os nossos inimigos juízes disto.'),
('acf','dt',32,32,'Porque a sua vinha é a vinha de Sodoma e dos campos de Gomorra; as suas uvas são uvas venenosas, cachos amargos têm.'),
('acf','dt',32,33,'O seu vinho é ardente veneno de serpentes, e peçonha cruel de víboras.'),
('acf','dt',32,34,'Não está isto guardado comigo? Selado nos meus tesouros?'),
('acf','dt',32,35,'Minha é a vingança e a recompensa, ao tempo que resvalar o seu pé; porque o dia da sua ruína está próximo, e as coisas que lhes hão de suceder, se apressam a chegar.'),
('acf','dt',32,36,'Porque o Senhor fará justiça ao seu povo, e se compadecerá de seus servos; quando vir que o poder deles se foi, e não há preso nem desamparado.'),
('acf','dt',32,37,'Então dirá: Onde estão os seus deuses? A rocha em quem confiavam,'),
('acf','dt',32,38,'De cujos sacrifícios comiam a gordura, e de cujas libações bebiam o vinho? Levantem-se, e vos ajudem, para que haja para vós esconderijo.'),
('acf','dt',32,39,'Vede agora que eu, eu o sou, e mais nenhum deus há além de mim; eu mato, e eu faço viver; eu firo, e eu saro, e ninguém há que escape da minha mão.'),
('acf','dt',32,40,'Porque levantarei a minha mão aos céus, e direi: Eu vivo para sempre.'),
('acf','dt',32,41,'Se eu afiar a minha espada reluzente, e se a minha mão travar o juízo, retribuirei a vingança sobre os meus adversários, e recompensarei aos que me odeiam.'),
('acf','dt',32,42,'Embriagarei as minhas setas de sangue, e a minha espada comerá carne; do sangue dos mortos e dos prisioneiros, desde a cabeça, haverá vinganças do inimigo.'),
('acf','dt',32,43,'Jubilai, ó nações, o seu povo, porque ele vingará o sangue dos seus servos, e sobre os seus adversários retribuirá a vingança, e terá misericórdia da sua terra e do seu povo.'),
('acf','dt',32,44,'E veio Moisés, e falou todas as palavras deste cântico aos ouvidos do povo, ele e Josué, filho de Num.'),
('acf','dt',32,45,'E, acabando Moisés de falar todas estas palavras a todo o Israel,'),
('acf','dt',32,46,'Disse-lhes: Aplicai o vosso coração a todas as palavras que hoje testifico entre vós, para que as recomendeis a vossos filhos, para que tenham cuidado de cumprir todas as palavras desta lei.'),
('acf','dt',32,47,'Porque esta palavra não vos é vã, antes é a vossa vida; e por esta mesma palavra prolongareis os dias na terra a qual, passando o Jordão, ides a possuir.'),
('acf','dt',32,48,'Depois falou o Senhor a Moisés, naquele mesmo dia, dizendo:'),
('acf','dt',32,49,'Sobe ao monte de Abarim, ao monte Nebo, que está na terra de Moabe, defronte de Jericó, e vê a terra de Canaã, que darei aos filhos de Israel por possessão.'),
('acf','dt',32,50,'E morre no monte ao qual subirás; e recolhe-te ao teu povo, como Arão teu irmão morreu no monte Hor, e se recolheu ao seu povo.'),
('acf','dt',32,51,'Porquanto transgredistes contra mim no meio dos filhos de Israel, às águas de Meribá de Cades, no deserto de Zim; pois não me santificastes no meio dos filhos de Israel.'),
('acf','dt',32,52,'Pelo que verás a terra diante de ti, porém não entrarás nela, na terra que darei aos filhos de Israel.'),
('acf','dt',33,1,'Esta, porém, é a bênção com que Moisés, homem de Deus, abençoou os filhos de Israel antes da sua morte.'),
('acf','dt',33,2,'Disse pois: O Senhor veio de Sinai, e lhes subiu de Seir; resplandeceu desde o monte Parã, e veio com dez milhares de santos; à sua direita havia para eles o fogo da lei.'),
('acf','dt',33,3,'Na verdade ama os povos; todos os seus santos estão na sua mão; postos serão no meio, entre os teus pés, e cada um receberá das tuas palavras.'),
('acf','dt',33,4,'Moisés nos deu a lei, como herança da congregação de Jacó.'),
('acf','dt',33,5,'E foi rei em Jesurum, quando se congregaram os cabeças do povo com as tribos de Israel.'),
('acf','dt',33,6,'Viva Rúben, e não morra, e que os seus homens não sejam poucos.'),
('acf','dt',33,7,'E isto é o que disse de Judá: Ouve, ó Senhor, a voz de Judá, e introduze-o no seu povo; as suas mãos lhe bastem, e tu lhe sejas em ajuda contra os seus inimigos.'),
('acf','dt',33,8,'E de Levi disse: Teu Tumim e teu Urim são para o teu amado, que tu provaste em Massá, com quem contendeste junto às águas de Meribá.'),
('acf','dt',33,9,'Aquele que disse a seu pai, e à sua mãe: Nunca os vi; e não conheceu a seus irmãos, e não estimou a seus filhos; pois guardaram a tua palavra e observaram a tua aliança.'),
('acf','dt',33,10,'Ensinaram os teus juízos a Jacó, e a tua lei a Israel; puseram incenso no teu nariz, e o holocausto sobre o teu altar.'),
('acf','dt',33,11,'Abençoa o seu poder, ó Senhor, e aceita a obra das suas mãos; fere os lombos dos que se levantam contra ele e o odeiam, para que nunca mais se levantem.'),
('acf','dt',33,12,'E de Benjamim disse: O amado do Senhor habitará seguro com ele; todo o dia o cobrirá, e morará entre os seus ombros.'),
('acf','dt',33,13,'E de José disse: Bendita do Senhor seja a sua terra, com o mais excelente dos céus, com o orvalho e com o abismo que jaz abaixo.'),
('acf','dt',33,14,'E com os mais excelentes frutos do sol, e com as mais excelentes produções das luas,'),
('acf','dt',33,15,'E com o mais excelente dos montes antigos, e com o mais excelente dos outeiros eternos.'),
('acf','dt',33,16,'E com o mais excelente da terra, e da sua plenitude, e com a benevolência daquele que habitava na sarça, venha sobre a cabeça de José, e sobre o alto da cabeça daquele que foi separado de seus irmãos.'),
('acf','dt',33,17,'Ele tem a glória do primogênito do seu touro, e os seus chifres são chifres de boi selvagem; com eles rechaçará todos os povos até às extremidades da terra; estes pois são os dez milhares de Efraim, e estes são os milhares de Manassés.'),
('acf','dt',33,18,'E de Zebulom disse: Zebulom, alegra-te nas tuas saídas; e tu, Issacar, nas tuas tendas.'),
('acf','dt',33,19,'Eles chamarão os povos ao monte; ali apresentarão ofertas de justiça, porque chuparão a abundância dos mares e os tesouros escondidos da areia.'),
('acf','dt',33,20,'E de Gade disse: Bendito aquele que faz dilatar a Gade; habita como a leoa, e despedaça o braço e o alto da cabeça.'),
('acf','dt',33,21,'E se proveu da melhor parte, porquanto ali estava escondida a porção do legislador; por isso veio com os chefes do povo, executou a justiça do Senhor e os seus juízos para com Israel.'),
('acf','dt',33,22,'E de Dã disse: Dã é cria de leão; que salta de Basã.'),
('acf','dt',33,23,'E de Naftali disse: Farta-te, ó Naftali, da benevolência, e enche-te da bênção do Senhor; possui o ocidente e o sul.'),
('acf','dt',33,24,'E de Aser disse: Bendito seja Aser com seus filhos; agrade a seus irmãos, e banhe em azeite o seu pé.'),
('acf','dt',33,25,'Seja de ferro e de metal o teu calçado; e a tua força seja como os teus dias.'),
('acf','dt',33,26,'Não há outro, ó Jesurum, semelhante a Deus, que cavalga sobre os céus para a tua ajuda, e com a sua majestade sobre as mais altas nuvens.'),
('acf','dt',33,27,'O Deus eterno é a tua habitação, e por baixo estão os braços eternos; e ele lançará o inimigo de diante de ti, e dirá: Destrói-o.'),
('acf','dt',33,28,'Israel, pois, habitará só, seguro, na terra da fonte de Jacó, na terra de grão e de mosto; e os seus céus gotejarão orvalho.'),
('acf','dt',33,29,'Bem-aventurado tu, ó Israel! Quem é como tu? Um povo salvo pelo Senhor, o escudo do teu socorro, e a espada da tua majestade; por isso os teus inimigos te serão sujeitos, e tu pisarás sobre as suas alturas.'),
('acf','dt',34,1,'Então subiu Moisés das campinas de Moabe ao monte Nebo, ao cume de Pisga, que está em frente a Jericó e o SENHOR mostrou-lhe toda a terra desde Gileade até Dã;'),
('acf','dt',34,2,'E todo Naftali, e a terra de Efraim, e Manassés e toda a terra de Judá, até ao mar ocidental;'),
('acf','dt',34,3,'E o sul, e a campina do vale de Jericó, a cidade das palmeiras, até Zoar.'),
('acf','dt',34,4,'E disse-lhe o Senhor: Esta é a terra que jurei a Abraão, Isaque, e Jacó, dizendo: À tua descendência a darei; eu te faço vê-la com os teus olhos, porém lá não passarás.'),
('acf','dt',34,5,'Assim morreu ali Moisés, servo do Senhor, na terra de Moabe, conforme a palavra do Senhor.'),
('acf','dt',34,6,'E o sepultou num vale, na terra de Moabe, em frente de Bete-Peor; e ninguém soube até hoje o lugar da sua sepultura.'),
('acf','dt',34,7,'Era Moisés da idade de cento e vinte anos quando morreu; os seus olhos nunca se escureceram, nem perdeu o seu vigor.'),
('acf','dt',34,8,'E os filhos de Israel prantearam a Moisés trinta dias, nas campinas de Moabe; e os dias do pranto no luto de Moisés se cumpriram.'),
('acf','dt',34,9,'E Josué, filho de Num, foi cheio do espírito de sabedoria, porquanto Moisés tinha posto sobre ele as suas mãos; assim os filhos de Israel lhe deram ouvidos, e fizeram como o Senhor ordenara a Moisés.'),
('acf','dt',34,10,'E nunca mais se levantou em Israel profeta algum como Moisés, a quem o Senhor conhecera face a face;'),
('acf','dt',34,11,'Nem semelhante em todos os sinais e maravilhas, que o Senhor o enviou para fazer na terra do Egito, a Faraó, e a todos os seus servos, e a toda a sua terra.'),
('acf','dt',34,12,'E em toda a mão forte, e em todo o grande espanto, que praticou Moisés aos olhos de todo o Israel.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','js',1,1,'E sucedeu depois da morte de Moisés, servo do SENHOR, que o SENHOR falou a Josué, filho de Num, servo de Moisés, dizendo:'),
('acf','js',1,2,'Moisés, meu servo, é morto; levanta-te, pois, agora, passa este Jordão, tu e todo este povo, à terra que eu dou aos filhos de Israel.'),
('acf','js',1,3,'Todo o lugar que pisar a planta do vosso pé, vo-lo tenho dado, como eu disse a Moisés.'),
('acf','js',1,4,'Desde o deserto e do Líbano, até ao grande rio, o rio Eufrates, toda a terra dos heteus, e até o grande mar para o poente do sol, será o vosso termo.'),
('acf','js',1,5,'Ninguém te poderá resistir, todos os dias da tua vida; como fui com Moisés, assim serei contigo; não te deixarei nem te desampararei.'),
('acf','js',1,6,'Esforça-te, e tem bom ânimo; porque tu farás a este povo herdar a terra que jurei a seus pais lhes daria.'),
('acf','js',1,7,'Tão-somente esforça-te e tem mui bom ânimo, para teres o cuidado de fazer conforme a toda a lei que meu servo Moisés te ordenou; dela não te desvies, nem para a direita nem para a esquerda, para que prudentemente te conduzas por onde quer que andares.'),
('acf','js',1,8,'Não se aparte da tua boca o livro desta lei; antes medita nele dia e noite, para que tenhas cuidado de fazer conforme a tudo quanto nele está escrito; porque então farás prosperar o teu caminho, e serás bem sucedido.'),
('acf','js',1,9,'Não to mandei eu? Esforça-te, e tem bom ânimo; não temas, nem te espantes; porque o Senhor teu Deus é contigo, por onde quer que andares.'),
('acf','js',1,10,'Então Josué deu ordem aos príncipes do povo, dizendo:'),
('acf','js',1,11,'Passai pelo meio do arraial e ordenai ao povo, dizendo: Provede-vos de comida, porque dentro de três dias passareis este Jordão, para que entreis a possuir a terra que vos dá o Senhor vosso Deus, para a possuirdes.'),
('acf','js',1,12,'E falou Josué aos rubenitas, e aos gaditas, e à meia tribo de Manassés, dizendo:'),
('acf','js',1,13,'Lembrai-vos da palavra que vos mandou Moisés, o servo do Senhor, dizendo: O Senhor vosso Deus vos dá descanso, e vos dá esta terra.'),
('acf','js',1,14,'Vossas mulheres, vossos meninos e vosso gado fiquem na terra que Moisés vos deu deste lado do Jordão; porém vós passareis armados na frente de vossos irmãos, todos os valentes e valorosos, e ajudá-los-eis.'),
('acf','js',1,15,'Até que o Senhor dê descanso a vossos irmãos, como a vós, e eles também possuam a terra que o Senhor vosso Deus lhes dá; então tornareis à terra da vossa herança, e possuireis a que vos deu Moisés, o servo do Senhor, deste lado do Jordão, para o nascente do sol.'),
('acf','js',1,16,'Então responderam a Josué, dizendo: Tudo quanto nos ordenaste faremos, e onde quer que nos enviares iremos.'),
('acf','js',1,17,'Como em tudo ouvimos a Moisés, assim te ouviremos a ti, tão-somente que o Senhor teu Deus seja contigo, como foi com Moisés.'),
('acf','js',1,18,'Todo o homem, que for rebelde às tuas ordens, e não ouvir as tuas palavras em tudo quanto lhe mandares, morrerá. Tão-somente esforça-te, e tem bom ânimo.'),
('acf','js',2,1,'E Josué, filho de Num, enviou secretamente, de Sitim, dois homens a espiar, dizendo: Ide reconhecer a terra e a Jericó. Foram, pois, e entraram na casa de uma mulher prostituta, cujo nome era Raabe, e dormiram ali.'),
('acf','js',2,2,'Então deu-se notícia ao rei de Jericó, dizendo: Eis que esta noite vieram aqui uns homens dos filhos de Israel, para espiar a terra.'),
('acf','js',2,3,'Por isso mandou o rei de Jericó dizer a Raabe: Tira fora os homens que vieram a ti e entraram na tua casa, porque vieram espiar toda a terra.'),
('acf','js',2,4,'Porém aquela mulher tomou os dois homens, e os escondeu, e disse: É verdade que vieram homens a mim, porém eu não sabia de onde eram.'),
('acf','js',2,5,'E aconteceu que, havendo-se de fechar a porta, sendo já escuro, aqueles homens saíram; não sei para onde aqueles homens se foram; ide após eles depressa, porque os alcançareis.'),
('acf','js',2,6,'Porém ela os tinha feito subir ao eirado, e os tinha escondido entre as canas do linho, que pusera em ordem sobre o eirado.'),
('acf','js',2,7,'E foram-se aqueles homens após eles pelo caminho do Jordão, até aos vaus; e, havendo eles saído, fechou-se a porta.'),
('acf','js',2,8,'E, antes que eles dormissem, ela subiu a eles no eirado;'),
('acf','js',2,9,'E disse aos homens: Bem sei que o Senhor vos deu esta terra e que o pavor de vós caiu sobre nós, e que todos os moradores da terra estão desfalecidos diante de vós.'),
('acf','js',2,10,'Porque temos ouvido que o Senhor secou as águas do Mar Vermelho diante de vós, quando saíeis do Egito, e o que fizestes aos dois reis dos amorreus, a Siom e a Ogue, que estavam além do Jordão, os quais destruístes.'),
('acf','js',2,11,'O que ouvindo, desfaleceu o nosso coração, e em ninguém mais há ânimo algum, por causa da vossa presença; porque o Senhor vosso Deus é Deus em cima nos céus e em baixo na terra.'),
('acf','js',2,12,'Agora, pois, jurai-me, vos peço, pelo Senhor, que, como usei de misericórdia convosco, vós também usareis de misericórdia para com a casa de meu pai, e dai-me um sinal seguro,'),
('acf','js',2,13,'De que conservareis com a vida a meu pai e a minha mãe, como também a meus irmãos e a minhas irmãs, com tudo o que têm e de que livrareis as nossas vidas da morte.'),
('acf','js',2,14,'Então aqueles homens responderam-lhe: A nossa vida responderá pela vossa até à morte, se não denunciardes este nosso negócio, e será, pois, que, dando-nos o Senhor esta terra, usaremos contigo de misericórdia e de fidelidade.'),
('acf','js',2,15,'Ela então os fez descer por uma corda pela janela, porquanto a sua casa estava sobre o muro da cidade, e ela morava sobre o muro.'),
('acf','js',2,16,'E disse-lhes: Ide-vos ao monte, para que, porventura, não vos encontrem os perseguidores, e escondei-vos lá três dias, até que voltem os perseguidores, e depois ide pelo vosso caminho.'),
('acf','js',2,17,'E, disseram-lhe aqueles homens: Desobrigados seremos deste juramento que nos fizeste jurar.'),
('acf','js',2,18,'Eis que, quando nós entrarmos na terra, atarás este cordão de fio de escarlata à janela por onde nos fizeste descer; e recolherás em casa contigo a teu pai, e a tua mãe, e a teus irmãos e a toda a família de teu pai.'),
('acf','js',2,19,'Será, pois, que qualquer que sair fora da porta da tua casa o seu sangue será sobre a sua cabeça, e nós seremos inocentes; mas qualquer que estiver contigo, em casa, o seu sangue seja sobre a nossa cabeça, se alguém nele puser mão.'),
('acf','js',2,20,'Porém, se tu denunciares este nosso negócio, seremos desobrigados do juramento que nos fizeste jurar.'),
('acf','js',2,21,'E ela disse: Conforme as vossas palavras, assim seja. Então os despediu; e eles se foram; e ela atou o cordão de escarlata à janela.'),
('acf','js',2,22,'Foram-se, pois, e chegaram ao monte, e ficaram ali três dias, até que voltaram os perseguidores, porque os perseguidores os buscaram por todo o caminho, porém não os acharam.'),
('acf','js',2,23,'Assim aqueles dois homens voltaram, e desceram do monte, e passaram, e chegaram a Josué, filho de Num, e contaram-lhe tudo quanto lhes acontecera;'),
('acf','js',2,24,'E disseram a Josué: Certamente o Senhor tem dado toda esta terra nas nossas mãos, pois até todos os moradores estão atemorizados diante de nós.'),
('acf','js',3,1,'Levantou-se, pois, Josué de madrugada, e partiram de Sitim, ele e todos os filhos de Israel; e vieram até ao Jordão, e pousaram ali, antes que passassem.'),
('acf','js',3,2,'E sucedeu, ao fim de três dias, que os oficiais passaram pelo meio do arraial;'),
('acf','js',3,3,'E ordenaram ao povo, dizendo: Quando virdes a arca da aliança do Senhor vosso Deus, e que os sacerdotes levitas a levam, partireis vós também do vosso lugar, e a seguireis.'),
('acf','js',3,4,'Haja contudo, entre vós e ela, uma distância de dois mil côvados; e não vos chegueis a ela, para que saibais o caminho pelo qual haveis de ir; porquanto por este caminho nunca passastes antes.'),
('acf','js',3,5,'Disse Josué também ao povo: Santificai-vos, porque amanhã fará o Senhor maravilhas no meio de vós.'),
('acf','js',3,6,'E falou Josué aos sacerdotes, dizendo: Levantai a arca da aliança, e passai adiante deste povo. Levantaram, pois, a arca da aliança, e foram andando adiante do povo.'),
('acf','js',3,7,'E o Senhor disse a Josué: Hoje começarei a engrandecer-te perante os olhos de todo o Israel, para que saibam que, assim como fui com Moisés, assim serei contigo.'),
('acf','js',3,8,'Tu, pois, ordenarás aos sacerdotes que levam a arca da aliança, dizendo: Quando chegardes à beira das águas do Jordão, parareis aí.'),
('acf','js',3,9,'Então disse Josué aos filhos de Israel: Chegai-vos para cá, e ouvi as palavras do Senhor vosso Deus.'),
('acf','js',3,10,'Disse mais Josué: Nisto conhecereis que o Deus vivo está no meio de vós; e que certamente lançará de diante de vós aos cananeus, e aos heteus, e aos heveus, e aos perizeus, e aos girgaseus, e aos amorreus, e aos jebuseus.'),
('acf','js',3,11,'Eis que a arca da aliança do Senhor de toda a terra passa o Jordão diante de vós.'),
('acf','js',3,12,'Tomai, pois, agora doze homens das tribos de Israel, de cada tribo um homem;'),
('acf','js',3,13,'Porque há de acontecer que, assim que as plantas dos pés dos sacerdotes, que levam a arca do Senhor, o Senhor de toda a terra, repousem nas águas do Jordão, se separarão as águas do Jordão, e as águas, que vêm de cima, pararão amontoadas.'),
('acf','js',3,14,'E aconteceu que, partindo o povo das suas tendas, para passar o Jordão, levavam os sacerdotes a arca da aliança adiante do povo.'),
('acf','js',3,15,'E quando os que levavam a arca, chegaram ao Jordão, e os seus pés se molharam na beira das águas (porque o Jordão transbordava sobre todas as suas ribanceiras, todos os dias da ceifa),'),
('acf','js',3,16,'Pararam-se as águas, que vinham de cima; levantaram-se num montão, mui longe da cidade de Adão, que está ao lado de Zaretã; e as que desciam ao mar das campinas, que é o Mar Salgado, foram de todo separadas; então passou o povo em frente de Jericó.'),
('acf','js',3,17,'Porém os sacerdotes, que levavam a arca da aliança do Senhor, pararam firmes, em seco, no meio do Jordão, e todo o Israel passou a seco, até que todo o povo acabou de passar o Jordão.'),
('acf','js',4,1,'Sucedeu que, acabando todo o povo de passar o Jordão, falou o SENHOR a Josué, dizendo:'),
('acf','js',4,2,'Tomai do povo doze homens, de cada tribo um homem;'),
('acf','js',4,3,'E mandai-lhes, dizendo: Tirai daqui, do meio do Jordão, do lugar onde estavam firmes os pés dos sacerdotes, doze pedras; e levai-as convosco à outra margem e depositai-as no alojamento em que haveis de passar esta noite.'),
('acf','js',4,4,'Chamou, pois, Josué os doze homens, que escolhera dos filhos de Israel; de cada tribo um homem;'),
('acf','js',4,5,'E disse-lhes Josué: Passai adiante da arca do Senhor vosso Deus, ao meio do Jordão; e cada um levante uma pedra sobre o ombro, segundo o número das tribos dos filhos de Israel;'),
('acf','js',4,6,'Para que isto seja por sinal entre vós; e quando vossos filhos no futuro perguntarem, dizendo: Que significam estas pedras?'),
('acf','js',4,7,'Então lhes direis que as águas do Jordão se separaram diante da arca da aliança do Senhor; passando ela pelo Jordão, separaram-se as águas do Jordão; assim estas pedras serão para sempre por memorial aos filhos de Israel.'),
('acf','js',4,8,'Fizeram, pois, os filhos de Israel assim como Josué tinha ordenado, e levantaram doze pedras do meio do Jordão como o Senhor dissera a Josué, segundo o número das tribos dos filhos de Israel; e levaram-nas consigo ao alojamento, e as depositaram ali.'),
('acf','js',4,9,'Levantou Josué também doze pedras no meio do Jordão, no lugar onde estiveram parados os pés dos sacerdotes, que levavam a arca da aliança; e ali estão até ao dia de hoje.'),
('acf','js',4,10,'Pararam, pois, os sacerdotes, que levavam a arca, no meio do Jordão, em pé, até que se cumpriu tudo quanto o Senhor mandara Josué dizer ao povo, conforme a tudo quanto Moisés tinha ordenado a Josué; e apressou-se o povo, e passou.'),
('acf','js',4,11,'E sucedeu que, assim que todo o povo acabou de passar, então passou a arca do Senhor, e os sacerdotes, à vista do povo.'),
('acf','js',4,12,'E passaram os filhos de Rúben, e os filhos de Gade, e a meia tribo de Manassés, armados na frente dos filhos de Israel, como Moisés lhes tinha falado;'),
('acf','js',4,13,'Uns quarenta mil homens de guerra, armados, passaram diante do Senhor para batalha, às campinas de Jericó.'),
('acf','js',4,14,'Naquele dia o Senhor engrandeceu a Josué diante dos olhos de todo o Israel; e temeram-no, como haviam temido a Moisés, todos os dias da sua vida.'),
('acf','js',4,15,'Falou, pois, o Senhor a Josué, dizendo:'),
('acf','js',4,16,'Dá ordem aos sacerdotes, que levam a arca do testemunho, que subam do Jordão.'),
('acf','js',4,17,'E deu Josué ordem aos sacerdotes, dizendo: Subi do Jordão.'),
('acf','js',4,18,'E aconteceu que, como os sacerdotes, que levavam a arca da aliança do Senhor, subiram do meio do Jordão, e as plantas dos pés dos sacerdotes se puseram em seco, as águas do Jordão se tornaram ao seu lugar, e corriam, como antes, sobre todas as suas ribanceiras.'),
('acf','js',4,19,'Subiu, pois, o povo, do Jordão no dia dez do mês primeiro; e alojaram-se em Gilgal, do lado oriental de Jericó.'),
('acf','js',4,20,'E as doze pedras, que tinham tomado do Jordão, levantou-as Josué em Gilgal.'),
('acf','js',4,21,'E falou aos filhos de Israel, dizendo: Quando no futuro vossos filhos perguntarem a seus pais, dizendo: Que significam estas pedras?'),
('acf','js',4,22,'Fareis saber a vossos filhos, dizendo: Israel passou em seco este Jordão.'),
('acf','js',4,23,'Porque o Senhor vosso Deus fez secar as águas do Jordão diante de vós, até que passásseis, como o Senhor vosso Deus fez ao Mar Vermelho que fez secar perante nós, até que passássemos.'),
('acf','js',4,24,'Para que todos os povos da terra conheçam a mão do Senhor, que é forte, para que temais ao Senhor vosso Deus todos os dias.'),
('acf','js',5,1,'E sucedeu que, ouvindo todos os reis dos amorreus, que habitavam deste lado do Jordão, ao ocidente, e todos os reis dos cananeus, que estavam ao pé do mar, que o SENHOR tinha secado as águas do Jordão, de diante dos filhos de Israel, até que passassem, desfaleceu-se-lhes o coração, e não houve mais ânimo neles, por causa dos filhos de Israel.'),
('acf','js',5,2,'Naquele tempo disse o Senhor a Josué: Faze facas de pedra, e torna a circuncidar segunda vez aos filhos de Israel.'),
('acf','js',5,3,'Então Josué fez para si facas de pedra, e circuncidou aos filhos de Israel no monte dos prepúcios.'),
('acf','js',5,4,'E foi esta a causa por que Josué os circuncidou: todo o povo que tinha saído do Egito, os homens, todos os homens de guerra, já haviam morrido no deserto, pelo caminho, depois que saíram do Egito.'),
('acf','js',5,5,'Porque todos os do povo que saíram estavam circuncidados, mas a nenhum dos que nasceram no deserto, pelo caminho, depois de terem saído do Egito, haviam circuncidado.'),
('acf','js',5,6,'Porque quarenta anos andaram os filhos de Israel pelo deserto, até se acabar toda a nação, os homens de guerra, que saíram do Egito, e não obedeceram à voz do Senhor; aos quais o Senhor tinha jurado que lhes não havia de deixar ver a terra que o Senhor jurara a seus pais dar-nos; terra que mana leite e mel.'),
('acf','js',5,7,'Porém em seu lugar pôs a seus filhos; a estes Josué circuncidou, porquanto estavam incircuncisos, porque os não circuncidaram no caminho.'),
('acf','js',5,8,'E aconteceu que, acabando de circuncidar a toda a nação, ficaram no seu lugar no arraial, até que sararam.'),
('acf','js',5,9,'Disse mais o Senhor a Josué: Hoje retirei de sobre vós o opróbrio do Egito; por isso o nome daquele lugar se chamou Gilgal, até ao dia de hoje.'),
('acf','js',5,10,'Estando, pois, os filhos de Israel acampados em Gilgal, celebraram a páscoa no dia catorze do mês, à tarde, nas campinas de Jericó.'),
('acf','js',5,11,'E, ao outro dia depois da páscoa, nesse mesmo dia, comeram, do fruto da terra, pães ázimos e espigas tostadas.'),
('acf','js',5,12,'E cessou o maná no dia seguinte, depois que comeram do fruto da terra, e os filhos de Israel não tiveram mais maná; porém, no mesmo ano comeram dos frutos da terra de Canaã.'),
('acf','js',5,13,'E sucedeu que, estando Josué perto de Jericó, levantou os seus olhos e olhou; e eis que se pôs em pé diante dele um homem que tinha na mão uma espada nua; e chegou-se Josué a ele, e disse-lhe: És tu dos nossos, ou dos nossos inimigos?'),
('acf','js',5,14,'E disse ele: Não, mas venho agora como príncipe do exército do SENHOR. Então Josué se prostrou com o seu rosto em terra e o adorou, e disse-lhe: Que diz meu senhor ao seu servo?'),
('acf','js',5,15,'Então disse o príncipe do exército do Senhor a Josué: Descalça os sapatos de teus pés, porque o lugar em que estás é santo. E fez Josué assim.'),
('acf','js',6,1,'Ora Jericó estava rigorosamente fechada por causa dos filhos de Israel; ninguém saía nem entrava.'),
('acf','js',6,2,'Então disse o Senhor a Josué: Olha, tenho dado na tua mão a Jericó, ao seu rei e aos seus homens valorosos.'),
('acf','js',6,3,'Vós, pois, todos os homens de guerra, rodeareis a cidade, cercando-a uma vez; assim fareis por seis dias.'),
('acf','js',6,4,'E sete sacerdotes levarão sete buzinas de chifres de carneiros adiante da arca, e no sétimo dia rodeareis a cidade sete vezes, e os sacerdotes tocarão as buzinas.'),
('acf','js',6,5,'E será que, tocando-se prolongadamente a buzina de carneiro, ouvindo vós o seu sonido, todo o povo gritará com grande brado; e o muro da cidade cairá abaixo, e o povo subirá por ele, cada um em frente.'),
('acf','js',6,6,'Então Josué, filho de Num, chamou aos sacerdotes e disse-lhes: Levai a arca da aliança; e sete sacerdotes levem sete buzinas de chifres de carneiros, adiante da arca do Senhor.'),
('acf','js',6,7,'E disse ao povo: Passai e rodeai a cidade; e quem estiver armado, passe adiante da arca do Senhor.'),
('acf','js',6,8,'E assim foi que, como Josué dissera ao povo, os sete sacerdotes, levando as sete buzinas de carneiros diante do Senhor, passaram e tocaram as buzinas; e a arca da aliança do Senhor os seguia.'),
('acf','js',6,9,'E os homens armados iam adiante dos sacerdotes, que tocavam as buzinas; e a retaguarda seguia após a arca; andando e tocando as buzinas iam os sacerdotes.'),
('acf','js',6,10,'Porém ao povo Josué tinha dado ordem, dizendo: Não gritareis, nem fareis ouvir a vossa voz, nem sairá palavra alguma da vossa boca até ao dia que eu vos diga: Gritai. Então gritareis.'),
('acf','js',6,11,'E fez a arca do Senhor rodear a cidade, contornando-a uma vez; e entraram no arraial, e ali passaram a noite.'),
('acf','js',6,12,'Depois Josué se levantou de madrugada, e os sacerdotes levaram a arca do Senhor.'),
('acf','js',6,13,'E os sete sacerdotes, que levavam as sete buzinas de chifres de carneiros, adiante da arca do Senhor, iam andando, e tocavam as buzinas, e os homens armados iam adiante deles e a retaguarda seguia atrás da arca do Senhor; os sacerdotes iam andando e tocando as buzinas.'),
('acf','js',6,14,'Assim rodearam outra vez a cidade no segundo dia e voltaram para o arraial; e assim fizeram seis dias.'),
('acf','js',6,15,'E sucedeu que, ao sétimo dia, madrugaram ao subir da alva, e da mesma maneira rodearam a cidade sete vezes; naquele dia somente rodearam a cidade sete vezes.'),
('acf','js',6,16,'E sucedeu que, tocando os sacerdotes pela sétima vez as buzinas, disse Josué ao povo: Gritai, porque o Senhor vos tem dado a cidade.'),
('acf','js',6,17,'Porém a cidade será anátema ao Senhor, ela e tudo quanto houver nela; somente a prostituta Raabe viverá; ela e todos os que com ela estiverem em casa; porquanto escondeu os mensageiros que enviamos.'),
('acf','js',6,18,'Tão-somente guardai-vos do anátema, para que não toqueis nem tomeis alguma coisa dele, e assim façais maldito o arraial de Israel, e o perturbeis.'),
('acf','js',6,19,'Porém toda a prata, e o ouro, e os vasos de metal, e de ferro são consagrados ao Senhor; irão ao tesouro do Senhor.'),
('acf','js',6,20,'Gritou, pois, o povo, tocando os sacerdotes as buzinas; e sucedeu que, ouvindo o povo o sonido da buzina, gritou o povo com grande brado; e o muro caiu abaixo, e o povo subiu à cidade, cada um em frente de si, e tomaram a cidade.'),
('acf','js',6,21,'E tudo quanto havia na cidade destruíram totalmente ao fio da espada, desde o homem até à mulher, desde o menino até ao velho, e até ao boi e gado miúdo, e ao jumento.'),
('acf','js',6,22,'Josué, porém, disse aos dois homens que tinham espiado a terra: Entrai na casa da mulher prostituta, e tirai-a de lá com tudo quanto tiver, como lhe tendes jurado.'),
('acf','js',6,23,'Então entraram os jovens espias, e tiraram a Raabe e a seu pai, e a sua mãe, e a seus irmãos, e a tudo quanto tinha; tiraram também a toda a sua parentela, e os puseram fora do arraial de Israel.'),
('acf','js',6,24,'Porém a cidade e tudo quanto havia nela queimaram a fogo; tão-somente a prata, e o ouro, e os vasos de metal e de ferro, deram para o tesouro da casa do Senhor.'),
('acf','js',6,25,'Assim deu Josué vida à prostituta Raabe e à família de seu pai, e a tudo quanto tinha; e habitou no meio de Israel até ao dia de hoje; porquanto escondera os mensageiros que Josué tinha enviado a espiar a Jericó.'),
('acf','js',6,26,'E naquele tempo Josué os esconjurou, dizendo: Maldito diante do Senhor seja o homem que se levantar e reedificar esta cidade de Jericó; sobre seu primogênito a fundará, e sobre o seu filho mais novo lhe porá as portas.'),
('acf','js',6,27,'Assim era o Senhor com Josué; e corria a sua fama por toda a terra.'),
('acf','js',7,1,'E transgrediram os filhos de Israel no anátema; porque Acã filho de Carmi, filho de Zabdi, filho de Zerá, da tribo de Judá, tomou do anátema, e a ira do SENHOR se acendeu contra os filhos de Israel.'),
('acf','js',7,2,'Enviando, pois, Josué, de Jericó, alguns homens a Ai, que está junto a Bete-Áven do lado do oriente de Betel, falou-lhes dizendo: Subi, e espiai a terra. Subiram, pois, aqueles homens, e espiaram a Ai.'),
('acf','js',7,3,'E voltaram a Josué, e disseram-lhe: Não suba todo o povo; subam uns dois mil, ou três mil homens, a ferir a Ai; não fatigueis ali a todo o povo, porque poucos são.'),
('acf','js',7,4,'Assim, subiram lá, do povo, uns três mil homens, os quais fugiram diante dos homens de Ai.'),
('acf','js',7,5,'E os homens de Ai feriram deles uns trinta e seis, e os perseguiram desde a porta até Sebarim, e os feriram na descida; e o coração do povo se derreteu e se tornou como água.'),
('acf','js',7,6,'Então Josué rasgou as suas vestes, e se prostrou em terra sobre o seu rosto perante a arca do Senhor até à tarde, ele e os anciãos de Israel; e deitaram pó sobre as suas cabeças.'),
('acf','js',7,7,'E disse Josué: Ah! Senhor Deus! Por que, com efeito, fizeste passar a este povo o Jordão, para nos entregares nas mãos dos amorreus para nos fazerem perecer? Antes nos tivéssemos contentado em ficar além do Jordão!'),
('acf','js',7,8,'Ah, Senhor! Que direi? Pois Israel virou as costas diante dos inimigos!'),
('acf','js',7,9,'Ouvindo isto, os cananeus, e todos os moradores da terra, nos cercarão e desarraigarão o nosso nome da terra; e então que farás ao teu grande nome?'),
('acf','js',7,10,'Então disse o Senhor a Josué: Levanta-te; por que estás prostrado assim sobre o teu rosto?'),
('acf','js',7,11,'Israel pecou, e transgrediram a minha aliança que lhes tinha ordenado, e tomaram do anátema, e furtaram, e mentiram, e debaixo da sua bagagem o puseram.'),
('acf','js',7,12,'Por isso os filhos de Israel não puderam subsistir perante os seus inimigos; viraram as costas diante dos seus inimigos; porquanto estão amaldiçoados; não serei mais convosco, se não desarraigardes o anátema do meio de vós.'),
('acf','js',7,13,'Levanta-te, santifica o povo, e dize: Santificai-vos para amanhã, porque assim diz o Senhor Deus de Israel: Anátema há no meio de ti, Israel; diante dos teus inimigos não poderás suster-te, até que tireis o anátema do meio de vós.'),
('acf','js',7,14,'Amanhã, pois, vos chegareis, segundo as vossas tribos; e será que a tribo que o Senhor tomar se chegará, segundo as famílias; e a família que o Senhor tomar se chegará por casas; e a casa que o Senhor tomar se chegará homem por homem.'),
('acf','js',7,15,'E será que aquele que for tomado com o anátema será queimado a fogo, ele e tudo quanto tiver; porquanto transgrediu a aliança do Senhor, e fez uma loucura em Israel.'),
('acf','js',7,16,'Então Josué se levantou de madrugada, e fez chegar a Israel, segundo as suas tribos; e a tribo de Judá foi tomada;'),
('acf','js',7,17,'E, fazendo chegar a tribo de Judá, tomou a família dos zeraítas; e fazendo chegar a família dos zeraítas homem por homem, foi tomado Zabdi;'),
('acf','js',7,18,'E, fazendo chegar a sua casa, homem por homem, foi tomado Acã, filho de Carmi, filho de Zabdi, filho de Zerá, da tribo de Judá.'),
('acf','js',7,19,'Então disse Josué a Acã: Filho meu, dá, peço-te, glória ao Senhor Deus de Israel, e faze confissão perante ele; e declara-me agora o que fizeste, não mo ocultes.'),
('acf','js',7,20,'E respondeu Acã a Josué, e disse: Verdadeiramente pequei contra o Senhor Deus de Israel, e fiz assim e assim.'),
('acf','js',7,21,'Quando vi entre os despojos uma boa capa babilônica, e duzentos siclos de prata, e uma cunha de ouro, do peso de cinqüenta siclos, cobicei-os e tomei-os; e eis que estão escondidos na terra, no meio da minha tenda, e a prata por baixo dela.'),
('acf','js',7,22,'Então Josué enviou mensageiros, que foram correndo à tenda; e eis que tudo estava escondido na sua tenda, e a prata por baixo.'),
('acf','js',7,23,'Tomaram, pois, aquelas coisas do meio da tenda, e as trouxeram a Josué e a todos os filhos de Israel; e as puseram perante o Senhor.'),
('acf','js',7,24,'Então Josué, e todo o Israel com ele, tomaram a Acã filho de Zerá, e a prata, e a capa, e a cunha de ouro, e seus filhos, e suas filhas, e seus bois, e seus jumentos, e suas ovelhas, e sua tenda, e tudo quanto ele tinha; e levaram-nos ao vale de Acor.'),
('acf','js',7,25,'E disse Josué: Por que nos perturbaste? O Senhor te perturbará neste dia. E todo o Israel o apedrejou; e os queimaram a fogo depois de apedrejá-los.'),
('acf','js',7,26,'E levantaram sobre ele um grande montão de pedras, até o dia de hoje; assim o Senhor se apartou do ardor da sua ira; pelo que aquele lugar se chama o vale de Acor, até ao dia de hoje.'),
('acf','js',8,1,'Então disse o SENHOR a Josué: Não temas, e não te espantes; toma contigo toda a gente de guerra, e levanta-te, sobe a Ai; olha que te tenho dado na tua mão o rei de Ai e o seu povo, e a sua cidade, e a sua terra.'),
('acf','js',8,2,'Farás, pois, a Ai e a seu rei, como fizeste a Jericó, e a seu rei; salvo que, para vós, tomareis os seus despojos, e o seu gado; põe emboscadas à cidade, por detrás dela.'),
('acf','js',8,3,'Então Josué levantou-se, e toda a gente de guerra, para subir contra Ai; e escolheu Josué trinta mil homens valorosos, e enviou-os de noite.'),
('acf','js',8,4,'E deu-lhes ordem, dizendo: Olhai! Ponde-vos de emboscadas contra a cidade, por detrás dela; não vos alongueis muito da cidade; e estai todos vós atentos.'),
('acf','js',8,5,'Porém eu e todo o povo que está comigo nos aproximaremos da cidade; e será que, quando nos saírem ao encontro, como antes, fugiremos diante deles.'),
('acf','js',8,6,'Deixai-os, pois, sair atrás de nós, até que os tiremos da cidade; porque dirão: Fogem diante de nós como antes. Assim fugiremos diante deles.'),
('acf','js',8,7,'Então saireis vós da emboscada, e tomareis a cidade; porque o Senhor vosso Deus vo-la dará nas vossas mãos.'),
('acf','js',8,8,'E será que tomando vós a cidade, pôr-lhe-eis fogo; conforme a palavra do Senhor fareis; olhai que vo-lo tenho mandado.'),
('acf','js',8,9,'Assim Josué os enviou, e eles se foram à emboscada; e ficaram entre Betel e Ai, ao ocidente de Ai; porém Josué passou aquela noite no meio do povo.'),
('acf','js',8,10,'E levantou-se Josué de madrugada, e contou o povo; e subiram ele e os anciãos de Israel adiante do povo contra Ai.'),
('acf','js',8,11,'E subiram também todos os homens de guerra, que estavam com ele; e aproximaram-se, e chegaram defronte da cidade; e alojaram-se do lado norte de Ai, e havia um vale entre eles e Ai.'),
('acf','js',8,12,'Tomou também uns cinco mil homens, e pô-los de emboscada entre Betel e Ai, ao ocidente da cidade.'),
('acf','js',8,13,'E puseram o povo, todo o arraial que estava ao norte da cidade, e a emboscada ao ocidente da cidade; e foi Josué aquela noite até ao meio do vale.'),
('acf','js',8,14,'E sucedeu que, vendo-o o rei de Ai, ele e todo o seu povo se apressaram, e se levantaram de madrugada, e os homens da cidade saíram ao encontro de Israel ao combate, ao tempo determinado, defronte das campinas; porém ele não sabia que se achava uma emboscada contra ele atrás da cidade.'),
('acf','js',8,15,'Josué, pois, e todo o Israel se houveram como feridos diante deles, e fugiram pelo caminho do deserto.'),
('acf','js',8,16,'Por isso todo o povo, que estava na cidade, foi convocado para os seguir; e seguiram a Josué e foram afastados da cidade.'),
('acf','js',8,17,'E nem um só homem ficou em Ai, nem em Betel, que não saísse após Israel; e deixaram a cidade aberta, e seguiram a Israel.'),
('acf','js',8,18,'Então o Senhor disse a Josué: Estende a lança que tens na tua mão, para Ai, porque a darei na tua mão. E Josué estendeu a lança, que estava na sua mão, para a cidade.'),
('acf','js',8,19,'Então a emboscada se levantou apressadamente do seu lugar, e, estendendo ele a sua mão, correram e entraram na cidade, e a tomaram; e apressando-se, puseram fogo na cidade.'),
('acf','js',8,20,'E virando-se os homens de Ai para trás, olharam, e eis que a fumaça da cidade subia ao céu, e não puderam fugir nem para uma parte nem para outra, porque o povo, que fugia para o deserto, se tornou contra os que os seguiam.'),
('acf','js',8,21,'E vendo Josué e todo o Israel que a emboscada tomara a cidade, e que a fumaça da cidade subia, voltaram, e feriram os homens de Ai.'),
('acf','js',8,22,'Também aqueles da cidade lhes saíram ao encontro, e assim ficaram no meio dos israelitas, uns de uma, e outros de outra parte; e feriram-nos, até que nenhum deles sobreviveu nem escapou.'),
('acf','js',8,23,'Porém ao rei de Ai tomaram vivo, e o trouxeram a Josué.'),
('acf','js',8,24,'E sucedeu que, acabando os israelitas de matar todos os moradores de Ai no campo, no deserto, onde os tinham seguido, e havendo todos caído ao fio da espada, até serem consumidos, todo o Israel se tornou a Ai e a feriu ao fio de espada.'),
('acf','js',8,25,'E todos os que caíram aquele dia, assim homens como mulheres, foram doze mil, todos moradores de Ai.'),
('acf','js',8,26,'Porque Josué não retirou a sua mão, que estendera com a lança, até destruir totalmente a todos os moradores de Ai.'),
('acf','js',8,27,'Tão-somente os israelitas tomaram para si o gado e os despojos da cidade, conforme à palavra do Senhor, que tinha ordenado a Josué.'),
('acf','js',8,28,'Queimou, pois, Josué a Ai e a tornou num montão perpétuo, em ruínas, até ao dia de hoje.'),
('acf','js',8,29,'E ao rei de Ai enforcou num madeiro, até à tarde; e ao pôr do sol ordenou Josué que o seu corpo fosse tirado do madeiro; e o lançaram à porta da cidade, e levantaram sobre ele um grande montão de pedras, até o dia de hoje.'),
('acf','js',8,30,'Então Josué edificou um altar ao Senhor Deus de Israel, no monte Ebal.'),
('acf','js',8,31,'Como Moisés, servo do Senhor, ordenara aos filhos de Israel, conforme ao que está escrito no livro da lei de Moisés, a saber: um altar de pedras inteiras, sobre o qual não se moverá instrumento de ferro; e ofereceram sobre ele holocaustos ao Senhor, e sacrificaram ofertas pacíficas.'),
('acf','js',8,32,'Também escreveu ali, em pedras, uma cópia da lei de Moisés, que este havia escrito diante dos filhos de Israel.'),
('acf','js',8,33,'E todo o Israel, com os seus anciãos, e os seus príncipes, e os seus juízes, estavam de um e de outro lado da arca, perante os sacerdotes levitas, que levavam a arca da aliança do Senhor, assim estrangeiros como naturais; metade deles em frente do monte Gerizim, e a outra metade em frente do monte Ebal, como Moisés, servo do Senhor, ordenara, para abençoar primeiramente o povo de Israel.'),
('acf','js',8,34,'E depois leu em alta voz todas as palavras da lei, a bênção e a maldição, conforme a tudo o que está escrito no livro da lei.'),
('acf','js',8,35,'Palavra nenhuma houve, de tudo o que Moisés ordenara, que Josué não lesse perante toda a congregação de Israel, e as mulheres, e os meninos, e os estrangeiros, que andavam no meio deles.'),
('acf','js',9,1,'E sucedeu que, ouvindo isto todos os reis, que estavam aquém do Jordão, nas montanhas, e nas campinas, em toda a costa do grande mar, em frente do Líbano, os heteus, e os amorreus, os cananeus, os perizeus, os heveus, e os jebuseus,'),
('acf','js',9,2,'Se ajuntaram eles de comum acordo, para pelejar contra Josué e contra Israel.'),
('acf','js',9,3,'E os moradores de Gibeom, ouvindo o que Josué fizera com Jericó e com Ai,'),
('acf','js',9,4,'Usaram de astúcia, e foram e se fingiram embaixadores, e levando sacos velhos sobre os seus jumentos, e odres de vinho, velhos, e rotos, e remendados;'),
('acf','js',9,5,'E nos seus pés sapatos velhos e remendados, e roupas velhas sobre si; e todo o pão que traziam para o caminho era seco e bolorento.'),
('acf','js',9,6,'E vieram a Josué, ao arraial, a Gilgal, e disseram a ele e aos homens de Israel: Viemos de uma terra distante; fazei, pois, agora, acordo conosco.'),
('acf','js',9,7,'E os homens de Israel responderam aos heveus: Porventura habiteis no meio de nós; como pois faremos acordo convosco?'),
('acf','js',9,8,'Então disseram a Josué: Nós somos teus servos. E disse-lhes Josué: Quem sois vós, e de onde vindes?'),
('acf','js',9,9,'E lhe responderam: Teus servos vieram de uma terra mui distante, por causa do nome do Senhor teu Deus, porquanto ouvimos a sua fama, e tudo quanto fez no Egito;'),
('acf','js',9,10,'E tudo quanto fez aos dois reis dos amorreus, que estavam além do Jordão, a Siom rei de Hesbom, e a Ogue, rei de Basã, que estava em Astarote.'),
('acf','js',9,11,'Por isso nossos anciãos e todos os moradores da nossa terra nos falaram, dizendo: Tomai em vossas mãos provisão para o caminho, e ide-lhes ao encontro e dizei-lhes: Nós somos vossos servos; fazei, pois, agora acordo conosco.'),
('acf','js',9,12,'Este nosso pão tomamos quente das nossas casas para nossa provisão, no dia em que saímos para vir a vós; e ei-lo aqui agora já seco e bolorento;'),
('acf','js',9,13,'E estes odres, que enchemos de vinho, eram novos, e ei-los aqui já rotos; e estas nossas roupas e nossos sapatos já se têm envelhecido, por causa do mui longo caminho.'),
('acf','js',9,14,'Então os homens de Israel tomaram da provisão deles e não pediram conselho ao Senhor.'),
('acf','js',9,15,'E Josué fez paz com eles, e fez um acordo com eles, que lhes daria a vida; e os príncipes da congregação lhes prestaram juramento.'),
('acf','js',9,16,'E sucedeu que, ao fim de três dias, depois de fazerem acordo com eles, ouviram que eram seus vizinhos, e que moravam no meio deles.'),
('acf','js',9,17,'Porque, partindo os filhos de Israel, chegaram às cidades deles ao terceiro dia; e suas cidades eram Gibeom e Cefira, e Beerote, e Quiriate-Jearim.'),
('acf','js',9,18,'E os filhos de Israel não os feriram; porquanto os príncipes da congregação lhes juraram pelo Senhor Deus de Israel; por isso toda a congregação murmurava contra os príncipes.'),
('acf','js',9,19,'Então todos os príncipes disseram a toda a congregação: Nós juramos-lhes pelo Senhor Deus de Israel, pelo que não lhes podemos tocar.'),
('acf','js',9,20,'Isto, porém, lhes faremos: conservar-lhes-emos a vida, para que não haja grande ira sobre nós, por causa do juramento que já lhes fizemos.'),
('acf','js',9,21,'Disseram-lhes, pois, os príncipes: Vivam, e sejam rachadores de lenha e tiradores de água para toda a congregação, como os príncipes lhes disseram.'),
('acf','js',9,22,'E Josué os chamou, e falou-lhes dizendo: Por que nos enganastes dizendo: Mui longe de vós habitamos, morando vós no meio de nós?'),
('acf','js',9,23,'Agora, pois, sereis malditos; e dentre vós não deixará de haver servos, nem rachadores de lenha, nem tiradores de água, para a casa do meu Deus.'),
('acf','js',9,24,'Então responderam a Josué, e disseram: Porquanto com certeza foi anunciado aos teus servos que o Senhor teu Deus ordenou a Moisés, seu servo, que a vós daria toda esta terra, e destruiria todos os moradores da terra diante de vós, tememos muito por nossas vidas por causa de vós; por isso fizemos assim.'),
('acf','js',9,25,'E eis que agora estamos na tua mão; faze-nos aquilo que te pareça bom e reto.'),
('acf','js',9,26,'Assim pois lhes fez, e livrou-os das mãos dos filhos de Israel, e não os mataram.'),
('acf','js',9,27,'E naquele dia, Josué os fez rachadores de lenha e tiradores de água para a congregação e para o altar do Senhor, até ao dia de hoje, no lugar que ele escolhesse.'),
('acf','js',10,1,'E sucedeu que, ouvindo Adoni-Zedeque, rei de Jerusalém, que Josué tomara a Ai, e a tinha destruído totalmente, e fizera a Ai, e ao seu rei, como tinha feito a Jericó e ao seu rei, e que os moradores de Gibeom fizeram paz com os israelitas, e estavam no meio deles,'),
('acf','js',10,2,'Temeram muito, porque Gibeom era uma cidade grande, como uma das cidades reais, e ainda maior do que Ai, e todos os seus homens valentes.'),
('acf','js',10,3,'Pelo que Adoni-Zedeque, rei de Jerusalém, enviou a Hoão, rei de Hebrom, e a Pirão, rei de Jarmute, e a Jafia, rei de Laquis e a Debir, rei de Eglom, dizendo:'),
('acf','js',10,4,'Subi a mim, e ajudai-me, e firamos a Gibeom, porquanto fez paz com Josué e com os filhos de Israel.'),
('acf','js',10,5,'Então se ajuntaram, e subiram cinco reis dos amorreus, o rei de Jerusalém, o rei de Hebrom, o rei de Jarmute, o rei de Laquis, o rei de Eglom, eles e todos os seus exércitos; e sitiaram a Gibeom e pelejaram contra ela.'),
('acf','js',10,6,'Enviaram, pois, os homens de Gibeom a Josué, ao arraial de Gilgal, dizendo: Não retires as tuas mãos de teus servos; sobe apressadamente a nós, e livra-nos e ajuda-nos, porquanto todos os reis dos amorreus, que habitam na montanha, se ajuntaram contra nós.'),
('acf','js',10,7,'Então subiu Josué, de Gilgal, ele e toda a gente de guerra com ele, e todos os homens valorosos.'),
('acf','js',10,8,'E o Senhor disse a Josué: Não os temas, porque os tenho dado na tua mão; nenhum deles te poderá resistir.'),
('acf','js',10,9,'E Josué lhes sobreveio de repente, porque toda a noite veio subindo desde Gilgal.'),
('acf','js',10,10,'E o Senhor os conturbou diante de Israel, e os feriu com grande matança em Gibeom; e perseguiu-os pelo caminho que sobe a Bete-Horom, e feriu-os até Azeca e a Maquedá.'),
('acf','js',10,11,'E sucedeu que fugindo eles de diante de Israel, à descida de Bete-Horom, o Senhor lançou sobre eles, do céu, grandes pedras, até Azeca, e morreram; e foram muitos mais os que morreram das pedras da saraiva do que os que os filhos de Israel mataram à espada.'),
('acf','js',10,12,'Então Josué falou ao Senhor, no dia em que o Senhor deu os amorreus nas mãos dos filhos de Israel, e disse na presença dos israelitas: Sol, detém-te em Gibeom, e tu, lua, no vale de Ajalom.'),
('acf','js',10,13,'E o sol se deteve, e a lua parou, até que o povo se vingou de seus inimigos. Isto não está escrito no livro de Jasher? O sol, pois, se deteve no meio do céu, e não se apressou a pôr-se, quase um dia inteiro.'),
('acf','js',10,14,'E não houve dia semelhante a este, nem antes nem depois dele, ouvindo o Senhor assim a voz de um homem; porque o Senhor pelejava por Israel.'),
('acf','js',10,15,'E voltou Josué, e todo o Israel com ele, ao arraial, em Gilgal.'),
('acf','js',10,16,'Aqueles cinco reis, porém, fugiram, e se esconderam numa cova em Maquedá.'),
('acf','js',10,17,'E foi anunciado a Josué, dizendo: Acharam-se os cinco reis escondidos numa cova em Maquedá.'),
('acf','js',10,18,'Disse, pois, Josué: Arrastai grandes pedras à boca da cova, e ponde sobre ela homens que os guardem;'),
('acf','js',10,19,'Porém vós não vos detenhais; persegui os vossos inimigos, e atacai os que vão ficando atrás; não os deixeis entrar nas suas cidades, porque o Senhor vosso Deus já vo-los deu na vossa mão.'),
('acf','js',10,20,'E sucedeu que, acabando Josué e os filhos de Israel de os ferir com grande matança, até consumi-los, e os que ficaram deles se retiraram às cidades fortificadas,'),
('acf','js',10,21,'Todo o povo voltou em paz a Josué, ao arraial em Maquedá; não havendo ninguém que movesse a sua língua contra os filhos de Israel.'),
('acf','js',10,22,'Depois disse Josué: Abri a boca da cova, e trazei-me para fora aqueles cinco reis.'),
('acf','js',10,23,'Fizeram, pois, assim, e trouxeram-lhe aqueles cinco reis para fora da cova: o rei de Jerusalém, o rei de Hebrom, o rei de Jarmute, o rei de Laquis e o rei de Eglom.'),
('acf','js',10,24,'E sucedeu que, trazendo aqueles reis a Josué, este chamou todos os homens de Israel, e disse aos capitães dos homens de guerra, que foram com ele: Chegai, ponde os vossos pés sobre os pescoços destes reis. E chegaram, e puseram os seus pés sobre os pescoços deles.'),
('acf','js',10,25,'Então Josué lhes disse: Não temais, nem vos espanteis; esforçai-vos e animai-vos; porque assim o fará o Senhor a todos os vossos inimigos, contra os quais pelejardes.'),
('acf','js',10,26,'E, depois disto, Josué os feriu, e os matou, e os enforcou em cinco madeiros; e ficaram enforcados nos madeiros até à tarde.'),
('acf','js',10,27,'E sucedeu que, ao pôr do sol, deu Josué ordem que os tirassem dos madeiros; e lançaram-nos na cova onde se esconderam; e puseram grandes pedras à boca da cova, que ainda ali estão até o dia de hoje.'),
('acf','js',10,28,'E naquele mesmo dia tomou Josué a Maquedá, e feriu-a a fio de espada, bem como ao seu rei; totalmente a destruiu com todos que nela havia, sem nada deixar; e fez ao rei de Maquedá como fizera ao rei de Jericó.'),
('acf','js',10,29,'Então Josué, e todo o Israel com ele, passou de Maquedá a Libna e pelejou contra ela.'),
('acf','js',10,30,'E também o Senhor a deu na mão de Israel, a ela e a seu rei, e a feriu a fio de espada, a ela e a todos que nela estavam; sem nada deixar; e fez ao seu rei como fizera ao rei de Jericó.'),
('acf','js',10,31,'Então Josué, e todo o Israel com ele, passou de Libna a Laquis; e a sitiou, e pelejou contra ela;'),
('acf','js',10,32,'E o Senhor deu a Laquis nas mãos de Israel, e tomou-a no dia seguinte e a feriu a fio de espada, a ela e a todos os que nela estavam, conforme a tudo o que fizera a Libna.'),
('acf','js',10,33,'Então Horão, rei de Gezer, subiu a ajudar a Laquis, porém Josué o feriu, a ele e ao seu povo, até não lhe deixar nem sequer um.'),
('acf','js',10,34,'E Josué, e todo o Israel com ele, passou de Laquis a Eglom, e a sitiaram, e pelejaram contra ela.'),
('acf','js',10,35,'E no mesmo dia a tomaram, e a feriram a fio de espada; e a todos os que nela estavam, destruiu totalmente no mesmo dia, conforme a tudo o que fizera a Laquis.'),
('acf','js',10,36,'Depois Josué, e todo o Israel com ele, subiu de Eglom a Hebrom, e pelejaram contra ela.'),
('acf','js',10,37,'E a tomaram, e a feriram ao fio de espada, assim ao seu rei como a todas as suas cidades; e a todos os que nelas estavam, a ninguém deixou com vida, conforme a tudo o que fizera a Eglom; e a destruiu totalmente, a ela e a todos os que nela estavam.'),
('acf','js',10,38,'Então Josué, e todo o Israel com ele, tornou a Debir, e pelejou contra ela.'),
('acf','js',10,39,'E tomou-a com o seu rei, e a todas as suas cidades, e as feriu a fio de espada, e a todos os que nelas estavam destruiu totalmente; nada deixou; como fizera a Hebrom, assim fez a Debir e ao seu rei, e como fizera a Libna e ao seu rei.'),
('acf','js',10,40,'Assim feriu Josué toda aquela terra, as montanhas, o sul, e as campinas, e as descidas das águas, e a todos os seus reis; nada deixou; mas tudo o que tinha fôlego destruiu, como ordenara o Senhor Deus de Israel.'),
('acf','js',10,41,'E Josué os feriu desde Cades-Barnéia, até Gaza, como também toda a terra de Gósen, e até Gibeom.'),
('acf','js',10,42,'E de uma vez tomou Josué todos estes reis, e as suas terras; porquanto o Senhor Deus de Israel pelejava por Israel.'),
('acf','js',10,43,'Então Josué, e todo o Israel com ele, voltou ao arraial em Gilgal.'),
('acf','js',11,1,'Sucedeu depois disto que, ouvindo-o Jabim, rei de Hazor, enviou mensageiros a Jobabe, rei de Madom, e ao rei de Sinrom, e ao rei de Acsafe;'),
('acf','js',11,2,'E aos reis, que estavam ao norte, nas montanhas, e na campina para o sul de Quinerete, e nas planícies, e nas elevações de Dor, do lado do mar;'),
('acf','js',11,3,'Ao cananeu do oriente e do ocidente; e ao amorreu, e ao heteu, e ao perizeu, e ao jebuseu nas montanhas; e ao heveu ao pé de Hermom, na terra de Mizpá.'),
('acf','js',11,4,'Saíram pois estes, e todos os seus exércitos com eles, muito povo, em multidão como a areia que está na praia do mar; e muitíssimos cavalos e carros.'),
('acf','js',11,5,'Todos estes reis se ajuntaram, e vieram e se acamparam junto às águas de Merom, para pelejarem contra Israel.'),
('acf','js',11,6,'E disse o Senhor a Josué: Não temas diante deles; porque amanhã, a esta mesma hora, eu os darei todos feridos diante dos filhos de Israel; os seus cavalos jarretarás, e os seus carros queimarás a fogo.'),
('acf','js',11,7,'E Josué, e todos os homens de guerra com ele, veio apressadamente sobre eles às águas de Merom, e atacou-os de repente.'),
('acf','js',11,8,'E o Senhor os deu nas mãos de Israel; e eles os feriram, e os perseguiram até à grande Sidom, e até Misrefote-Maim, e até ao vale de Mizpá ao oriente; feriram até não lhes deixarem nenhum.'),
('acf','js',11,9,'E fez-lhes Josué como o Senhor lhe dissera; os seus cavalos jarretou, e os seus carros queimou a fogo.'),
('acf','js',11,10,'E naquele mesmo tempo voltou Josué, e tomou a Hazor, e feriu à espada ao seu rei; porquanto Hazor antes era a cabeça de todos estes reinos.'),
('acf','js',11,11,'E a todos os que nela estavam, feriram ao fio da espada, e totalmente os destruíram; nada restou do que tinha fôlego, e a Hazor queimou a fogo.'),
('acf','js',11,12,'E Josué tomou todas as cidades destes reis, e todos os seus reis, e os feriu ao fio da espada, destruindo-os totalmente, como ordenara Moisés servo do Senhor.'),
('acf','js',11,13,'Tão-somente não queimaram os israelitas as cidades que estavam sobre os seus outeiros; a não ser Hazor, a qual Josué queimou.'),
('acf','js',11,14,'E todos os despojos destas cidades, e o gado, os filhos de Israel tomaram para si; tão-somente a todos os homens feriram ao fio da espada, até que os destruíram; nada do que tinha fôlego deixaram com vida.'),
('acf','js',11,15,'Como ordenara o Senhor a Moisés, seu servo, assim Moisés ordenou a Josué; e assim Josué o fez; nem uma só palavra tirou de tudo o que o Senhor ordenara a Moisés.'),
('acf','js',11,16,'Assim Josué tomou toda aquela terra, as montanhas, e todo o sul, e toda a terra de Gósen, e as planícies, e as campinas, e as montanhas de Israel, e as suas planícies.'),
('acf','js',11,17,'Desde o monte Halaque, que sobe a Seir, até Baal-Gade, no vale do Líbano, ao pé do monte de Hermom; também tomou todos os seus reis, e os feriu e os matou.'),
('acf','js',11,18,'Por muito tempo Josué fez guerra contra todos estes reis.'),
('acf','js',11,19,'Não houve cidade que fizesse paz com os filhos de Israel, senão os heveus, moradores de Gibeom; por guerra as tomaram todas.'),
('acf','js',11,20,'Porquanto do Senhor vinha o endurecimento de seus corações, para saírem à guerra contra Israel, para que fossem totalmente destruídos e não achassem piedade alguma; mas para os destruir a todos como o Senhor tinha ordenado a Moisés.'),
('acf','js',11,21,'Naquele tempo veio Josué, e extirpou os anaquins das montanhas de Hebrom, de Debir, de Anabe e de todas as montanhas de Judá e de todas as montanhas de Israel; Josué os destruiu totalmente com as suas cidades.'),
('acf','js',11,22,'Nenhum dos anaquins foi deixado na terra dos filhos de Israel; somente ficaram alguns em Gaza, em Gate, e em Asdode.'),
('acf','js',11,23,'Assim Josué tomou toda esta terra, conforme a tudo o que o Senhor tinha dito a Moisés; e Josué a deu em herança aos filhos de Israel, conforme as suas divisões, segundo as suas tribos; e a terra descansou da guerra.'),
('acf','js',12,1,'Estes, pois, são os reis da terra, aos quais os filhos de Israel feriram e cujas terras possuíram além do Jordão para o nascente do sol, desde o ribeiro de Arnom, até ao monte de Hermom, e toda a planície do oriente:'),
('acf','js',12,2,'Siom, rei dos amorreus, que habitava em Hesbom e que dominava desde Aroer, que está à beira do ribeiro de Arnom, e desde o meio do ribeiro, e a metade de Gileade, e até ao ribeiro de Jaboque, o termo dos filhos de Amom.'),
('acf','js',12,3,'E desde a campina até ao mar de Quinerete para o oriente, e até ao mar da campina, o Mar Salgado para o oriente, pelo caminho de Bete-Jesimote; e desde o sul, abaixo de Asdote-Pisga.'),
('acf','js',12,4,'Como também o termo de Ogue, rei de Basã que era do restante dos gigantes e que habitava em Astarote e em Edrei;'),
('acf','js',12,5,'E dominava no monte Hermom, e em Salcá, e em toda a Basã, até ao termo dos gesureus e dos maacateus, e metade de Gileade, termo de Siom, rei de Hesbom.'),
('acf','js',12,6,'A estes Moisés, servo do Senhor, e os filhos de Israel, feriram; e Moisés, servo do Senhor, deu esta terra em possessão aos rubenitas, e aos gaditas, e à meia tribo de Manassés.'),
('acf','js',12,7,'E estes são os reis da terra aos quais Josué e os filhos de Israel feriram aquém do Jordão para o ocidente, desde Baal-Gade, no vale do Líbano, até ao monte Halaque, que sobe a Seir; e Josué a deu às tribos de Israel em possessão, segundo as suas divisões.'),
('acf','js',12,8,'O que havia nas montanhas, e nas planícies, e nas campinas, e nas descidas das águas, e no deserto, e para o sul: o heteu, o amorreu, e o cananeu, o perizeu, o heveu, e o jebuseu.'),
('acf','js',12,9,'O rei de Jericó, um; o rei de Ai, que está ao lado de Betel, outro;'),
('acf','js',12,10,'O rei de Jerusalém, outro; o rei de Hebrom, outro;'),
('acf','js',12,11,'O rei de Jarmute, outro; o rei de Laquis, outro;'),
('acf','js',12,12,'O rei de Eglom, outro; o rei de Geser, outro;'),
('acf','js',12,13,'O rei de Debir, outro; o rei de Geder, outro;'),
('acf','js',12,14,'O rei de Hormá, outro; o rei de Harade, outro;'),
('acf','js',12,15,'O rei de Libna, outro; o rei de Adulão, outro;'),
('acf','js',12,16,'O rei de Maquedá, outro; o rei de Betel, outro;'),
('acf','js',12,17,'O rei de Tapua, outro; o rei de Hefer, outro;'),
('acf','js',12,18,'O rei de Afeque, outro; o rei de Lassarom, outro;'),
('acf','js',12,19,'O rei de Madom, outro; o rei de Hazor, outro;'),
('acf','js',12,20,'O rei de Sinrom-Meron, outro; o rei de Acsafe, outro;'),
('acf','js',12,21,'O rei de Taanaque, outro; o rei de Megido, outro;'),
('acf','js',12,22,'O rei de Quedes, outro; o rei de Jocneão do Carmelo, outro;'),
('acf','js',12,23,'O rei de Dor no outeiro de Dor, outro; o rei de Goim em Gilgal, outro;'),
('acf','js',12,24,'O rei de Tirza, outro; trinta e um reis ao todo.'),
('acf','js',13,1,'Era, porém, Josué já velho, entrado em dias; e disse-lhe o SENHOR: Já estás velho, entrado em dias; e ainda muitíssima terra ficou para possuir.'),
('acf','js',13,2,'A terra que ainda fica é esta: Todos os termos dos filisteus e toda a Gesur;'),
('acf','js',13,3,'Desde Sior, que está em frente ao Egito, até ao termo de Ecrom para o norte, que se diz ser dos cananeus; cinco príncipes dos filisteus; o gazeu, e o asdodeu, o asqueloneu, o giteu, e o ecroneu, e os aveus;'),
('acf','js',13,4,'Desde o sul, toda a terra dos cananeus, e Meara, que é dos sidônios; até Afeca, até ao termo dos amorreus;'),
('acf','js',13,5,'Como também a terra dos gebalitas, e todo o Líbano, para o nascente do sol, desde Baal-Gade, ao pé do monte Hermom, até a entrada de Hamate;'),
('acf','js',13,6,'Todos os que habitam nas montanhas desde o Líbano até Misrefote-Maim, todos os sidônios; eu os lançarei de diante dos filhos de Israel; tão-somente reparte a terra em herança a Israel, como já te mandei.'),
('acf','js',13,7,'Reparte, pois, agora esta terra por herança às nove tribos, e à meia tribo de Manassés,'),
('acf','js',13,8,'Com a qual os rubenitas e os gaditas já receberam a sua herança, além do Jordão para o oriente, assim como já lhes tinha dado Moisés, servo do Senhor.'),
('acf','js',13,9,'Desde Aroer, que está à beira do ribeiro de Arnom, e a cidade que está no meio do vale, e toda a campina de Medeba até Dibom;'),
('acf','js',13,10,'E todas as cidades de Siom, rei dos amorreus, que reinou em Hesbom, até ao termo dos filhos de Amom;'),
('acf','js',13,11,'E Gileade, e o termo dos gesureus, e dos maacateus, e todo o monte Hermom, e toda a Basã até Salcá;'),
('acf','js',13,12,'Todo o reino de Ogue em Basã, que reinou em Astarote e em Edrei; este ficou do restante dos gigantes que Moisés feriu e expulsou.'),
('acf','js',13,13,'Porém os filhos de Israel não expulsaram os gesureus, nem os maacateus; antes Gesur e Maacate ficaram habitando no meio de Israel até ao dia de hoje.'),
('acf','js',13,14,'Tão-somente à tribo de Levi não deu herança; os sacrifícios queimados do Senhor Deus de Israel são a sua herança, como já lhe tinha falado.'),
('acf','js',13,15,'Assim Moisés deu à tribo dos filhos de Rúben, conforme as suas famílias.'),
('acf','js',13,16,'E foi o seu limite desde Aroer, que está à beira do ribeiro de Arnom, e a cidade que está no meio do vale, e toda a campina até Medeba;'),
('acf','js',13,17,'Hesbom e todas as suas cidades, que estão na campina; Dibom, e Bamote-Baal, e Bete-Baal-Meom;'),
('acf','js',13,18,'E Jasa e Quedemote, e Mefaate;'),
('acf','js',13,19,'E Quiriataim e Sibma, e Zerete-Saar, no monte do vale;'),
('acf','js',13,20,'Bete-Peor, e Asdote-Pisga, Bete-Jesimote;'),
('acf','js',13,21,'E todas as cidades da campina, e todo o reino de Siom, rei dos amorreus, que reinou em Hesbom, a quem Moisés feriu, como também aos príncipes de Midiã, Evi, e Requém, e Zur, e Hur, e Reba, príncipes de Siom, moradores da terra.'),
('acf','js',13,22,'Também os filhos de Israel mataram à espada a Balaão, filho de Beor, o adivinho, com os outros que por eles foram mortos.'),
('acf','js',13,23,'E o termo dos filhos de Rúben ficou sendo o Jordão e os seus limites; esta foi a herança dos filhos de Rúben, segundo as suas famílias, as cidades, e as suas aldeias.'),
('acf','js',13,24,'E deu Moisés à tribo de Gade, aos filhos de Gade, segundo as suas famílias.'),
('acf','js',13,25,'E foi o seu termo Jazer, e todas as cidades de Gileade, e metade da terra dos filhos de Amom, até Aroer, que está em frente de Rabá.'),
('acf','js',13,26,'E desde Hesbom até Ramate-Mizpá e Betonim, e desde Maanaim até ao termo de Debir;'),
('acf','js',13,27,'E no vale Bete-Arã, e Bete-Nimra, e Sucote, Zafom, que ficara do restante do reino de Siom, em Hesbom, o Jordão e o seu termo, até a extremidade do mar de Quinerete além do Jordão para o oriente.'),
('acf','js',13,28,'Esta é a herança dos filhos de Gade segundo as suas famílias, as cidades e as suas aldeias.'),
('acf','js',13,29,'Deu também Moisés herança à meia tribo de Manassés; e deu à meia tribo dos filhos de Manassés, segundo as suas famílias.'),
('acf','js',13,30,'De maneira que o seu termo foi desde Maanaim, todo o Basã, todo o reino de Ogue, rei de Basã, e todas as aldeias de Jair, que estão em Basã, sessenta cidades,'),
('acf','js',13,31,'E metade de Gileade, e Astarote, e Edrei, cidades do reino de Ogue em Basã, deu aos filhos de Maquir, filho de Manassés, a saber, à metade dos filhos de Maquir, segundo as suas famílias.'),
('acf','js',13,32,'Isto é o que Moisés repartiu em herança nas campinas de Moabe, além do Jordão para o oriente de Jericó.'),
('acf','js',13,33,'Porém, à tribo de Levi, Moisés não deu herança; o Senhor Deus de Israel é a sua herança, como já lhe tinha falado.'),
('acf','js',14,1,'Isto, pois, é o que os filhos de Israel tiveram em herança, na terra de Canaã, o que Eleazar, o sacerdote, e Josué, filho de Num, e os cabeças dos pais das tribos dos filhos de Israel lhes fizeram repartir,'),
('acf','js',14,2,'Por sorte da sua herança, como o Senhor ordenara, pelo ministério de Moisés, acerca das nove tribos e da meia tribo.'),
('acf','js',14,3,'Porquanto às duas tribos e à meia tribo já dera Moisés herança além do Jordão; mas aos levitas não tinha dado herança entre eles.'),
('acf','js',14,4,'Porque os filhos de José eram duas tribos, Manassés e Efraim, e aos levitas não se deu herança na terra, senão cidades em que habitassem, e os seus arrabaldes para seu gado e para seus bens.'),
('acf','js',14,5,'Como o Senhor ordenara a Moisés, assim fizeram os filhos de Israel, e repartiram a terra.'),
('acf','js',14,6,'Então os filhos de Judá chegaram a Josué em Gilgal; e Calebe, filho de Jefoné o quenezeu, lhe disse: Tu sabes o que o Senhor falou a Moisés, homem de Deus, em Cades-Barnéia por causa de mim e de ti.'),
('acf','js',14,7,'Quarenta anos tinha eu, quando Moisés, servo do Senhor, me enviou de Cades-Barnéia a espiar a terra; e eu lhe trouxe resposta, como sentia no meu coração;'),
('acf','js',14,8,'Mas meus irmãos, que subiram comigo, fizeram derreter o coração do povo; eu porém perseverei em seguir ao Senhor meu Deus.'),
('acf','js',14,9,'Então Moisés naquele dia jurou, dizendo: Certamente a terra que pisou o teu pé será tua, e de teus filhos, em herança perpetuamente; pois perseveraste em seguir ao Senhor meu Deus.'),
('acf','js',14,10,'E agora eis que o Senhor me conservou em vida, como disse; quarenta e cinco anos são passados, desde que o Senhor falou esta palavra a Moisés, andando Israel ainda no deserto; e agora eis que hoje tenho já oitenta e cinco anos;'),
('acf','js',14,11,'E ainda hoje estou tão forte como no dia em que Moisés me enviou; qual era a minha força então, tal é agora a minha força, tanto para a guerra como para sair e entrar.'),
('acf','js',14,12,'Agora, pois, dá-me este monte de que o Senhor falou aquele dia; pois naquele dia tu ouviste que estavam ali os anaquins, e grandes e fortes cidades. Porventura o Senhor será comigo, para os expulsar, como o Senhor disse.'),
('acf','js',14,13,'E Josué o abençoou, e deu a Calebe, filho de Jefoné, a Hebrom em herança.'),
('acf','js',14,14,'Portanto Hebrom ficou sendo herança de Calebe, filho de Jefoné o quenezeu, até ao dia de hoje, porquanto perseverara em seguir ao Senhor Deus de Israel.'),
('acf','js',14,15,'E antes o nome de Hebrom era Quiriate-Arba, porque Arba foi o maior homem entre os anaquins. E a terra repousou da guerra.'),
('acf','js',15,1,'A sorte que coube à tribo dos filhos de Judá, segundo as suas famílias, foi até ao termo de Edom, o deserto de Zim, para o sul, na extremidade do lado meridional.'),
('acf','js',15,2,'E foi o seu termo para o sul, desde a extremidade do Mar Salgado, desde a baía que olha para o sul;'),
('acf','js',15,3,'E sai para o sul, até à subida de Acrabim, e passa a Zim, e sobe do sul a Cades-Barnéia, e passa por Hezrom, e sobe a Adar, e vira para Carca;'),
('acf','js',15,4,'E passa Azmom, e sai ao ribeiro do Egito, e as saídas deste termo vão até ao mar; este será o vosso termo do lado do sul.'),
('acf','js',15,5,'O termo, porém, para o oriente será o Mar Salgado, até à foz do Jordão; e o termo para o norte será da baía do mar, desde a foz do Jordão.'),
('acf','js',15,6,'E este termo subirá até Bete-Hogla, e passará do norte a Bete-Arabá, e este termo subirá até à pedra de Boã, filho de Rúben.'),
('acf','js',15,7,'Subirá mais este termo a Debir desde o vale de Acor, indo para o norte rumo a Gilgal, a qual está em frente da subida de Adumim, que está para o sul do ribeiro; então este termo continua até às águas de En-Semes; e as suas saídas estão do lado de En-Rogel.'),
('acf','js',15,8,'E este termo sobe pelo vale do filho de Hinom, do lado sul dos jebuseus (esta é Jerusalém) e sobe este termo até ao cume do monte que está diante do vale de Hinom para o ocidente, que está no fim do vale dos refains do lado do norte.'),
('acf','js',15,9,'Então este termo vai desde a altura do monte até à fonte das águas de Neftoa; e sai até às cidades do monte de Efrom; vai mais este termo até Baalá (esta é Quiriate-Jearim).'),
('acf','js',15,10,'Então volta este termo desde Baalá para o ocidente, até às montanhas de Seir, e passa ao lado do monte de Jearim do lado do norte (esta é Quesalom) e desce a Bete-Semes, e passa por Timna;'),
('acf','js',15,11,'Sai este termo mais ao lado de Ecrom, para o norte, e este termo vai a Sicrom e passa o monte de Baalá, e sai em Jabneel; e assim este termo finda no mar.'),
('acf','js',15,12,'Será, porém, o termo do lado do ocidente o Mar Grande, e suas adjacências; este é o termo dos filhos de Judá ao redor, segundo as suas famílias.'),
('acf','js',15,13,'Mas a Calebe, filho de Jefoné, deu uma parte no meio dos filhos de Judá, conforme a ordem do Senhor a Josué; a saber, a cidade de Arba, que é Hebrom; este Arba era pai de Anaque.'),
('acf','js',15,14,'E Calebe expulsou dali os três filhos de Anaque: Sesai, e Aimã, e Talmai, gerados de Anaque.'),
('acf','js',15,15,'E dali subiu aos habitantes de Debir; e fora antes o nome de Debir, Quiriate-Sefer.'),
('acf','js',15,16,'E disse Calebe: Quem ferir a Quiriate-Sefer, e a tomar, lhe darei a minha filha Acsa por mulher.'),
('acf','js',15,17,'Tomou-a, pois, Otniel, filho de Quenaz, irmão de Calebe; e deu-lhe a sua filha Acsa por mulher.'),
('acf','js',15,18,'E sucedeu que, vindo ela a ele, o persuadiu que pedisse um campo a seu pai; e ela desceu do seu jumento; então Calebe lhe disse: Que é que tens?'),
('acf','js',15,19,'E ela disse: Dá-me uma bênção; pois me deste terra seca, dá-me também fontes de águas. Então lhe deu as fontes superiores e as fontes inferiores.'),
('acf','js',15,20,'Esta é a herança da tribo dos filhos de Judá, segundo as suas famílias.'),
('acf','js',15,21,'São, pois, as cidades da tribo dos filhos de Judá, até ao termo de Edom, no extremo sul: Cabzeel, e Eder, e Jagur.'),
('acf','js',15,22,'E Quiná, e Dimona, e Adada,'),
('acf','js',15,23,'E Quedes, e Hazor, e Itnã,'),
('acf','js',15,24,'Zife, e Telem, e Bealote,'),
('acf','js',15,25,'E Hazor-Hadata, e Queriote-Hezrom (que é Hazor),'),
('acf','js',15,26,'Amã e Sema, e Moladá,'),
('acf','js',15,27,'E Hazar-Gada, e Hesmom, e Bete-Palete,'),
('acf','js',15,28,'E Hazar-Sual, e Berseba, e Biziotiá,'),
('acf','js',15,29,'Baalá, e Iim, e Azem,'),
('acf','js',15,30,'E Eltolade, e Quesil, e Hormá.'),
('acf','js',15,31,'E Ziclague, e Madmana, e Sansana,'),
('acf','js',15,32,'E Lebaote, e Silim, e Aim, e Rimom; todas as cidades e as suas aldeias, vinte e nove.'),
('acf','js',15,33,'Nas planícies: Estaol, e Zorá, e Asná,'),
('acf','js',15,34,'E Zanoa, e En-Ganim, Tapua, e Enã.'),
('acf','js',15,35,'E Jarmute, e Adulão, Socó, e Azeca,'),
('acf','js',15,36,'E Saaraim, e Aditaim, e Gederá, e Gederotaim; catorze cidades e as suas aldeias.'),
('acf','js',15,37,'Zenã, e Hadasa, e Migdal-Gade,'),
('acf','js',15,38,'E Dileã, e Mizpe, e Jocteel,'),
('acf','js',15,39,'Laquis, e Bozcate, e Eglom,'),
('acf','js',15,40,'E Cabom, e Laamás, e Quitlis,'),
('acf','js',15,41,'E Gederote, Bete-Dagom, e Naamá, e Maquedá, dezesseis cidades e as suas aldeias.'),
('acf','js',15,42,'Libna, e Eter, e Asã,'),
('acf','js',15,43,'E Iftá, e Asná, e Nezibe,'),
('acf','js',15,44,'E Queila, e Aczibe, e Maressa; nove cidades e as suas aldeias.'),
('acf','js',15,45,'Ecrom, com suas vilas, e as suas aldeias.'),
('acf','js',15,46,'Desde Ecrom, e até ao mar, todas as que estão do lado de Asdode, e as suas aldeias.'),
('acf','js',15,47,'Asdode, com as suas vilas e as suas aldeias; Gaza, com as suas vilas e as suas aldeias, até ao rio do Egito, e o Mar Grande e o seu termo.'),
('acf','js',15,48,'E nas montanhas: Samir, Jatir, e Socó.'),
('acf','js',15,49,'E Daná, e Quiriate-Saná (que é Debir),'),
('acf','js',15,50,'E Anabe, Estemó, e Anim,'),
('acf','js',15,51,'E Gósen, e Holom, e Giló; onze cidades e as suas aldeias.'),
('acf','js',15,52,'Arabe, e Dumá e Esã,'),
('acf','js',15,53,'E Janim, e Bete-Tapua e Afeca,'),
('acf','js',15,54,'E Hunta, e Quiriate-Arba (que é Hebrom), e Zior; nove cidades e as suas aldeias.'),
('acf','js',15,55,'Maom, Carmelo, e Zife, e Jutá,'),
('acf','js',15,56,'E Jizreel, e Jocdeão, e Zanoa,'),
('acf','js',15,57,'Caim, Gibeá, e Timna; dez cidades e as suas aldeias.'),
('acf','js',15,58,'Halul, Bete-Zur, e Gedor,'),
('acf','js',15,59,'E Maarate, e Bete-Anote, e Eltecom; seis cidades e as suas aldeias.'),
('acf','js',15,60,'Quiriate-Baal (que é Quiriate-Jearim), e Rabá; duas cidades e as suas aldeias.'),
('acf','js',15,61,'No deserto: Bete-Arabá, Midim, e Secacá,'),
('acf','js',15,62,'E Nibsã, e a Cidade do Sal, e En-Gedi; seis cidades e as suas aldeias.'),
('acf','js',15,63,'Não puderam, porém, os filhos de Judá expulsar os jebuseus que habitavam em Jerusalém; assim habitaram os jebuseus com os filhos de Judá em Jerusalém, até ao dia de hoje.'),
('acf','js',16,1,'Saiu depois a sorte dos filhos de José, desde o Jordão, na direção de Jericó, junto às águas de Jericó, para o oriente, estendendo-se pelo deserto que sobe de Jericó pelas montanhas de Betel.'),
('acf','js',16,2,'E de Betel vai para Luz, e passa ao termo dos arquitas, até Atarote,'),
('acf','js',16,3,'E desce do lado do ocidente ao termo de Jafleti, até ao termo de Bete-Horom de baixo, e até Gezer, indo terminar no mar.'),
('acf','js',16,4,'Assim alcançaram a sua herança os filhos de José, Manassés e Efraim.'),
('acf','js',16,5,'E foi o termo dos filhos de Efraim, segundo as suas famílias, como se segue: o termo da sua herança para o oriente era Atarote-Adar até Bete-Horom de cima;'),
('acf','js',16,6,'E sai este termo para o ocidente junto a Micmetá, desde o norte, e torna este termo para o oriente até Taanate-Siló, e passa por ela desde o oriente a Janoa;'),
('acf','js',16,7,'E desce desde Janoa a Atarote e a Naarate e toca em Jericó, terminando no Jordão.'),
('acf','js',16,8,'De Tapua vai este termo para o ocidente ao ribeiro de Caná, terminando no mar; esta é a herança da tribo dos filhos de Efraim, segundo as suas famílias,'),
('acf','js',16,9,'Mais as cidades que se separaram para os filhos de Efraim no meio da herança dos filhos de Manassés; todas aquelas cidades e as suas aldeias.'),
('acf','js',16,10,'E não expulsaram aos cananeus que habitavam em Gezer; e os cananeus habitam no meio dos efraimitas até ao dia de hoje; porém, sendo-lhes tributários.'),
('acf','js',17,1,'Também coube sorte à tribo de Manassés, porquanto era o primogênito de José. Maquir, o primogênito de Manassés, pai de Gileade, porquanto era homem de guerra, teve a Gileade e Basã;'),
('acf','js',17,2,'Também os demais filhos de Manassés tiveram a sua parte, segundo as suas famílias, a saber: Os filhos de Abiezer, e os filhos de Heleque, e os filhos de Asriel, e os filhos de Siquém, e os filhos de Hefer, e os filhos de Semida; esses são os filhos de Manassés, filho de José, segundo as suas famílias.'),
('acf','js',17,3,'Zelofeade, porém, filho de Hefer, filho de Gileade, filho de Maquir, filho de Manassés, não teve filhos, mas só filhas; e estes são os nomes de suas filhas: Maalá, Noa, Hogla, Milca e Tirza.'),
('acf','js',17,4,'Estas, pois, chegaram diante de Eleazar, o sacerdote, e diante de Josué, filho de Num, e diante dos príncipes, dizendo: O Senhor ordenou a Moisés que se nos desse herança no meio de nossos irmãos, pelo que, conforme a ordem do Senhor, lhes deu herança no meio dos irmãos de seu pai.'),
('acf','js',17,5,'E couberam a Manassés dez quinhões, afora a terra de Gileade e Basã, que está além do Jordão;'),
('acf','js',17,6,'Porque as filhas de Manassés receberam herança entre os filhos dele; e os outros filhos de Manassés ficaram com a terra de Gileade.'),
('acf','js',17,7,'E o termo de Manassés foi desde Aser até Micmetá, que está defronte de Siquém; e estende-se este termo à direita até os moradores de En-Tapua.'),
('acf','js',17,8,'Tinha Manassés a terra de Tapua; porém Tapua, junto ao termo de Manassés, pertencia aos filhos de Efraim.'),
('acf','js',17,9,'Então descia este termo ao ribeiro de Caná. A Efraim couberam as cidades ao sul do ribeiro, entre as cidades de Manassés; e o termo de Manassés estava ao norte do ribeiro, indo terminar no mar.'),
('acf','js',17,10,'Efraim ao sul, e Manassés ao norte, e o mar é o seu termo; pelo norte tocam em Aser, e pelo oriente em Issacar.'),
('acf','js',17,11,'Porque em Issacar e em Aser tinha Manassés a Bete-Seã e as suas vilas, e Ibleã e as suas vilas, e os habitantes de Dor e as suas vilas, e os habitantes de En-Dor e as suas vilas, e os habitantes de Taanaque e as suas vilas, e os habitantes de Megido e as suas vilas; três outeiros.'),
('acf','js',17,12,'E os filhos de Manassés não puderam expulsar os habitantes daquelas cidades; porquanto os cananeus queriam habitar na mesma terra.'),
('acf','js',17,13,'E sucedeu que, engrossando em forças os filhos de Israel, fizeram tributários aos cananeus; porém não os expulsaram de todo.'),
('acf','js',17,14,'Então os filhos de José falaram a Josué, dizendo: Por que me deste por herança só uma sorte e um quinhão, sendo eu um tão grande povo, visto que o Senhor até aqui me tem abençoado?'),
('acf','js',17,15,'E disse-lhes Josué: Se tão grande povo és, sobe ao bosque, e ali corta, para ti, lugar na terra dos perizeus e dos refains; pois que as montanhas de Efraim te são tão estreitas.'),
('acf','js',17,16,'Então disseram os filhos de José: As montanhas não nos bastariam; também carros de ferro há entre todos os cananeus que habitam na terra do vale, entre os de Bete-Seã e as suas vilas, e entre os que estão no vale de Jizreel.'),
('acf','js',17,17,'Então Josué falou à casa de José, a Efraim e a Manassés, dizendo: Grande povo és, e grande força tens; não terás uma sorte apenas;'),
('acf','js',17,18,'Porém as montanhas serão tuas. Ainda que é bosque, cortá-lo-ás, e as suas extremidades serão tuas; porque expulsarás os cananeus, ainda que tenham carros de ferro, ainda que sejam fortes.'),
('acf','js',18,1,'E Toda a congregação dos filhos de Israel se reuniu em Siló, e ali armaram a tenda da congregação, depois que a terra lhes foi sujeita.'),
('acf','js',18,2,'E dentre os filhos de Israel ficaram sete tribos que ainda não tinham repartido a sua herança.'),
('acf','js',18,3,'E disse Josué aos filhos de Israel: Até quando sereis negligentes em chegardes para possuir a terra que o Senhor Deus de vossos pais vos deu?'),
('acf','js',18,4,'De cada tribo escolhei vós três homens, para que eu os envie, e eles se levantem e percorram a terra, e a demarquem segundo as suas heranças, e voltem a mim.'),
('acf','js',18,5,'E dividi-la-ão em sete partes: Judá ficará no seu termo para o sul, e a casa de José ficará no seu termo para o norte.'),
('acf','js',18,6,'E vós demarcareis a terra em sete partes, e me trareis a mim aqui descrita, para que eu aqui lance as sortes perante o Senhor nosso Deus,'),
('acf','js',18,7,'Porquanto os levitas não têm parte no meio de vós, porque o sacerdócio do Senhor é a sua parte; e Gade, e Rúben, e a meia tribo de Manassés, receberam a sua herança além do Jordão para o oriente, a qual lhes deu Moisés, o servo do Senhor.'),
('acf','js',18,8,'Então aqueles homens se levantaram e se foram; e Josué deu ordem aos que iam demarcar a terra, dizendo: Ide, e percorrei a terra, e demarcai-a, e então voltai a mim, e aqui vos lançarei as sortes perante o Senhor, em Siló.'),
('acf','js',18,9,'Foram, pois, aqueles homens, e passaram pela terra, e a demarcaram, em sete partes segundo as cidades, descrevendo-a num livro; e voltaram a Josué, ao arraial em Siló.'),
('acf','js',18,10,'Então Josué lhes lançou as sortes em Siló, perante o Senhor; e ali repartiu Josué a terra aos filhos de Israel, conforme às suas divisões.'),
('acf','js',18,11,'E tirou a sorte da tribo dos filhos de Benjamim, segundo as suas famílias; e coube-lhe o termo da sua sorte entre os filhos de Judá e os filhos de José.'),
('acf','js',18,12,'E o seu termo foi para o lado do norte, desde o Jordão; e sobe aquele termo ao lado de Jericó para o norte, e sobe pela montanha para o ocidente, terminando no deserto de Bete-Áven.'),
('acf','js',18,13,'E dali passa este termo a Luz, ao lado de Luz (que é Betel), para o sul; e desce a Atarote-Adar, ao pé do monte que está do lado do sul de Bete-Horom de baixo;'),
('acf','js',18,14,'E vai este termo e volta ao lado do ocidente para o sul do monte que está defronte de Bete-Horom, para o sul, terminando em Quiriate-Baal (que é Quiriate-Jearim), cidade dos filhos de Judá; esta é a sua extensão para o ocidente.'),
('acf','js',18,15,'E a sua extensão para o sul começa na extremidade de Quiriate-Jearim; e vai este termo ao ocidente e segue até à fonte das águas de Neftoa.'),
('acf','js',18,16,'E desce este termo até à extremidade do monte que está defronte do vale do filho de Hinom, que está no vale dos refains para o norte, e desce pelo vale de Hinom do lado dos jebuseus para o sul; e então desce a En-Rogel;'),
('acf','js',18,17,'E vai desde o norte, e chega a En-Semes; e dali sai a Gelilote, que está defronte da subida de Adumim, e desce à pedra de Boã, filho de Rúben;'),
('acf','js',18,18,'E passa até ao lado, defronte de Arabá, para o norte, e desce a Arabá.'),
('acf','js',18,19,'Passa mais este termo até ao lado de Bete-Hogla, para o norte, saindo esse termo na baía do Mar Salgado, para o norte, na extremidade do Jordão, para o sul; este é o termo do sul.'),
('acf','js',18,20,'E o Jordão será seu termo do lado do oriente; esta é a herança dos filhos de Benjamim, nos seus termos em redor, segundo as suas famílias.'),
('acf','js',18,21,'E as cidades da tribo dos filhos de Benjamim, segundo as suas famílias, são: Jericó, e Bete-Hogla, e Emeque-Queziz,'),
('acf','js',18,22,'E Bete-Arabá, e Zemaraim, e Betel,'),
('acf','js',18,23,'E Avim, e Pará, e Ofra,'),
('acf','js',18,24,'E Quefar-Amonai, e Ofni e Gaba: doze cidades e as suas aldeias;'),
('acf','js',18,25,'Gibeão, e Ramá e Beerote,'),
('acf','js',18,26,'E Mizpá, e Cefira e Moza,'),
('acf','js',18,27,'E Requém e Irpeel, e Tarala,'),
('acf','js',18,28,'E Zela, Elefe, e Jebus (esta é Jerusalém), Gibeá e Quiriate: catorze cidades com as suas aldeias; esta é a herança dos filhos de Benjamim, segundo as suas famílias.'),
('acf','js',19,1,'E Saiu a segunda sorte a Simeão, para a tribo dos filhos de Simeão, segundo as suas famílias; e foi a sua herança no meio da herança dos filhos de Judá.'),
('acf','js',19,2,'E tiveram na sua herança: Berseba, e Seba e Moladá.'),
('acf','js',19,3,'E Hazar-Sual, e Balá, e Azem,'),
('acf','js',19,4,'E Eltolade, e Betul, e Hormá,'),
('acf','js',19,5,'E Ziclague, e Bete-Marcabote, e Hazar-Susa,'),
('acf','js',19,6,'E Bete-Lebaote, e Saruém; treze cidades e as suas aldeias.'),
('acf','js',19,7,'E Aim, e Rimom, e Eter, e Asã; quatro cidades e as suas aldeias.'),
('acf','js',19,8,'E todas as aldeias que havia em redor destas cidades, até Baalate-Ber (que é Ramá), do sul; esta é a herança da tribo dos filhos de Simeão, segundo as suas famílias.'),
('acf','js',19,9,'A herança dos filhos de Simeão foi tirada do quinhão dos de Judá, porquanto a herança dos filhos de Judá era demasiadamente grande para eles; pelo que os filhos de Simeão tiveram a sua herança no meio deles.'),
('acf','js',19,10,'E saiu a terceira sorte pelos filhos de Zebulom, segundo as suas famílias; e foi o termo da sua herança até Saride.'),
('acf','js',19,11,'E sobe o seu termo pelo ocidente a Maralá, e vai até Dabesete, e chega também até ao ribeiro que está defronte de Jocneão.'),
('acf','js',19,12,'E de Saride volta para o oriente, para o nascente do sol, até ao termo de Quislote-Tabor, sai a Daberate, e vai subindo a Jafia.'),
('acf','js',19,13,'E dali passa pelo oriente, para o nascente, a Gate-Hefer, em Ete-Cazim, chegando a Rimom-Metoar, que vai até Neá;'),
('acf','js',19,14,'E rodeando-a, passa o termo para o norte a Hanatom, chegando ao vale de Iftá-El,'),
('acf','js',19,15,'E Catate, Naalal, e Sinrom, e Idala, e Belém; doze cidades e as suas aldeias.'),
('acf','js',19,16,'Esta é a herança dos filhos de Zebulom, segundo as suas famílias; estas cidades e as suas aldeias.'),
('acf','js',19,17,'A quarta sorte saiu para Issacar; aos filhos de Issacar, segundo as suas famílias.'),
('acf','js',19,18,'E foi o seu termo Jizreel, e Quesulote e Suném,'),
('acf','js',19,19,'E Hafaraim, e Siom, e Anaarate,'),
('acf','js',19,20,'E Rabite e Quisiom, e Ebes,'),
('acf','js',19,21,'E Remete, e En-Ganim, e En-Hadá, e Bete-Pazez.'),
('acf','js',19,22,'E chega este termo até Tabor, e Saazima, e Bete-Semes; e vai terminar no Jordão; dezesseis cidades e as suas aldeias.'),
('acf','js',19,23,'Esta é a herança da tribo dos filhos de Issacar, segundo as suas famílias; estas cidades e as suas aldeias.'),
('acf','js',19,24,'E saiu a quinta sorte para a tribo dos filhos de Aser, segundo as suas famílias.'),
('acf','js',19,25,'E foi o seu termo Helcate, e Hali, e Béten, e Acsafe,'),
('acf','js',19,26,'E Alameleque, e Amade, e Misal; e chega ao Carmelo para o ocidente, e a Sior-Libnate;'),
('acf','js',19,27,'E volta para o nascente do sol a Bete-Dagom, e chega a Zebulom e ao vale de Iftá-El, ao norte de Bete-Emeque e de Neiel, e vem sair a Cabul, pela esquerda,'),
('acf','js',19,28,'E Hebrom, e Reobe, e Hamom, e Caná, até à grande Sidom.'),
('acf','js',19,29,'E volta este termo a Ramá, e até à forte cidade de Tiro; então torna este termo a Hosa, para terminar no mar, na região de Aczibe.'),
('acf','js',19,30,'E Umá, e Afeque, e Reobe; vinte e duas cidades e as suas aldeias.'),
('acf','js',19,31,'Esta é a herança da tribo dos filhos de Aser, segundo as suas famílias; estas cidades e as suas aldeias.'),
('acf','js',19,32,'E saiu a sexta sorte para os filhos de Naftali, segundo as suas famílias.'),
('acf','js',19,33,'E foi o seu termo desde Helefe e desde Alom em Zaananim, e Adami-Neguebe, e Jabneel, até Lacum, terminando no Jordão.'),
('acf','js',19,34,'E volta este termo pelo ocidente a Aznote-Tabor, e dali passa a Hucoque; e chega a Zebulom ao sul, e chega a Aser ao ocidente, e a Judá pelo Jordão, ao nascente do sol.'),
('acf','js',19,35,'E são as cidades fortificadas: Zidim, Zer, e Hamate, Racate e Quinerete,'),
('acf','js',19,36,'E Adama, e Ramá, e Hazor,'),
('acf','js',19,37,'E Quedes, e Edrei, e En-Hazor,'),
('acf','js',19,38,'E Irom, e Migdal-El, Horém e Bete-Anate, e Bete-Semes; dezenove cidades e as suas aldeias.'),
('acf','js',19,39,'Esta é a herança da tribo dos filhos de Naftali, segundo as suas famílias; estas cidades e as suas aldeias.'),
('acf','js',19,40,'A sétima sorte saiu para a tribo dos filhos de Dã, segundo as suas famílias.'),
('acf','js',19,41,'E foi o termo da sua herança, Sora, e Estaol, e Ir-Semes,'),
('acf','js',19,42,'E Saalabim, e Aijalom, e Itla,'),
('acf','js',19,43,'E Elom, e Timna, e Ecrom,'),
('acf','js',19,44,'E Elteque, e Gibetom, e Baalate,'),
('acf','js',19,45,'E Jeúde, e Bene-Beraque, e Gate-Rimom,'),
('acf','js',19,46,'E Me-Jarcom, e Racom, com o termo defronte de Jafo;'),
('acf','js',19,47,'Saiu, porém, pequeno termo aos filhos de Dã, pelo que subiram os filhos de Dã, e pelejaram contra Lesém, e a tomaram, e a feriram ao fio da espada, e a possuíram e habitaram nela; e a Lesém chamaram Dã, conforme ao nome de Dã seu pai.'),
('acf','js',19,48,'Esta é a herança da tribo dos filhos de Dã, segundo as suas famílias; estas cidades e as suas aldeias.'),
('acf','js',19,49,'Acabando, pois, de repartir a terra em herança segundo os seus termos, deram os filhos de Israel a Josué, filho de Num, herança no meio deles.'),
('acf','js',19,50,'Segundo o mandado do Senhor lhe deram a cidade que pediu, a Timnate-Sera, na montanha de Efraim; e reedificou aquela cidade, e habitou nela.'),
('acf','js',19,51,'Estas são as heranças que Eleazar, o sacerdote, e Josué, filho de Num, e os cabeças dos pais das famílias repartiram às tribos dos filhos de Israel, em herança, por sorte, em Siló, perante o Senhor, à porta da tenda da congregação. E assim acabaram de repartir a terra.'),
('acf','js',20,1,'Falou mais o SENHOR a Josué, dizendo:'),
('acf','js',20,2,'Fala aos filhos de Israel, dizendo: Apartai para vós as cidades de refúgio, de que vos falei pelo ministério de Moisés,'),
('acf','js',20,3,'Para que fuja para ali o homicida, que matar alguma pessoa por engano, e não com intenção; para que vos sirvam de refúgio contra o vingador do sangue.'),
('acf','js',20,4,'E fugindo para alguma daquelas cidades, pôr-se-á à porta dela e exporá a sua causa aos ouvidos dos anciãos da tal cidade; então o tomarão consigo na cidade; e lhe darão lugar, para que habite com eles.'),
('acf','js',20,5,'E se o vingador do sangue o seguir, não entregarão na sua mão o homicida, porquanto não feriu a seu próximo com intenção, e não o odiou antes.'),
('acf','js',20,6,'E habitará na mesma cidade, até que compareça em juízo perante a congregação, até que morra o sumo sacerdote que houver naqueles dias; então o homicida voltará, e virá à sua cidade e à sua casa, à cidade de onde fugiu.'),
('acf','js',20,7,'Então designaram a Quedes na Galiléia, na montanha de Naftali, e a Siquém, na montanha de Efraim, e a Quiriate-Arba (esta é Hebrom), na montanha de Judá.'),
('acf','js',20,8,'E, além do Jordão, na direção de Jericó para o oriente, designaram a Bezer, no deserto, na campina da tribo de Rúben, e a Ramote, em Gileade da tribo de Gade, e a Golã, em Basã da tribo de Manassés.'),
('acf','js',20,9,'Estas são as cidades que foram designadas para todos os filhos de Israel, e para o estrangeiro que habitasse entre eles, para que se acolhesse a elas todo aquele que por engano matasse alguma pessoa, para que não morresse às mãos do vingador do sangue, até se apresentar diante da congregação.'),
('acf','js',21,1,'Então os cabeças dos pais dos levitas se achegaram a Eleazar, o sacerdote, e a Josué, filho de Num, e aos cabeças dos pais das tribos dos filhos de Israel;'),
('acf','js',21,2,'E falaram-lhes em Siló, na terra de Canaã, dizendo: O Senhor ordenou, pelo ministério de Moisés, que se nos dessem cidades para habitar, e os seus arrabaldes para os nossos animais.'),
('acf','js',21,3,'Por isso os filhos de Israel deram aos levitas da sua herança, conforme a ordem do Senhor, as seguintes cidades e os seus arrabaldes.'),
('acf','js',21,4,'E saiu a sorte para as famílias dos coatitas; e aos filhos de Arão, o sacerdote, que eram dos levitas, tiveram por sorte da tribo de Judá, e da tribo de Simeão, e da tribo de Benjamim, treze cidades;'),
('acf','js',21,5,'E aos outros filhos de Coate couberam por sorte, das famílias da tribo de Efraim, e da tribo de Dã, e da meia tribo de Manassés, dez cidades;'),
('acf','js',21,6,'E aos filhos de Gérson couberam por sorte, das famílias da tribo de Issacar, e da tribo de Aser, e da tribo de Naftali, e da meia tribo de Manassés, em Basã, treze cidades;'),
('acf','js',21,7,'Aos filhos de Merari, segundo as suas famílias, da tribo de Rúben, e da tribo de Gade, e da tribo de Zebulom, doze cidades;'),
('acf','js',21,8,'E deram os filhos de Israel aos levitas estas cidades e os seus arrabaldes por sorte, como o Senhor ordenara pelo ministério de Moisés.'),
('acf','js',21,9,'Deram mais, da tribo dos filhos de Judá e da tribo dos filhos de Simeão, estas cidades, que por nome foram mencionadas,'),
('acf','js',21,10,'Para que fossem dos filhos de Arão, das famílias dos coatitas dos filhos de Levi; porquanto a primeira sorte foi sua.'),
('acf','js',21,11,'Assim lhes deram a cidade de Arba, do pai de Anaque (esta é Hebrom), no monte de Judá, e os seus arrabaldes ao redor.'),
('acf','js',21,12,'Porém o campo da cidade, e as suas aldeias, deram a Calebe, filho de Jefoné, por sua possessão.'),
('acf','js',21,13,'Assim aos filhos de Arão, o sacerdote, deram Hebrom, cidade do refúgio do homicida, e os seus arrabaldes, Libna e os seus arrabaldes;'),
('acf','js',21,14,'Jatir e os seus arrabaldes, e Estemoa e os seus arrabaldes;'),
('acf','js',21,15,'E Holom e os seus arrabaldes, e Debir e os seus arrabaldes;'),
('acf','js',21,16,'E Aim e os seus arrabaldes, e Jutá e os seus arrabaldes, e Bete-Semes e os seus arrabaldes; nove cidades destas duas tribos.'),
('acf','js',21,17,'E da tribo de Benjamim, Gibeão e os seus arrabaldes, Geba e os seus arrabaldes;'),
('acf','js',21,18,'Anatote e os seus arrabaldes, e Almom e os seus arrabaldes; quatro cidades.'),
('acf','js',21,19,'Todas as cidades dos sacerdotes, filhos de Arão, foram treze cidades e os seus arrabaldes.'),
('acf','js',21,20,'E as famílias dos filhos de Coate, levitas, que ficaram dos filhos de Coate, tiveram as cidades da sua sorte, da tribo de Efraim.'),
('acf','js',21,21,'E deram-lhes Siquém, cidade de refúgio do homicida, e os seus arrabaldes, no monte de Efraim, e Gezer e os seus arrabaldes;'),
('acf','js',21,22,'E Quibzaim e os seus arrabaldes, e Bete-Horom e os seus arrabaldes; quatro cidades.'),
('acf','js',21,23,'E da tribo de Dã, Elteque e os seus arrabaldes, Gibetom e os seus arrabaldes;'),
('acf','js',21,24,'Aijalom e os seus arrabaldes, Gate-Rimom e os seus arrabaldes; quatro cidades.'),
('acf','js',21,25,'E da meia tribo de Manassés, Taanaque e os seus arrabaldes, e Gate-Rimom e os seus arrabaldes; duas cidades.'),
('acf','js',21,26,'As cidades para as famílias dos demais filhos de Coate, foram dez e os seus arrabaldes.'),
('acf','js',21,27,'E aos filhos de Gérson, das famílias dos levitas, deram da meia tribo de Manassés, Golã, cidade de refúgio do homicida, em Basã, e os seus arrabaldes, e Beesterá e os seus arrabaldes; duas cidades.'),
('acf','js',21,28,'E da tribo de Issacar, Quisiom e os seus arrabaldes, Daberate e os seus arrabaldes,'),
('acf','js',21,29,'Jarmute e os seus arrabaldes, En-Ganim e os seus arrabaldes; quatro cidades.'),
('acf','js',21,30,'E da tribo de Aser, Misal e os seus arrabaldes, Abdom e os seus arrabaldes,'),
('acf','js',21,31,'Helcate e os seus arrabaldes, e Reobe e os seus arrabaldes;'),
('acf','js',21,32,'E da tribo de Naftali, Quedes, cidade de refúgio do homicida, na Galiléia, e os seus arrabaldes, e Hamote-Dor e os seus arrabaldes, e Cartã e os seus arrabaldes; três cidades.'),
('acf','js',21,33,'Todas as cidades dos gersonitas, segundo as suas famílias, foram treze cidades e os seus arrabaldes.'),
('acf','js',21,34,'E às famílias dos filhos de Merari, aos demais levitas, foram dadas, da tribo de Zebulom, Jocneão e os seus arrabaldes, Cartã e os seus arrabaldes,'),
('acf','js',21,35,'Dimna e os seus arrabaldes, Naalal e os seus arrabaldes; quatro cidades.'),
('acf','js',21,36,'E da tribo de Rúben, Bezer e os seus arrabaldes, e Jaza e os seus arrabaldes,'),
('acf','js',21,37,'Quedemote e os seus arrabaldes, e Mefaate e os seus arrabaldes; quatro cidades.'),
('acf','js',21,38,'E da tribo de Gade, Ramote, cidade de refúgio do homicida, em Gileade, e os seus arrabaldes, e Maanaim e os seus arrabaldes,'),
('acf','js',21,39,'Hesbom e os seus arrabaldes, Jazer e os seus arrabaldes; ao todo, quatro cidades.'),
('acf','js',21,40,'Todas estas cidades foram dos filhos de Merari, segundo as suas famílias, que ainda restavam das famílias dos dos levitas; e foi a sua sorte doze cidades.'),
('acf','js',21,41,'Todas as cidades dos levitas, no meio da herança dos filhos de Israel, foram quarenta e oito cidades e os seus arrabaldes.'),
('acf','js',21,42,'Estavam estas cidades, cada uma com os seus arrabaldes em redor delas; assim estavam todas estas cidades.'),
('acf','js',21,43,'Desta maneira deu o Senhor a Israel toda a terra que jurara dar a seus pais; e a possuíram e habitaram nela.'),
('acf','js',21,44,'E o Senhor lhes deu repouso de todos os lados, conforme a tudo quanto jurara a seus pais; e nenhum de todos os seus inimigos pôde resisti-los; todos os seus inimigos o Senhor entregou-lhes nas mãos.'),
('acf','js',21,45,'Palavra alguma falhou de todas as boas coisas que o Senhor falou à casa de Israel; tudo se cumpriu.'),
('acf','js',22,1,'Então Josué chamou os rubenitas, e os gaditas, e a meia tribo de Manassés.'),
('acf','js',22,2,'E disse-lhes: Tudo quanto Moisés, o servo do Senhor, vos ordenou, guardastes; e à minha voz obedecestes em tudo quanto vos ordenei.'),
('acf','js',22,3,'A vossos irmãos por todo este tempo, até ao dia de hoje, não desamparastes; antes tivestes cuidado de guardar o mandamento do Senhor vosso Deus.'),
('acf','js',22,4,'Agora o Senhor vosso Deus deu repouso a vossos irmãos, como lhes tinha prometido; voltai-vos, pois, agora, e ide-vos às vossas tendas, à terra da vossa possessão, que Moisés, o servo do Senhor, vos deu além do Jordão.'),
('acf','js',22,5,'Tão-somente tende cuidado de guardar com diligência o mandamento e a lei que Moisés, o servo do Senhor, vos mandou: que ameis ao Senhor vosso Deus, e andeis em todos os seus caminhos, e guardeis os seus mandamentos, e vos achegueis a ele, e o sirvais com todo o vosso coração, e com toda a vossa alma.'),
('acf','js',22,6,'Assim Josué os abençoou, e despediu-os; e foram-se às suas tendas.'),
('acf','js',22,7,'Ora, Moisés dera herança em Basã à meia tribo de Manassés, porém à outra metade Josué deu herança entre seus irmãos aquém do Jordão para o ocidente; e enviando-os Josué também às suas tendas os abençoou;'),
('acf','js',22,8,'E falou-lhes, dizendo: Voltai-vos às vossas tendas com grandes riquezas, e com muitíssimo gado, com prata, e com ouro, e com metal, e com ferro, e com muitíssimas roupas; e com vossos irmãos reparti o despojo dos vossos inimigos.'),
('acf','js',22,9,'Assim os filhos de Rúben, e os filhos de Gade, e a meia tribo de Manassés voltaram, e separaram-se dos filhos de Israel, de Siló, que está na terra de Canaã, para irem à terra de Gileade, à terra da sua possessão, de que foram feitos possuidores, conforme a ordem do Senhor pelo ministério de Moisés.'),
('acf','js',22,10,'E, chegando eles aos limites do Jordão, ainda na terra de Canaã, ali os filhos de Rúben, e os filhos de Gade, e a meia tribo de Manassés edificaram um altar junto ao Jordão, um altar de grande aparência.'),
('acf','js',22,11,'E ouviram os filhos de Israel dizer: Eis que os filhos de Rúben, e os filhos de Gade, e a meia tribo de Manassés edificaram um altar diante da terra de Canaã, nos limites do Jordão, do lado dos filhos de Israel.'),
('acf','js',22,12,'Ouvindo isso os filhos de Israel, reuniu-se toda a congregação dos filhos de Israel em Siló, para saírem em guerra contra eles.'),
('acf','js',22,13,'E enviaram os filhos de Israel, aos filhos de Rúben, e aos filhos de Gade, e à meia tribo de Manassés, na terra de Gileade, a Finéias, filho de Eleazar, o sacerdote,'),
('acf','js',22,14,'E a dez príncipes com ele, de cada casa paterna um príncipe, de todas as tribos de Israel; e cada um era cabeça da casa de seus pais entre os milhares de Israel.'),
('acf','js',22,15,'E, indo eles aos filhos de Rúben, e aos filhos de Gade, e à meia tribo de Manassés, à terra de Gileade, falaram-lhes, dizendo:'),
('acf','js',22,16,'Assim diz toda a congregação do Senhor: Que transgressão é esta, que cometestes contra o Deus de Israel, deixando hoje de seguir ao Senhor, edificando-vos um altar, para vos rebelardes contra o Senhor?'),
('acf','js',22,17,'Foi-nos pouco a iniqüidade de Peor, de que ainda até o dia de hoje não estamos purificados, mesmo que tenha havido castigo na congregação do Senhor,'),
('acf','js',22,18,'Para que hoje deixais de seguir o Senhor? Será que rebelando-vos hoje contra o Senhor, amanhã ele se irará contra toda a congregação de Israel.'),
('acf','js',22,19,'Se é, porém, que a terra da vossa herança é imunda, passai-vos para a terra da possessão do Senhor, onde habita o tabernáculo do Senhor, e tomai possessão entre nós; mas não vos rebeleis contra o Senhor, nem tampouco vos rebeleis contra nós, edificando-vos um altar, além do altar do Senhor nosso Deus.'),
('acf','js',22,20,'Não cometeu Acã, filho de Zerá, transgressão no tocante ao anátema? Não veio ira sobre toda a congregação de Israel, de modo que aquele homem não morreu só, na sua iniqüidade?'),
('acf','js',22,21,'Então responderam os filhos de Rúben, e os filhos de Gade, e a meia tribo de Manassés, e disseram aos cabeças dos milhares de Israel:'),
('acf','js',22,22,'O Senhor Deus dos deuses, o Senhor Deus dos deuses, ele o sabe, e Israel mesmo o saberá. Se foi por rebeldia, ou por transgressão contra o Senhor, hoje não nos preserve;'),
('acf','js',22,23,'Se nós edificamos um altar para nos desviarmos do Senhor, ou para sobre ele oferecer holocausto e oferta de alimentos, ou sobre ele apresentar oferta pacífica, o Senhor mesmo de nós o requeira.'),
('acf','js',22,24,'E, se antes o não fizemos por receio disto, dizendo: Amanhã vossos filhos virão a falar a nossos filhos, dizendo: Que tendes vós com o Senhor Deus de Israel?'),
('acf','js',22,25,'Pois o Senhor pôs o Jordão por termo entre nós e vós, ó filhos de Rúben, e filhos de Gade; não tendes parte no Senhor; e assim bem poderiam vossos filhos fazer desistir a nossos filhos de temer ao Senhor.'),
('acf','js',22,26,'Por isso dissemos: Preparemo-nos agora, e edifiquemos um altar, não para holocausto, nem para sacrifício,'),
('acf','js',22,27,'Mas para que, entre nós e vós, e entre as nossas gerações depois de nós, nos seja em testemunho, para podermos fazer o serviço do Senhor diante dele com os nossos holocaustos, e com os nossos sacrifícios, e com as nossas ofertas pacíficas; para que vossos filhos não digam amanhã a nossos filhos: Não tendes parte no Senhor.'),
('acf','js',22,28,'Por isso dissemos: Quando suceder que amanhã assim nos digam a nós e às nossas gerações, então diremos: Vede o modelo do altar do Senhor que fizeram nossos pais, não para holocausto nem para sacrifício, porém para ser testemunho entre nós e vós.'),
('acf','js',22,29,'Nunca tal nos aconteça que nos rebelemos contra o Senhor, ou que hoje nós abandonássemos o Senhor, edificando altar para holocausto, oferta de alimentos ou sacrifício, fora do altar do Senhor nosso Deus, que está perante o seu tabernáculo.'),
('acf','js',22,30,'Ouvindo, pois, Finéias, o sacerdote, e os príncipes da congregação, e os cabeças dos milhares de Israel, que com eles estavam, as palavras que disseram os filhos de Rúben, e os filhos de Gade, e os filhos de Manassés, pareceu bem aos seus olhos.'),
('acf','js',22,31,'E disse Finéias, filho de Eleazar, o sacerdote, aos filhos de Rúben, e aos filhos de Gade, e aos filhos de Manassés: Hoje sabemos que o Senhor está no meio de nós; porquanto não cometestes transgressão contra o Senhor; agora livrastes os filhos de Israel da mão do Senhor.'),
('acf','js',22,32,'E Finéias filho de Eleazar, o sacerdote, com os príncipes, deixando os filhos de Rúben, e os filhos de Gade, voltaram da terra de Gileade à terra de Canaã, aos filhos de Israel, e trouxeram-lhes a resposta.'),
('acf','js',22,33,'E pareceu a resposta boa aos olhos dos filhos de Israel, e os filhos de Israel louvaram a Deus; e não falaram mais em subir à guerra contra eles em exército, para destruírem a terra em que habitavam os filhos de Rúben e os filhos de Gade.'),
('acf','js',22,34,'E os filhos de Rúben e os filhos de Gade deram ao altar o nome de Ede; para que seja testemunho entre nós que o Senhor é Deus.'),
('acf','js',23,1,'E sucedeu que, muitos dias depois que o SENHOR dera repouso a Israel de todos os seus inimigos em redor, e sendo Josué já velho e entrado em dias,'),
('acf','js',23,2,'Chamou Josué a todo o Israel, aos seus anciãos, e aos seus cabeças, e aos seus juízes, e aos seus oficiais, e disse-lhes: Eu já sou velho e entrado em dias,'),
('acf','js',23,3,'E vós já tendes visto tudo quanto o Senhor vosso Deus fez a todas estas nações por causa de vós; porque o Senhor vosso Deus é que tem pelejado por vós.'),
('acf','js',23,4,'Vede que vos reparti por sorte, em herança às vossas tribos, estas nações que restam, bem como as nações que tenho destruído, desde o Jordão até o grande mar para o pôr-do-sol.'),
('acf','js',23,5,'E o Senhor vosso Deus as impelirá, e as expelirá de diante de vós; e vós possuireis a sua terra, como o Senhor vosso Deus vos tem prometido.'),
('acf','js',23,6,'Esforçai-vos, pois, muito para guardardes e para fazerdes tudo quanto está escrito no livro da lei de Moisés; para que dele não vos aparteis, nem para a direita nem para a esquerda;'),
('acf','js',23,7,'Para que não entreis no meio destas nações que ainda ficam convosco; e dos nomes de seus deuses não façais menção, nem por eles façais jurar, nem os sirvais, nem a eles vos inclineis,'),
('acf','js',23,8,'Mas ao Senhor vosso Deus vos apegareis, como fizestes até o dia de hoje;'),
('acf','js',23,9,'Pois o Senhor expulsou de diante de vós grandes e fortes nações; e, quanto a vós, ninguém vos tem podido resistir, até o dia de hoje.'),
('acf','js',23,10,'Um só homem dentre vós perseguirá a mil; pois é o Senhor vosso Deus que peleja por vós, como já vos tem falado.'),
('acf','js',23,11,'Portanto, guardai diligentemente as vossas almas, para amardes ao Senhor vosso Deus.'),
('acf','js',23,12,'Porque, se de algum modo vos desviardes, e vos apegardes ao restante destas nações que ainda ficou entre vós, e com elas vos aparentardes, e vós a elas entrardes, e elas a vós,'),
('acf','js',23,13,'Sabei certamente que o Senhor vosso Deus não continuará a expulsar estas nações de diante de vós, mas elas vos serão por laço e rede, e açoite às vossas ilhargas, e espinhos aos vossos olhos; até que pereçais desta boa terra que vos deu o Senhor vosso Deus.'),
('acf','js',23,14,'E eis que vou hoje pelo caminho de toda a terra; e vós bem sabeis, com todo o vosso coração, e com toda a vossa alma, que nem uma só palavra falhou de todas as boas coisas que falou de vós o Senhor vosso Deus; todas vos sobrevieram, nenhuma delas falhou.'),
('acf','js',23,15,'E será que, assim como sobre vós vieram todas estas boas coisas, que o Senhor vosso Deus vos disse, assim trará o Senhor sobre vós todas aquelas más coisas, até vos destruir de sobre a boa terra que vos deu o Senhor vosso Deus.'),
('acf','js',23,16,'Quando transgredirdes a aliança do Senhor vosso Deus, que vos tem ordenado, e fordes e servirdes a outros deuses, e a eles vos inclinardes, então a ira do Senhor sobre vós se acenderá, e logo perecereis de sobre a boa terra que vos deu.'),
('acf','js',24,1,'Depois reuniu Josué todas as tribos de Israel em Siquém; e chamou os anciãos de Israel, e os seus cabeças, e os seus juízes, e os seus oficiais; e eles se apresentaram diante de Deus.'),
('acf','js',24,2,'Então Josué disse a todo o povo: Assim diz o Senhor Deus de Israel: Além do rio habitaram antigamente vossos pais, Terá, pai de Abraão e pai de Naor; e serviram a outros deuses.'),
('acf','js',24,3,'Eu, porém, tomei a vosso pai Abraão dalém do rio e o fiz andar por toda a terra de Canaã; também multipliquei a sua descendência e dei-lhe a Isaque.'),
('acf','js',24,4,'E a Isaque dei Jacó e Esaú; e a Esaú dei a montanha de Seir, para a possuir; porém, Jacó e seus filhos desceram para o Egito.'),
('acf','js',24,5,'Então enviei Moisés e Arão e feri ao Egito, como o fiz no meio deles; e depois vos tirei de lá.'),
('acf','js',24,6,'E, tirando eu a vossos pais do Egito, viestes ao mar; e os egípcios perseguiram a vossos pais com carros e com cavaleiros, até ao Mar Vermelho.'),
('acf','js',24,7,'E clamaram ao Senhor, que pôs uma escuridão entre vós e os egípcios, e trouxe o mar sobre eles, e os cobriu, e os vossos olhos viram o que eu fiz no Egito; depois habitastes no deserto muitos dias.'),
('acf','js',24,8,'Então eu vos trouxe à terra dos amorreus, que habitavam além do Jordão, os quais pelejaram contra vós; porém os entreguei nas vossas mãos, e possuístes a sua terra, e os destruí de diante de vós.'),
('acf','js',24,9,'Levantou-se também Balaque, filho de Zipor, rei dos moabitas e pelejou contra Israel; e mandou chamar a Balaão, filho de Beor, para que vos amaldiçoasse.'),
('acf','js',24,10,'Porém eu não quis ouvir a Balaão; pelo que ele vos abençoou grandemente e eu vos livrei da sua mão.'),
('acf','js',24,11,'E, passando vós o Jordão, e vindo a Jericó, os habitantes de Jericó pelejaram contra vós, os amorreus, e os perizeus, e os cananeus, e os heteus, e os girgaseus, e os heveus, e os jebuseus; porém os entreguei nas vossas mãos.'),
('acf','js',24,12,'E enviei vespões adiante de vós, que os expulsaram de diante de vós, como a ambos os reis dos amorreus; não com a tua espada nem com o teu arco.'),
('acf','js',24,13,'E eu vos dei a terra em que não trabalhastes, e cidades que não edificastes, e habitais nelas e comeis das vinhas e dos olivais que não plantastes.'),
('acf','js',24,14,'Agora, pois, temei ao Senhor, e servi-o com sinceridade e com verdade; e deitai fora os deuses aos quais serviram vossos pais além do rio e no Egito, e servi ao Senhor.'),
('acf','js',24,15,'Porém, se vos parece mal aos vossos olhos servir ao Senhor, escolhei hoje a quem sirvais; se aos deuses a quem serviram vossos pais, que estavam além do rio, ou aos deuses dos amorreus, em cuja terra habitais; porém eu e a minha casa serviremos ao Senhor.'),
('acf','js',24,16,'Então respondeu o povo, e disse: Nunca nos aconteça que deixemos ao Senhor para servirmos a outros deuses;'),
('acf','js',24,17,'Porque o Senhor é o nosso Deus; ele é o que nos fez subir, a nós e a nossos pais, da terra do Egito, da casa da servidão, e o que tem feito estes grandes sinais aos nossos olhos, e nos guardou por todo o caminho que andamos, e entre todos os povos pelo meio dos quais passamos.'),
('acf','js',24,18,'E o Senhor expulsou de diante de nós a todos esses povos, até ao amorreu, morador da terra; também nós serviremos ao Senhor, porquanto é nosso Deus.'),
('acf','js',24,19,'Então Josué disse ao povo: Não podereis servir ao Senhor, porquanto é Deus santo, é Deus zeloso, que não perdoará a vossa transgressão nem os vossos pecados.'),
('acf','js',24,20,'Se deixardes ao Senhor, e servirdes a deuses estranhos, então ele se tornará, e vos fará mal, e vos consumirá, depois de vos ter feito o bem.'),
('acf','js',24,21,'Então disse o povo a Josué: Não, antes ao Senhor serviremos.'),
('acf','js',24,22,'E Josué disse ao povo: Sois testemunhas contra vós mesmos de que escolhestes ao Senhor, para o servir. E disseram: Somos testemunhas.'),
('acf','js',24,23,'Deitai, pois, agora, fora aos deuses estranhos que há no meio de vós, e inclinai o vosso coração ao Senhor Deus de Israel.'),
('acf','js',24,24,'E disse o povo a Josué: Serviremos ao Senhor nosso Deus, e obedeceremos à sua voz.'),
('acf','js',24,25,'Assim, naquele dia fez Josué aliança com o povo e lhe pôs por estatuto e direito em Siquém.'),
('acf','js',24,26,'E Josué escreveu estas palavras no livro da lei de Deus; e tomou uma grande pedra, e a erigiu ali debaixo do carvalho que estava junto ao santuário do Senhor.'),
('acf','js',24,27,'E disse Josué a todo o povo: Eis que esta pedra nos será por testemunho, pois ela ouviu todas as palavras, que o Senhor nos tem falado; e também será testemunho contra vós, para que não mintais a vosso Deus.'),
('acf','js',24,28,'Então Josué enviou o povo, cada um para a sua herança.'),
('acf','js',24,29,'E depois destas coisas sucedeu que Josué, filho de Num, servo do Senhor, faleceu, com idade de cento e dez anos.'),
('acf','js',24,30,'E sepultaram-no no termo da sua herança, em Timnate-Sera, que está no monte de Efraim, para o norte do monte de Gaás.'),
('acf','js',24,31,'Serviu, pois, Israel ao Senhor todos os dias de Josué, e todos os dias dos anciãos que ainda sobreviveram muito tempo depois de Josué, e que sabiam todas as obras que o Senhor tinha feito a Israel.'),
('acf','js',24,32,'Também os ossos de José, que os filhos de Israel trouxeram do Egito, foram enterrados em Siquém, naquela parte do campo que Jacó comprara aos filhos de Hemor, pai de Siquém, por cem peças de prata, e que se tornara herança dos filhos de José.'),
('acf','js',24,33,'Faleceu também Eleazar, filho de Arão, e o sepultaram no outeiro de Finéias, seu filho, que lhe fora dado na montanha de Efraim.')
